GimCorpus.put(103,0,[[1,1,"בִּשְׁנַת שָׁלוֹשׁ לְמַלְכוּת יְהוֹיָקִים. וְכִי אֶפְשָׁר לוֹמַר כֵּן? וַהֲלֹא הוּא מָלַךְ בִּשְׁנַת אַרְבַּע לִיהוֹיָקִים, שֶׁנֶּאֱמַר (ירמיהו כה:א) ״בַּשָּׁנָה הָרְבִעִית לִיהוֹיָקִים בֶּן יֹאשִׁיָּהוּ מֶלֶךְ יְהוּדָה הִיא הַשָּׁנָה הָרִאשׁוֹנָה לִנְבוּכַדְרֶאצַּר״. וּמַה תַּלְמוּד לוֹמַר בִּשְׁנַת שָׁלוֹשׁ? בִּשְׁנַת שָׁלוֹשׁ לְמִרְדּוֹ, שֶׁנֶּאֱמַר (מלכים ב כד:א) ״וַיְהִי לוֹ יְהוֹיָקִים עֶבֶד שָׁלֹשׁ שָׁנִים וַיָּשָׁב וַיִּמְרֹד בּוֹ״. שָׁלֹשׁ שָׁנִים וּבִשְׁנַת שָׁלֹשׁ עָלָה עָלָיו. וְהִיא שְׁנַת שְׁמוֹנֶה לִנְבוּכַדְנֶצַּר, דְּאָמַר מַר: שָׁנָה רִאשׁוֹנָה כָּבַשׁ נִינְוֵה, שְׁנִיָּה עָלָה וְכָבַשׁ יְהוֹיָקִים, וְשָׁלֹשׁ שָׁנִים עֲבָדוֹ וְשָׁלֹשׁ שָׁנִים מָרַד בּוֹ, וְהִיא הָיְתָה שְׁנַת אַחַת עֶשְׂרֵה לְמַלְכוּת יְהוֹיָקִים: חָמֵשׁ שָׁנִים קֹדֶם שֶׁכְּבָשׁוֹ וְשָׁלֹשׁ שֶׁעֲבָדוֹ וְשָׁלֹשָׁה שֶׁמָּרַד בּוֹ, וְאָז מֵת יְהוֹיָקִים תַּחַת יָדוֹ וְהִמְלִיךְ נְבוּכַדְנֶצַּר תַּחְתָּיו יְהוֹיָכִין בְּנוֹ:",1,0],[1,2,"וּמִקְצָת כְּלֵי בֵית הָאֱלֹהִים. לָקַח וּמִקְצָתָם נִשְׁאֲרוּ, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהו כז:יט): ״כֹּה אָמַר ה׳ צְבָאוֹת אֶל הָעַמּוּדִים וְעַל הַיָּם וְעַל הַמְּכֹנוֹת וְעַל יֶתֶר הַכֵּלִים הַנּוֹתָרִים בָּעִיר הַזֹּאת״:",1,0],[1,2,"וַיְבִיאֵם אֶרֶץ שִׁנְעָר בֵּית אֱלֹהָיו. לְקַלֵּס לַעֲבוֹדַת כּוֹכָבִים שֶׁלּוֹ הֵבִיא שָׁם אֶת הַשִּׁבְיָה כֻּלָּהּ, אַף אֶת הָאֲנָשִׁים, וְאֶת הַכֵּלִים הֵבִיא אַחַר כָּךְ בֵּית הָאוֹצָר:",2,0],[1,3,"הַפַּרְתְּמִים. דּוּכָסִים:",1,0],[1,4,"וַאֲשֶׁר כֹּחַ בָּהֶם. פֵּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה שֶׁיִּהְיוּ אוֹנְסִין עַצְמָן מִן הַשְּׂחוֹק וּמִן הַשִּׂיחָה וּמִן הַשֵּׁנָה מִפְּנֵי אֵימַת מַלְכוּת וְשֶׁמַּעֲמִידִים עַצְמָן כְּשֶׁנִּצְרָכִים לִנְקָבֵיהֶם (סנהדרין צג:):",1,0],[1,4,"וּלְלַמְּדָם סֵפֶר. מוּסָב עַל אֲשֶׁר כֹּחַ בָּהֶם:",2,0],[1,5,"וַיְמַן. לְשׁוֹן הַזְמָנָה:",1,0],[1,5,"מִפַּת בַּג. הוּא שֵׁם מַאֲכַל הַמֶּלֶךְ בִּלְשׁוֹן כַּשְׂדִּים. וְיֵשׁ פּוֹתְרִים פַּת בַּג לֶחֶם, וְאֵין נִרְאֶה כֵּן, שֶׁהֲרֵי כְּתִיב ״וַיְהִי הַמֶּלְצַר נֹשֵׂא אֶת פַּת בָּגָם וְנֹתֵן לָהֶם זֵרְעוֹנִים״ (דניאל א:טז), וְאֵין זֵרְעוֹנִים חֲלִיפֵי לֶחֶם אֶלָּא חֲלִיפֵי תַבְשִׁיל:",2,0],[1,7,"בֵּלְטְשַׁאצַּר. עַל שֵׁם עֲבוֹדַת כּוֹכָבִים שֶׁל בָּבֶל שֶׁקְּרוּיָה בֵּל, שֶׁנֶּאֱמַר ״דִּי שְׁמֵהּ בֵּלְטְשַׁאצַּר כְּשׁוּם אֱלָהִי״ (דניאל ד:ה). בֵּלְטְשַׁאצַּר שֵׁם לְשׁוֹן חָכְמָה בִּלְשׁוֹן אֲרַמִּי:",1,0],[1,8,"יִתְגָּאַל. לְשׁוֹן לִכְלוּךְ:",1,0],[1,9,"שַׂר הַסָּרִיסִים. שֶׁהָיָה שַׂר עַל מְשָׁרְתֵי הַמֶּלֶךְ:",1,0],[1,10,"אֲשֶׁר מָנָה. אֲשֶׁר הִזְמִין וְסִפֵּק:",1,0],[1,10,"כְּגִילְכֶם. דּוּגְמַתְכֶם, וּלְשׁוֹן מִשְׁנָה הוּא: בֶּן גִּילוֹ (סנהדרין לז:):",2,0],[1,10,"וְחִיַּבְתֶּם אֶת רֹאשִׁי לַמֶּלֶךְ. תִּגְרְמוּ לִי לְהִתְחַיֵּב לְהַתִּיז רֹאשִׁי:",3,0],[1,11,"הַמֶּלְצַר. הַסּוֹדֵר אֶת הַמָּנוֹת וְאֶת הַקְּעָרוֹת שֶׁקּוֹרִין מאישטרי״ב אל״ה:",1,0],[1,12,"נַס. לְשׁוֹן נִסָּיוֹן:",1,0],[1,12,"מִן הַזֵּרֹעִים. מִין קִטְנִיּוֹת, תַּחַת פַּת בַּג (לעיל ח):",2,0],[1,13,"וְכַאֲשֶׁר תִּרְאֵה. לְפִי מַה שֶּׁתִּרְאֶה עֲשֵׂה:",1,0],[1,16,"נוֹשֵׂא אֶת פַּת בָּגָם. נוֹטְלוֹ לְעַצְמוֹ:",1,0],[1,18,"אֲשֶׁר אָמַר הַמֶּלֶךְ לַהֲבִיאָם. שֶׁיָּבֹאוּ לְפָנָיו:",1,0],[1,20,"הַחַרְטֻמִּים. אֵלּוּ שֶׁשּׁוֹאֲלִים בְּטִימֵי מֵתִים, בְּעַצְמוֹת מֵתִים, כְּמָה דְאַתְּ אָמַר: שְׁחִיק עַצְמוֹת, שְׁחִיק טַמְיָא:",1,0],[1,20,"הָאַשָּׁפִים. אֵלּוּ שֶׁדּוֹחֲקִים בַּמַּזָּל, כָּךְ מְפֹרָשׁ בְּתַנְחוּמָא (תנחומא מקץ ב):",2,0],[1,21,"וַיְהִי דָנִיֵּאל. בִּגְדֻלָּה בְּבָבֶל עַד שְׁנַת אַחַת לְכוֹרֶשׁ הַמֶּלֶךְ. לְדִבְרֵי הָאוֹמֵר הֲתָךְ זֶה דָנִיֵּאל (מגילה טו.), וְלָמָּה נִקְרָא שְׁמוֹ הֲתָךְ שֶׁחֲתָכוּהוּ מִגְּדֻלָּתוֹ, צְרִיכִין אָנוּ לוֹמַר שֶׁזֶּהוּ כּוֹרֶשׁ הָרִאשׁוֹן שֶׁלִּפְנֵי אֲחַשְׁוֵרוֹשׁ. וּלְדִבְרֵי הָאוֹמֵר שֶׁכָּל דִּבְרֵי מַלְכוּת נֶחְתָּכִין עַל פִּיו, נֹאמַר כּוֹרֶשׁ זֶה הוּא דָּרְיָוֶשׁ הַשֵּׁנִי אַחַר אֲחַשְׁוֵרוֹשׁ, וּבִימֵי דָּרְיָוֶשׁ הַמָּדִי שֶׁהִשְׁלִיכוּ לְגוֹב אֲרָיוֹת לֹא יָרַד מִגְּדֻלָּתוֹ, שֶׁנֶּאֱמַר (דניאל ו:כט) ״וְדָנִיֵּאל דְּנָה הַצְלַח בְּמַלְכוּת דָּרְיָוֶשׁ וּבְמַלְכוּת כּוֹרֶשׁ פַּרְסָאָה״, לָמַדְנוּ שֶׁבִּימֵי כּוֹרֶשׁ הָרִאשׁוֹן הָיָה בִּגְדֻלָּה:",1,0],[2,1,"וּבִשְׁנַת שְׁתַּיִם לְמַלְכוּת נְבוּכַדְנֶצַּר. אִי אֶפְשָׁר לוֹמַר כֵּן, אֶלָּא בִּשְׁנַת שְׁתַּיִם לְחֻרְבַּן הַבַּיִת; כָּךְ שְׁנוּיָה בְּסֵדֶר עוֹלָם (פרק כח). וּקְרָאוֹ לְמַלְכוּת נְבוּכַדְנֶצַּר, עַל שֶׁהֶרְאָה זְדוֹנוֹ לִכָּנֵס לְתוֹךְ דְּבִיר מַלְכּוֹ שֶׁל עוֹלָם:",1,0],[2,1,"וַתִּתְפָּעֶם רוּחוֹ. בְּפַרְעֹה נֶאֱמַר ״וַתִּפָּעֶם רוּחוֹ״ (בראשית מא:ח) שֶׁלֹּא נֶעְלַם מִמֶּנּוּ אֶלָּא פִּתְרוֹן הַחֲלוֹם, וְכָאן שֶׁנֶּעְלַם מִמֶּנּוּ גַּם הַחֲלוֹם נִכְפְּלָה הַלָּשׁוֹן וַתִּתְפָּעֶם. לְשׁוֹן פְּעִימָה וַהֲלִימָה, (וּבַחוּמָּשׁ פֵּרֵשׁ רַשִׁ״י זַ״ל לְשׁוֹן נְקִיפָה):",2,0],[2,1,"נִהְיְתָה עָלָיו. לְשׁוֹן שִׁבָּרוֹן, כְּמוֹ ״הוֹוָה עַל הוֹוָה״ (יחזקאל ו:יא):",3,0],[2,4,"לְעָלְמִין חֱיִי. לְעוֹלָם יִחְיֶה:",1,0],[2,4,"אֱמַר חֶלְמָא לְעַבְדָּךְ. אֱמוֹר הַחֲלוֹם לְעַבְדֶּךָ:",2,0],[2,5,"מִלְּתָא מִנִּי אַזְדָּא. הַדָּבָר מִמֶּנִּי הָלַךְ׃",1,0],[2,5,"הֵן לָא תְהוֹדְעוּנַּנִי חֶלְמָא וּפִשְׁרֵהּ. אִם לֹא תוֹדִיעוּנִי הַחֲלוֹם וּפִתְרוֹנוֹ:",2,0],[2,5,"הַדָּמִין תִּתְעַבְדוּן. לְאֵבָרִים תִּתְחַתְּכוּ, וְהַרְבֵּה יֵשׁ בַּגְּמָרָא הַדּוֹמֵי הַדְמוּהָ בְּמַסֶּכֶת גִּטִּין (גיטין סז:):",3,0],[2,5,"נְוָלִי. אַשְׁפָּה:",4,0],[2,5,"יִתְּשָׂמוּן. לְשׁוֹן ״וַיָּשֶׂם״ (דניאל א:ב), יְהוֹן שׂוּמוֹת לְאַשְׁפּוֹת:",5,0],[2,6,"וְהֵן. וְאִם:",1,0],[2,6,"וּנְבִזְבָּה. דּוֹרְנוֹת:",2,0],[2,6,"לָהֵן. אַךְ:",3,0],[2,6,"הַחֲוֺנִי. תַּגִּידוּ לִי:",4,0],[2,7,"תִּנְיָנוּת. שֵׁנִית:",1,0],[2,7,"נְהַחֲוֵה. נַגִּיד:",2,0],[2,8,"מִן יַצִּיב יָדַע אֲנָה. בֶּאֱמֶת יוֹדֵעַ אֲנִי:",1,0],[2,8,"יַצִּיב. דָּבָר אֱמֶת וְיַצִּיב:",2,0],[2,8,"דִּי עִדָּנָא אַנְתּוּן זָבְנִין. אֲשֶׁר זוֹ הַשָּׁעָה אַתֶּם מְסוּרִים לַמָּוֶת:",3,0],[2,8,"כָּל קֳבֵל דִּי חֲזֵיתוֹן. כָּל כְּנֶגֶד שֶׁאַתֶּם רוֹאִים שֶׁהָלַךְ מִמֶּנִּי הַדָּבָר וְאַתֶּם כּוֹפְלִים לִי לְהַגִּיד לָכֶם:",4,0],[2,9,"דִּי הֵן חֶלְמָא לָא תְהוֹדְעֻנַּנִי. שֶׁאִם הַחֲלוֹם וּפִתְרוֹנוֹ לֹא תוֹדִיעוּנִי, אַחַת הִיא דָתְכֶם לָמוּת:",1,0],[2,9,"וּמִלָּה כִדְבָה וּשְׁחִיתָה הִזְדַּמִּנְתּוּן. אוֹ אִם דָּבָר כָּזָב וְנִשְׁחָת תָּכִינוּ עַצְמְכֶם לוֹמַר לְפָנַי:",2,0],[2,9,"עַד דִּי עִדָּנָא יִשְׁתַּנֵּא. עַד אֲשֶׁר יִשְׁתַּנֶּה הָעֵת, כְּלוֹמַר: קֹדֶם נְטוֹת צִלְלֵי עֶרֶב (ירמיה ו:ד), שֶׁיִּשְׁתַּנֶּה מוֹעֵד הַבֹּקֶר:",3,0],[2,9,"עַד דִּי עִדָּנָא יִשְׁתַּנֵּא. לְשׁוֹן גְּעָרָה וְגִזּוּם הוּא. כָּךְ יֵעָנֵשׁ, וְהָעֹנֶשׁ כְּבָר פֵּרֵשׁ לְמַעְלָה. וְדוּגְמָתוֹ ״לָכֵן כָּל הֹרֵג קַיִן״ (בראשית ד:טו):",4,0],[2,9,"לָהֵן. אַךְ הַחֲלוֹם אִמְרוּ לִי מַה חָלַמְתִּי, וְאֵדַע כָּל שֶׁכֵּן שֶׁהַפִּתְרוֹן תַּגִּידוּ:",5,0],[2,10,"דִּי מִלַּת מַלְכָּא. אֲשֶׁר דְּבַר הַמֶּלֶךְ יוּכַל לְהַגִּיד:",1,0],[2,10,"כָּל קֳבֵל. כָּל כְּנֶגֶד, כְּלוֹמַר: תְּשׁוּבָתֵנוּ זוֹ אֱמֶת הִיא, לְעֻמַּת שֶׁלֹּא הָיָה מֶלֶךְ מֵעוֹלָם שֶׁשָּׁאַל דָּבָר כָּזֶה:",2,0],[2,10,"מִלָּה כִדְנָה. דָּבָר כָּזֶה:",3,0],[2,10,"וְאָשַׁף. הַדּוֹחֵק בַּמַּזָּל:",4,0],[2,11,"יַקִּירָה. כְּבֵדָה, וּמַשָּׂאָהּ כָּבֵד:",1,0],[2,11,"וְאָחֳרָן לָא אִיתַי דִּי יְחַוִּנַּהּ. וְאַחֵר אֵין אֲשֶׁר יַגִּידֶהָ:",2,0],[2,11,"לָהֵן אֱלָהִין. אַךְ הַמַּלְאָכִים אֲשֶׁר מְדוֹרָם עִם בָּשָׂר וָדָם אֵינֶנּוּ:",3,0],[2,11,"מְדָרְהוֹן. מְגוּרֵיהוֹן. וּמִדְרַשׁ רַבִּי תַּנְחוּמָא וְאָחֳרָן לָא אִיתַי וְאַהֲרֹן לָא אִיתַי כֹּהֵן הַלּוֹבֵשׁ אוּרִים וְתֻמִּים אֵינוֹ כָאן שֶׁיַּגִּיד לְךָ. אָמַר לָהֶם: כָּל כָּךְ הָיָה כֹּחַ בְּאוֹתוֹ בַּיִת וּנְתַתֶּם לִי עֵצָה לְהַחֲרִיבוֹ?! מִיָּד כָּעַס וְצִוָּה לְהָרְגָן:",4,0],[2,12,"כָּל קֳבֵל דְּנָה. לְעֻמַּת הַתְּשׁוּבָה הַזֹּאת:",1,0],[2,12,"מַלְכָּא בְּנַס וּקְצַף שַׂגִּיא. הָיָה הַמֶּלֶךְ בְּזַעַף וְקֶצֶף גָּדוֹל:",2,0],[2,12,"בְּנַס. בְּזַעַף, ״וְהִנָּם זֹעֲפִים״ (בראשית מ:ו) תִּרְגֵּם אוּנְקְלוֹס: ״וְהָא אִינּוּן נְסִיסִין״:",3,0],[2,12,"וַאֲמַר לְהוֹבָדָה. וַיֹּאמֶר לְהַאֲבִיד, וָי״ו שֶׁל וַאֲמַר נִתְעַצְּמוּ בּוֹ מְנַחֵם וְדוּנָ״שׁ, מְנַחֵם דָּחַק עַצְמוֹ לָתֵת בֵּי״ת שֶׁל בְּנַס בִּיסוֹד הַתֵּיבָה וְלֹא פָּתַר בְּנַס וּקְצַף לְשׁוֹן שְׁמוֹת דְּבָרִים אֶלָּא לְשׁוֹן פֹּעַל רָגַז וְקָצַף הַרְבֵּה, וְאָמַר לְהַאֲבִיד וָי״ו שֶׁבְּוַאֲמַר דְּחָקוֹ לִפְתֹּר כֵּן, וְדוּנָשׁ אָמַר אִי אֶפְשָׁר לִהְיוֹת בֵּי״ת בְּנַס יְסוֹד בַּתֵּיבָה אֶלָּא שֵׁם דָּבָר הוּא, וְכֵן פָּתְרוֹ בְּזַעַף וְקֶצֶף גָּדוֹל אָמַר לְהַאֲבִיד, וְשָׁם הַוָּי״ו טְפֵלָה וִיתֵרָה כְּמוֹ וָי״ו שֶׁל ״וְרֶכֶב וָסוּס״ (תהלים עו:ז). וַאֲנִי אוֹמֵר אֵין הַוָּי״ו דְּחוּקָה לִהְיוֹת טְפֵלָה וִיתֵרָה כִּי כֵּן פִּתְרוֹנוֹ מַלְכָּא בְּנַס וּקְצַף שַׂגִּיא הַמֶּלֶךְ נִהְיָה בְּזַעַף וְקֶצֶף גָּדוֹל וְאָמַר בְּזַעְפּוֹ לְהַאֲבִידָם וּמִן הַמִּקְרָאוֹת קִצְרֵי לָשׁוֹן הִיא:",4,0],[2,13,"וְדָתָא נֶפְקַת. דַּת הַמֶּלֶךְ וּגְזֵרָתוֹ יָצָא בַּמְּדִינָה:",1,0],[2,13,"וּבְעוֹ דָנִיֵּאל וְחַבְרוֹהִי לְהִתְקְטָלָה. וְנִתְבַּקְשׁוּ דָנִיֵּאל וַחֲבֵרָיו לֵיהָרֵג:",2,0],[2,14,"בֵּאדַיִן. תַּרְגּוּם שֶׁל אָז:",1,0],[2,14,"הֲתִיב עֵטָא וּטְעֵם לְאַרְיוֹךְ. הֵשִׁיב עֵצָה וְטַעַם לְאַרְיוֹךְ שֵׁם הָאִישׁ:",2,0],[2,14,"רַב טַבָּחַיָּא. שַׂר הַהוֹרְגִים הַמְחֻיָּבִים הֲרִיגָה:",3,0],[2,15,"עַל מָה דָּתָא מְהַחְצְפָה. מָה זֶּה שֶׁדַּת הַמֶּלֶךְ חֲצוּפָה לַהֲרוֹג?",1,0],[2,15,"אֱדַיִן מִלְּתָא הוֹדַע אֲרְיוֹךְ לְדָנִיֵּאל. שֶׁקָּצַף הַמֶּלֶךְ עַל שֶׁאֵין מַגִּיד חֲלוֹמוֹ:",2,0],[2,16,"עַל וּבְעָא. נִכְנַס וּבִקֵּשׁ׃",1,0],[2,16,"יִנְתִּן לֵיהּ. יִתֵּן לוֹ:",2,0],[2,19,"רָזָא גְלִי. בְּסֵתֶר נִגְלָה:",1,0],[2,21,"מְהַשְׁנֵא. מְחַלִּיף:",1,0],[2,21,"מְהַעְדֵּה. מֵסִיר מַלְכִין. עַל שֶׁהֵבִין מִתּוֹךְ הַחֲלוֹם שֶׁמַּלְכוּת נְבוּכַדְנֶצַּר פּוֹסֶקֶת וּמַלְכוּת אַחֶרֶת עוֹמֶדֶת:",2,0],[2,22,"הוּא גָּלֵא עַמִּיקָתָא. גּוֹלֶה עֲמוּקוֹת:",1,0],[2,22,"וּמְסַתְּרָתָא. עַל שֶׁגִּלָּה לוֹ עֹמֶק זֶה:",2,0],[2,23,"הוֹדַעְתֶּנָא. הוֹדַעְתַּנִי:",1,0],[2,24,"כָּל קֳבֵל דְּנָה. כָּל עוּמַּת זֶה שֶׁנִּגְלָה לוֹ הַסּוֹד:",1,0],[2,24,"דָּנִיֵּאל עַל עַל אַרְיוֹךְ. נִכְנַס אֵצֶל אַרְיוֹךְ:",2,0],[2,24,"דִּי מַנִּי. שֶׁהִפְקִיד:",3,0],[2,24,"אַל תְּהוֹבֵד. אַל תְּאַבֵּד:",4,0],[2,24,"הַעֵלְנִי. הַכְנִיסֵנִי:",5,0],[2,25,"אֱדַיִן. אָז:",1,0],[2,25,"בְּהִתְבְּהָלָה. בְּבֶהָלָה, כְּלוֹמַר: בִּמְהִירוּת:",2,0],[2,25,"הַנְעֵל. הִכְנִיס אֶת דָּנִיֵּאל:",3,0],[2,25,"דִּי הַשְׁכַּחַת גְּבַר. אֲשֶׁר מָצָאתִי אִישׁ׃",4,0],[2,25,"גָּלוּתָא דִּי יְהוּד. גָּלוּת יְהוּדָה:",5,0],[2,26,"הַאִיתָךְ כֹּהֵל. הֲיֶשְׁךָ יָכוֹל?",1,0],[2,26,"דִּי חֲזֵית. אֲשֶׁר רָאִיתִי׃",2,0],[2,27,"גָּזְרִין. שֵׁם מִין בַּעַל כִּשּׁוּף:",1,0],[2,28,"בְּרַם אִיתַי וְגוֹ׳: וְהוֹדַע לְמַלְכָּא וְגוֹ׳. הוּא גִּלָּה לִי רָז זֶה, וְעַל יָדוֹ הוֹדִיעַ לַמֶּלֶךְ עִקַּר חֲלוֹמוֹ בָּעֲתִידוֹת:",1,0],[2,28,"חֶלְמָךְ וְחֶזְוֵי רֵאשָׁךְ עַל מִשְׁכְּבָךְ. אֲשֶׁר עַל מִשְׁכְּבָךְ זֶהוּ:",2,0],[2,29,"רַעְיוֹנָךְ. הִרְהוּרְךָ:",1,0],[2,29,"עַל מִשְׁכְּבָךְ סְלִיקוּ. מָה שֶׁהָיִיתָ מְהַרְהֵר בַּיּוֹם מָה יִהְיֶה אַחֲרֶיךָ, עַל מִשְׁכָּבְךָ עָלוּ:",2,0],[2,29,"וְגָלֵא רָזַיָּא הוֹדְעָךְ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה רָזִים הוֹדִיעֲךָ אֶת אֲשֶׁר יִהְיֶה:",3,0],[2,30,"וַאֲנָה לָא בְחָכְמָה. וַאֲנִי לֹא מֵרוֹב הַחָכְמָה שֶׁיֵּשׁ בִּי מִשְּׁאָר הַבְּרִיּוֹת יוֹתֵר נִגְלָה לִי הַסּוֹד הַזֶּה:",1,0],[2,30,"לָהֵן עַל דִּבְרַת דִּי פִשְׁרָא לְמַלְכָּא יְהוֹדְעוּן. יוֹדִיעוּךָ מִן הַשָּׁמַיִם:",2,0],[2,30,"וְרַעְיוֹנֵי לִבְבָךְ תִּנְדַּע. וְהִרְהוּרֵי לְבָבְךָ שֶׁאַתָּה מְהַרְהֵר תָּמִיד לָדַעַת מִי יָקוּם אַחֲרֶיךָ:",3,0],[2,30,"תִּנְדַּע. תֵּדַע:",4,0],[2,31,"חָזֵה הֲוַיְתָ. רוֹאֶה הָיִיתָ:",1,0],[2,31,"וַאֲלוּ. לְשׁוֹן וְהִנֵּה:",2,0],[2,31,"צַלְמָא דִּכֵּן רַב. צֶלֶם אֲשֶׁר הָיָה לוֹ כַּן גָּדוֹל:",3,0],[2,31,"וְזִיוֵהּ יַתִּיר קָאֵם לְקָבְלָךְ. הָיָה עוֹמֵד לְנֶגְדְּךָ:",4,0],[2,31,"וְרֵוֵהּ דְּחִיל. וְתָאֳרוֹ נוֹרָא:",5,0],[2,32,"דִּי דְהַב טָב. שֶׁל זָהָב טוֹב׃",1,0],[2,32,"חֲדוֹהִי. חָזֶה שֶׁלּוֹ:",2,0],[2,32,"וּדְרָעוֹהִי. וּזְרוֹעוֹתָיו:",3,0],[2,32,"מְעוֹהִי וְיַרְכָתֵהּ. בִּטְנוֹ וִירֵכוֹתָיו:",4,0],[2,33,"שָׁקוֹהִי דִּי פַרְזֶל. שׁוֹקָיו שֶׁל בַּרְזֶל:",1,0],[2,33,"מִנְּהֵין דִּי פַרְזֶל וּמִנְּהֵן דִּי חֲסַף. מֵהֶם שֶׁל בַּרְזֶל וּמֵהֶם שֶׁל חֶרֶס:",2,0],[2,34,"דִּי הִתְגְּזֶרֶת אֶבֶן. אֲשֶׁר נֶחְתְּכָה וְנִבְדְּלָה אֶבֶן אַחַת:",1,0],[2,34,"דִּי לָא בִידַיִן. אֲשֶׁר לֹא בְיָדַיִם, כִּי אִם מֵאֵילֶיהָ:",2,0],[2,34,"וּמְחָת לְצַלְמָא. וְהִכִּיתָ אֶת הַצֶּלֶם:",3,0],[2,34,"וְהַדֵּקֶת הִמּוֹן. וְהִדִּיקָה אוֹתָם:",4,0],[2,35,"בֵּאדַיִן דָּקוּ כַחֲדָה. אָז הוּדְקוּ יַחַד כָּל מִינֵי מַתָּכוֹת וְחֶרֶס שֶׁהָיָה בּוֹ:",1,0],[2,35,"וַהֲווֹ כְּעוּר מִן אִדְּרֵי קַיִט. וְהָיוּ כְּמוֹץ מִגָּרְנוֹת הַקַּיִץ:",2,0],[2,35,"וּנְשָׂא הֲמוֹן רוּחָא. וְתִשָּׂא אוֹתָם הָרוּחַ:",3,0],[2,35,"וְכָל אֲתַר לָא הִשְׁתְּכַח לְהוֹן. כְּלוֹמַר: לֹא נוֹדַע מְקוֹמָהּ הָרִאשׁוֹן, וְלֹא נִכָּר שֶׁהָיוּ שָׁם מֵעוֹלָם:",4,0],[2,35,"הֲוָת לְטוּר רַב. נַעֲשֵׂית הַר גָּדוֹל:",5,0],[2,36,"דְּנָה חֶלְמָא. הֲרֵי זֶה הַחֲלוֹם שֶׁחָלַמְתָּ:",1,0],[2,36,"וּפִשְׁרֵיהּ נֵאמַר וְגוֹ׳. וּפִתְרוֹנוֹ נֹאמַר לָךְ:",2,0],[2,37,"מֶלֶךְ מַלְכַיָּא. פֵּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה: כָּל מֶלֶךְ מַלְכַיָּא דְּדָנִיֵּאל מֶלֶךְ בָּשָׂר וָדָם, חוּץ מִזֶּה, שֶׁכְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר (שבועות לה:). וְכֵן פִּתְרוֹנוֹ: מֶלֶךְ הַמְּלָכִים שֶׁהוּא אֱלֹקֵי הַשָּׁמַיִם:",1,0],[2,37,"מַלְכוּתָא חִסְנָא. מַלְכוּת חָזָק וְכָבֵד נָתַן לְךָ׃",2,0],[2,38,"וְהַשְׁלְטָךְ בְּכָלְהוֹן. וְהִשְׁלִיטְךָ עַל כֻּלָּם, שֶׁאֲפִלּוּ גּוֹזֵר עַל הַסּוּס לֹא יְהֵא צוֹנֵף, וְעַל הָעוֹף לֹא יִפְרַח, כְּמוֹ שֶׁנֶּאֱמַר ״וְאֶת חַיַּת הַשָּׂדֶה נָתַתִּי לְעָבְדוֹ״ (ירמיה כז:ו):",1,0],[2,38,"אַנְתְּ הוּא רֵאשָׁה דִּי דַהֲבָא. רֹאשׁ הַזָּהָב שֶׁל הַצּוּרָה שֶׁרָאִיתָ אַתָּה הוּא, שֶׁמַּלְכוּתְךָ חֲזָקָה וְעַתָּה קַיֶּמֶת, וְהִיא חֲשׁוּבָה מְאֹד:",2,0],[2,39,"וּבָתְרָךְ תְּקוּם מַלְכוּ אָחֳרִי אֲרַע מִנָּךְ. וְאַחֲרֶיךָ, אַחַר מַלְכוּת בֵּלְשַׁצַּר בִּנְךָ, תָּקוּם מַלְכוּת שֶׁתִּטֹּל הַשְּׂרָרָה מִזַּרְעֲךָ, נְמוּכָה וּשְׁפֵלָה מִמַּלְכוּת שֶׁלְּךָ:",1,0],[2,39,"אֲרַע. תַּחְתּוֹנָה וּנְמוּכָה, כְּמוֹ שֶׁהַכֶּסֶף נָמוּךְ וְשָׁפָל מֵהַזָּהָב, וְרָאִיתָ שֶׁהֶחָזֶה שֶׁהִיא אַחַר הָרֹאשׁ הִיא שֶׁל כֶּסֶף, כָּךְ תְּהֵא מַלְכוּת מָדַי וּפָרַס אַחַר מַלְכוּת בָּבֶל שְׁפָלָה מִמַּלְכוּת נְבוּכַדְנֶצַּר:",2,0],[2,39,"וּמַלְכוּ תְּלִיתָאָה אָחֳרִי. אַחֶרֶת:",3,0],[2,39,"דִּי נְחָשָׁא. חֲסִינָא כִּנְחֹשֶׁת, וְהִיא מַלְכוּת יָוָן מַלְכוּת אֲלֶכְּסַנְדְּרוֹס מוֹקְדָן:",4,0],[2,40,"וּמַלְכוּ רְבִיעָאָה. הִיא קָשָׁה כְּפַרְזְלָא, כַּאֲשֶׁר רָאִיתָ הַשּׁוֹקַיִם שֶׁהֵם רְבִיעִים לָרֹאשׁ וְלֶחָזֶה וְלַמֵּעַיִם וְהֵם שֶׁל בַּרְזֶל:",1,0],[2,40,"מְהַדֵּק וְחָשֵׁל כֹּלָּא. מְרַדֵּד וּמְהַדֵּק כָּל מִינֵי מַתָּכוֹת שֶׁמְּרַדְּדִין אוֹתָם בְּקוּרְנָס:",2,0],[2,40,"וְחָשֵׁל. וּמְרַדֵּד, וְהַרְבֵּה יֵשׁ בַּגְּמָרָא: חַשְּׁלֵי דּוּדֵי (כתובות עז.), בֵּיעֵי חֲשִׁילְתָא (חולין צב.):",3,0],[2,40,"כָּל אִלֵּין. כָּל מִינֵי מַתָּכוֹת הַלָּלוּ שֶׁרָאִיתָ בַּצֶּלֶם:",4,0],[2,40,"תַּדִּיק וְתֵרֹעַ. תַּדִּיק וּתְרוֹצֵץ:",5,0],[2,41,"חֲסַף דִּי פֶחָר. חֶרֶס שֶׁל יוֹצֵר, וְהַרְבֵּה יֵשׁ בַּגְּמָרָא מָאנֵי דְפַחְרָא (תענית ז.):",1,0],[2,41,"מַלְכוּ פְלִיגָה תֶהֱוֵה. מַלְכוּת חֲלוּקָה תִּהְיֶה, שְׁנֵי מְלָכִים יִהְיוּ מִמֶּנָּה כְּאֶחָד, חָזָק וְחַלָּשׁ, כְּמוֹ שֶׁמְפֹרָשׁ לְמַטָּה מִן קְצָת מַלְכוּתָא תֶהֱוֵה תַקִּיפָא:",2,0],[2,41,"וּמִן נִצְבְּתָא דִי פַרְזְלָא לֶהֱוֵא בַהּ. אַף הַחַלָּשׁ יְהֵא חָזָק עַל אֲחֵרִים עַל יְדֵי חוֹזֶק חֲבֵרוֹ, שֶׁיִּירְאוּ מִפָּנָיו. וְזֶה מִן נִצְבְּתָא דִי פַרְזְלָא לֶהֱוֵא בַהּ, מִן חוֹזֶק מַצַּב הַבַּרְזֶל, יִהְיֶה בַּמֶּלֶךְ הַחַלָּשׁ:",3,0],[2,41,"כָּל קֳבֵל דִּי חֲזַיְתָה. כָּל־עוּמַּת שֶׁרָאִיתָ בַּרְזֶל מְעֹרָב בַּחֲרָסִית הַטִּיט:",4,0],[2,43,"מִתְעָרְבִין לֶהֱוֺן בִּזְרַע אֲנָשָׁא וְגוֹ׳. מִתְחַתְּנִים יִהְיוּ עִם שְׁאָר הָאֻמּוֹת, וְלֹא יִהְיוּ שְׁלֵמִים וְנִדְבָּקִים עִמָּם בֶּאֱמֶת וְלֵב שָׁלֵם, וְדָתֵיהֶם שׁוֹנוֹת מִדָּתֵי שְׁאָר הָאֻמּוֹת:",1,0],[2,43,"הָא כְּדִי פַרְזְלָא לָא מִתְעָרַב. הֲלֹא הוּא כְּמוֹ שֶׁאֵין הַבַּרְזֶל נִדְבָּק יָפֶה עִם הַחֶרֶס:",2,0],[2,44,"וּבְיוֹמֵיהוֹן דִּי מַלְכַיָּא אִנּוּן. בִּיוֹמֵיהוֹן שֶׁל מְלָכִים הַלָּלוּ, בְּעוֹד מַלְכוּתָם שֶׁל רוֹמִיִּים קַיֶּמֶת:",1,0],[2,44,"יְקִים אֱלָהּ שְׁמַיָּא. מַלְכוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלְּעוֹלָם לֹא תִתְחַבַּל מַלְכוּ, וְהִיא מַלְכוּת מֶלֶךְ הַמָּשִׁיחַ:",2,0],[2,44,"תַּדִּק וְתָסֵף. תַּדִּק וּתְכַלֶּה כָּל אֵלּוּ הַמַּלְכֻיּוֹת:",3,0],[2,45,"כָּל קֳבֵל דִּי חֲזַיְתָ. כָּל עוּמַּת שֶׁרָאִיתָ שֶׁנִּתְפָּרְקָה אֶבֶן מִן הָהָר שֶׁהִדִּיקָה כָּל הַצֶּלֶם, זֶה פִּתְרוֹן שֶׁהַמַּלְכוּת הַחֲמִישִׁית תְּכַלֶּה וּתְרוֹצֵץ אֶת כֻּלָּם:",1,0],[2,45,"מָה דִּי לֶהֱוֵא אַחֲרֵי דְנָה. מַה שֶׁיִּהְיֶה אַחַר זֹאת, אַחַר מַלְכוּת זוֹ שֶׁלְּךָ:",2,0],[2,45,"וְיַצִּיב חֶלְמָא. אֱמֶת הוּא הַחֲלוֹם:",3,0],[2,46,"אֲמַר לְנַסָּכָה. רָצָה לַעֲשׂוֹתוֹ אֱלוֹהַּ:",1,0],[2,47,"מִן קְשׁוֹט. בֶּאֱמֶת:",1,0],[2,47,"וּמָרֵא מַלְכִין. אֲדוֹנֵי הָאֲדוֹנִים:",2,0],[2,47,"רָזָא דְנָה. סֵתֶר זֶה:",3,0],[2,48,"לְדָנִיֵּאל רַבִּי. לְדָנִיֵּאל גָּדַל עַל כָּל הַשָּׂרִים:",1,0],[2,49,"וּמַנִּי עַל עֲבִידְתָּא דִּי מְדִינַת בָּבֶל. וַיַּפְקֵד עַל כָּל צָרְכֵי הַמַּמְלָכוֹת אֶת חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה:",1,0],[3,1,"עֲבַד וְגוֹ׳. מָלְאָה לִבּוֹ לַעֲשׂוֹת צֶלֶם שֶׁל זָהָב:",1,0],[3,1,"פְּתָיֵהּ אַמִּין שִׁת אֲקִימֵהּ וְגוֹ׳. אִם אֵין עָבְיוֹ אֶלָּא שֵׁשׁ, הֵיאַךְ יָכוֹל לַעֲמֹד בְּגֹבַהּ אַמִּין שִׁתִּין? אָמַר רַב בִּיבִי: מַעֲמִידִין אוֹתוֹ וְנוֹפֵל, עַד שֶׁהֵבִיאוּ כָּל זָהָב שֶׁל יְרוּשָׁלַיִם וְשָׁפְכוּ דִּימוֹס עַל רַגְלָיו, לְקַיֵּם מַה שֶּׁנֶּאֱמַר (יחזקאל ז:יט) ״וְזָהָבָם לְנִדָּה יִהְיֶה״:",2,0],[3,1,"בְּבִקְעַת דּוּרָא. שֵׁם מָקוֹם׃",3,0],[3,2,"לַאֲחַשְׁדַּרְפְּנַיָּא. דּוּכְסִין:",1,0],[3,2,"פַּחֲוָתָא. שָׁלְטוֹנִין:",2,0],[3,2,"אֲדַרְגָּזְרַיָּא גְדָבְרַיָּא וְגוֹ׳. כֻּלָּם שֵׁם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת הֵם:",3,0],[3,2,"לַחֲנֻכַּת צַלְמָא. תְּחִלַּת עֲבוֹדוֹתָיו:",4,0],[3,4,"וְכָרוֹזָא קָרֵא בְחָיִל. הַכָּרוֹז יוֹצֵא בְּכֹחַ גָּדוֹל:",1,0],[3,4,"לְכוֹן אָמְרִין עַמְמַיָּא. לָכֶם כָּל הָעַמִּים וְהַלְּשׁוֹנוֹת אוֹמְרִים מִכְּרוּז מִצְוַת הַמֶּלֶךְ בְּמִשְׁלַחַת הַמֶּלֶךְ׃",2,0],[3,5,"בְּעִדָּנָא דְּתִשְׁמְעוּן קָל קַרְנָא מַשְׁרוֹקִיתָא. קוֹל הַקֶּרֶן שׁוֹרֶקֶת, כְּמוֹ ״אֶשְׁרְקָה לָהֶם וַאֲקַבְּצֵם״ (זכריה י:ח):",1,0],[3,5,"קַתְרוֹס סַבְּכָא וְגוֹ׳. כֻּלָּם כְּלֵי זֶמֶר הֵם:",2,0],[3,5,"זְנֵי זְמָרָא. מִינֵי זֶמֶר. ״לְמִינוֹ״ (בראשית א:יא) תַּרְגּוּם אוּנְקְלוֹס: לִזְנוֹהִי:",3,0],[3,6,"אַתּוּן נוּרָא. גּוּמָּא שֶׁעוֹשִׂין לִשְׂרוֹף בָּהּ אֲבָנִים לְסִיד, וְהוּא כִּבְשָׁן שֶׁבְּכָל הַמִּקְרָא:",1,0],[3,7,"כָּל קֳבֵל דְּנָה. כָּל עוּמַּת זוֹ שֶׁנִּזְהֲרוּ בְּמִצְוַת הַמֶּלֶךְ עַל כָּךְ:",1,0],[3,7,"בֵּהּ זִמְנָא. בּוֹ בַּזְּמַן שֶׁיִּשְׁמְעוּ קוֹל הַזֶּמֶר, שֶׁהוּא לְסִימָן שֶׁיָּבוֹאוּ הַמִּשְׁתַּחֲוִים לְהִשְׁתַּחֲווֹת, נָפְלִין כָּל עַמְמַיָּא וְגוֹ׳:",2,0],[3,8,"כָּל קֳבֵל דְּנָה. כָּל עוּמַּת זוֹ שֶׁרָאוּ שׂוֹנְאֵי הַיְּהוּדִים שֶׁיֵּשׁ שָׁעָה לְהַלְשִׁין עֲלֵיהֶם:",1,0],[3,8,"קְרִיבוּ גֻבְרִין כַּשְׂדָּאִין וַאֲכַלוּ קַרְצֵיהוֹן. הִלְשִׁינוּ עֲלֵיהֶם, ״לֹא תֵלֵךְ רָכִיל״ (ויקרא יט:טז) מְתַרְגְּמִינָן ״וְלָא תֵיכוּל קוּרְצִין״, וְאוֹמֵר אֲנִי שֶׁכֵּן הָיְתָה דַּת שֶׁל הוֹלְכֵי רָכִיל לֶאֱכֹל לְגִימָה בַּמָּקוֹם שֶׁמַּלְשִׁינִין שָׁם, וְהוּא סִימָן קִיּוּם דְּבָרִים, שֶׁמֵּאוֹתָהּ שָׁעָה יֵשׁ עֲלֵיהֶם לְבָרֵר דִּבְרֵיהֶם וּלְאַמֵּת לָשׁוֹן הָרַע שֶׁאָמְרוּ. וְאוֹתָהּ סְעוּדָה נִקְרֵאת אֲכִילַת קוּרְצִין, לְשׁוֹן ״קוֹרֵץ בְּעֵינָיו״ (משלי ו:יג), שֶׁהוּא לְסִימָן לָשׁוֹן הָרַע:",2,0],[3,9,"עֲנוֹ וְאָמְרִין. צָוְחוּ. כָּל עֲנִיָּה שֶׁבַּמִּקְרָא לְשׁוֹן קוֹל רָם הוּא:",1,0],[3,10,"שַׂמְתָּ טְּעֵם. גָּזַרְתָּ דָּבָר:",1,0],[3,12,"אִיתַי. יֵשׁ:",1,0],[3,12,"יְהוּדָאיִן. מִשֵּׁבֶט יְהוּדָה:",2,0],[3,12,"אִלֵּךְ. אֵלֶּה:",3,0],[3,12,"לֹא שָׂמוּ עֲלָךְ מַלְכָּא טְעֵם. לֹא חָשׁוּ לָתֵת עֵצָה לְעַצְמָן לָחוּשׁ עַל גְּזֵרוֹתֶיךָ:",4,0],[3,13,"אֲמַר לְהַיְתָיָה. צִוָּה לְהָבִיא:",1,0],[3,13,"הֵיתָיוּ. הוּבָאוּ׃",2,0],[3,14,"הַצְדָא. שֶׁמָּא גְּזֵרוֹתַי צָדוּ וְשַׁמָּה וְדָבָר רֵיק הִיא בְּעֵינֵיכֶם, אַתֶּם שַׁדְרַךְ מֵישַׁךְ וַעֲבֵד נְגוֹ אֲשֶׁר לֵאלֹהַי אֵינְכֶם עוֹבְדִים? ה״א שֶׁל הַצְדָא מְשַׁמֶּשֶׁת בִּלְשׁוֹן תְּמִיהָה:",1,0],[3,14,"דִּי הֲקֵימֶת. שֶׁהֲקִימוֹתִי:",2,0],[3,15,"כְּעַן הֵן אִיתֵיכוֹן עֲתִידִין. עַתָּה הִנְּכֶם עֲתִידִים עַל כָּרְחֲכֶם לְקַבֵּל זוֹ עֲלֵיכֶם:",1,0],[3,15,"וְהֵן לָא תִסְגְּדוּן. וְאִם לֹא תִשְׁתַּחֲווּ תִּהְיוּ מֻשְׁלָכִים:",2,0],[3,15,"לְגוֹ. לְתוֹךְ:",3,0],[3,15,"וּמַן הוּא אֱלָהּ. וּמִי הוּא שׁוּם אֱלוֹהַּ שֶׁיַּצִּיל אֶתְכֶם מִיָּדִי?",4,0],[3,16,"לְמַלְכָּא נְבוּכַדְנֶצַּר. לָמָּה הוּזְכַּר שְׁמוֹ? אֶלָּא כָּךְ אָמְרוּ לוֹ: אִם לְקַבֵּל עָלֵינוּ גְּזֵרָתְךָ לָתֵת מִסִּין וְאַרְנוֹנִיּוֹת וְגֻלְגָּלִיּוֹת, אַתָּה מֶלֶךְ עָלֵינוּ, אִם לִכְפּוֹר בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, נְבוּכַדְנֶצַּר שְׁפַל אֲנָשִׁים בְּעֵינֵינוּ וּבָזוּי עַם אַתָּה:",1,0],[3,16,"לֹא חַשְׁחִין אֲנַחְנָא. לֹא חוֹשְׁשִׁין אָנוּ עַל זֹאת לִטּוֹל עֵצָה מַה לְּהָשִׁיבְךָ, כִּי הַמַּעֲנֶה מוּכָן וְשָׁגוּר בְּפִינוּ:",2,0],[3,17,"יָכִיל לְשֵׁיזָבוּתַנָא. יָכוֹל לְהַצִּילֵנוּ מִכָּל צָרָה:",1,0],[3,17,"מִן אַתּוּן נוּרָא. וּמִן יְדָךְ מַלְכָּא יְשֵׁיזִיב מִן הַכִּבְשָׁן וּמִן יָדְךָ יַצִּיל׃",2,0],[3,18,"וְהֵן לָא. וְאִם לֹא יַחְפֹּץ לְהַצִּיל גּוּפֵינוּ יְדִיעַ לֶהֱוֵי לָךְ:",1,0],[3,19,"הִתְמְלִי חֱמָא. נִתְמַלֵּא חֵמָה:",1,0],[3,19,"וּצְלֵם אַנְפּוֹהִי אֶשְׁתַּנִּי. וּפַרְצוּף פָּנָיו נִשְׁתַּנּוּ:",2,0],[3,19,"לְמֵזֵא לְאַתּוּנָא. לְהַצִּית לְכִבְשַׁן הָאֵשׁ וּלְחַמְּמוֹ׃",3,0],[3,19,"חַד שִׁבְעָה עַל דִּי חֲזֵה לְמֵזְיֵהּ. עַל אַחַת שֶׁבַע פְּעָמִים שֶׁשִּׁעֲרוּהוּ עַד כְּדֵי הֶסֵּקוֹ, וּכְאִלּוּ יַבְעִירוּהוּ שִׁבְעָה שִׁעוּרִין כָּמוֹהוּ:",4,0],[3,19,"לְמֵזְיֵהּ. לְהַסִּיקוֹ:",5,0],[3,20,"וּלְגֻבְרִין גִּבָּרֵי חַיִל דִּי בְחַיְלֵהּ. וְלַאֲנָשִׁים גִּבּוֹרֵי כֹחַ אֲשֶׁר בְּחֵילוֹ:",1,0],[3,20,"אֲמַר לְכַפָּתָה. צִוָּה לֶאֱסוֹר אוֹתָם, שֶׁרָאָה מִתְחַזְּקִים לַעֲנוֹתוֹ קָשׁוֹת, וְאָמַר: גִּבּוֹרִים הֵם אֵלּוּ, וְצִוָּה לַגִּבּוֹרִים אֲשֶׁר בְּחֵילוֹ לֶאֱסוֹר אוֹתָם:",2,0],[3,21,"גּוּבְרַיָּא אִלֵּךְ. אֲנָשִׁים אֵלּוּ:",1,0],[3,21,"כְּפִיתוּ בְּסַרְבָּלֵיהוֹן. נִתְקַשְּׁרוּ בְּבִגְדֵי מַעֲטְפוֹתָן:",2,0],[3,21,"פַּטְּשֵׁיהוֹן וְכַרְבְּלָתְהוֹן מִינֵי מַלְבּוּשׁ מַלְכוּת שֶׁהָיָה לָהֶם, וְאַף עַל פִּי שֶׁהָיוּ יוֹצְאִין לִידּוֹן לִפְנֵי נְבוּכַדְנֶצַּר דִּינֵי מִיתָה, לֹא שִׁנּוּ בִגְדֵיהֶם לְהַשְׁפִּיל אֶת גְּדֻלָּתָם. מִכָּאן לָמְדוּ חֲכָמִים, שֶׁאֲפִלּוּ בִּשְׁעַת הַסַּכָּנָה לֹא יְשַׁנֶּה אָדָם מִן הַשְּׂרָרָה שֶׁהֻחְזַק בָּהּ:",3,0],[3,21,"וְכַרְבְּלָתְהוֹן. יֵשׁ לוֹ דֻגְמָא: ״וְדָוִד מְכֻרְבָּל״ (דברי הימים א טו:כז):",4,0],[3,21,"וּרְמִיו לְגוֹא אַתּוּן נוּרָא. וְהֻשְׁלְכוּ לְתוֹךְ כִּבְשָׁן בּוֹעֵרָה:",5,0],[3,22,"כָּל קֳבֵל דְּנָה. כָּל עוּמַּת זֹאת אֲשֶׁר מִצְוַת הַמֶּלֶךְ הָיְתָה עַזָּה:",1,0],[3,22,"וְאַתּוּנָא אֵזֵה יַתִּירָא. וְהַכִּבְשָׁן הוּסַּק מְאֹד:",2,0],[3,22,"גּוּבְרַיָּא אִלֵּךְ. אֵלּוּ הָאֲנָשִׁים הַגִּבּוֹרִים אֲשֶׁר קָשְׁרוּ אֶת חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה וְהִשְׁלִיכוּם לַכִּבְשָׁן:",3,0],[3,22,"קַטִּל הִמּוֹן שְׁבִיבָא דִּי נוּרָא. שָׂרַף אוֹתָם כֹּחַ שְׁבִיב הָאֵשׁ:",4,0],[3,23,"מְכַפְּתִין. קְשׁוּרִין:",1,0],[3,24,"תְּוַהּ. תָּמַהּ׃",1,0],[3,24,"וְקָם בְּהִתְבְּהָלָה. וְעָמַד בְּבֶהָלָה:",2,0],[3,24,"עָנַיִן וְאָמְרִין. עוֹנִין וְאוֹמְרִים לַמֶּלֶךְ:",3,0],[3,24,"יַצִּיבָא מַלְכָּא. אֱמֶת דְּבַר הַמֶּלֶךְ:",4,0],[3,25,"שְׁרַיִן מַהְלְכִין בְּגוֹא נוּרָא. מוּתָּרִין מֵאֲסוּרֵיהֶן וְהוֹלְכִים בְּתוֹךְ הָאֵשׁ:",1,0],[3,25,"וַחֲבָל לָא אִיתַי בְּהוֹן. וַחֲבָלָה לֹא יֵשׁ בָּהֶם:",2,0],[3,25,"וְרֵוֵהּ דִּי. רְבִיעָאָה וְתוֹאֲרוֹ שֶׁל רְבִיעִי:",3,0],[3,25,"דָּמֵה לְבַר אֱלָהִין. דּוֹמֶה לְמַלְאָךְ שֶׁרָאִיתִי בִּהְיוֹתִי עִם סַנְחֵרִיב כְּשֶׁנִּשְׂרְפוּ אוּכְלוּסָיו, שֶׁנֶּאֱמַר ״וַיַּךְ בְּמַחֲנֵה אַשּׁוּר״ (מלכים ב יט:לה), וּנְבוּכַדְנֶצַּר הָיָה שָׁם וְנִמְלַט בְּתוֹךְ עֲשָׂרָה שֶׁנִּמְלְטוּ מֵהֶם:",4,0],[3,26,"קְרֵב לִתְרַע אַתּוּן נוּרָא נִגַּשׁ לְשַׁעַר הֶחָצֵר שֶׁהַכִּבְשָׁן בְּתוֹכָהּ, לְדַבֵּר עִמָּהֶם; וּמִתְּחִלָּה הָיָה רוֹאֶה אוֹתָם מֵרָחוֹק:",1,0],[3,26,"פּוּקוּ וֶאֱתוֹ. צְאוּ וּבֹאוּ, וְלֹא אָמַר לָהֶם עֲלוּ וּבֹאוּ. מִכָּאן לָמַדְנוּ שֶׁצָּף קַרְקָעִית הַכִּבְשָׁן וְהִשְׁוָה לָאָרֶץ, שֶׁלֹּא יִטְרְחוּ לַעֲלוֹת:",2,0],[3,26,"בֵּאדַיִן נָפְקוּן. אַף עַל פִּי שֶׁבְּטוּחִין בַּנֵּס הֶעָשׂוּי לָהֶם, לֹא מָלְאָה לִבָּם לְזַלְזֵל בַּמַּלְכוּת לָצֵאת שֶׁלֹּא בִּרְשׁוּת:",3,0],[3,27,"וּמִתְכַּנְּשִׁין אֲחַשְׁדַּרְפְּנַיָּא. אַרְבַּע אֻמּוֹת נִמְנוּ לְמַעְלָה בָּאֲסִיפָה הָרִאשׁוֹנָה שֶׁלֹּא נִמְנוּ כָּאן: אֲדַרְגָּזְרַיָּא דְּתָבְרַיָּא גְּדָבְרַיָּא תִּפְתָּיָא, הֵם גִּבּוֹרֵי הַחַיִל אֲשֶׁר הֲרָגָם שְׁבִיב הָאֵשׁ בְּהַשְׁלִיכָם אֶת חֲנַנְיָה וַחֲבֵרָיו לָאוּר:",1,0],[3,27,"חָזַיִן לְגֻבְרַיָּא אִלֵּךְ. רוֹאִין אֶת הָאֲנָשִׁים הָאֵלֶּה, חֲנַנְיָה וַחֲבֵרָיו:",2,0],[3,27,"דִּי לָא שְׁלֵט נוּרָא בְּגֶשְׁמְהוֹן. אֲשֶׁר לֹא שָׁלְטָה הָאֵשׁ בְּגוּפָם:",3,0],[3,27,"גִּשְׁמְהוֹן. גּוּפָן בִּלְשׁוֹן אֲרַמִּי, וְיֵשׁ רַבִּים בְּזֶה הַסֵּפֶר:",4,0],[3,27,"וּשְׂעַר רֵאשְׁהוֹן לָא הִתְחָרַךְ. שְׂעַר רֵאשֵׁיהוֹן לָא נֶחֱרַךְ:",5,0],[3,27,"לֹא שָׁנוּ. לֹא נִשְׁתַּנּוּ מִמַּרְאִיתָן:",6,0],[3,27,"לֹא עֲדָת בְּהוֹן. לֹא סָרָה לְתוֹכָם:",7,0],[3,28,"עָנֵה נְבוּכַדְנֶצַּר. צָוַח נְבוּכַדְנֶצַּר:",1,0],[3,28,"דִּי הִתְרְחִיצוּ עֲלוֹהִי. אֲשֶׁר בָּטְחוּ עָלָיו:",2,0],[3,28,"וּמִלַּת מַלְכָּא שַׁנִּיו. וּמִלַּת הַמֶּלֶךְ שִׁנּוּ שֶׁלֹּא לְקַיְּמוֹ:",3,0],[3,28,"וִיהַבוּ גֶשְׁמְהוֹן. וּמָסְרוּ גוּפָם:",4,0],[3,28,"לֵאלָהֲהוֹן. זוּלָתִי לֵאלֹהֵיהֶם:",5,0],[3,29,"שִׂים טְעֵם. כְּלוֹמַר: יוּשַׂם חֹק:",1,0],[3,29,"דִּי יֵאמַר שָׁלוּ. אֲשֶׁר יֹאמַר מִשְׁגֶּה, כְּלוֹמַר: שׁוּם דָּבָר שֶׁל גְּנַאי:",2,0],[3,29,"הַדָּמִין. אֵבָרִים, כְּלוֹמַר: יְנַתְּחוּהוּ לְאֵבָרִים:",3,0],[3,29,"נְוָלִי יִשְׁתַּוֵּה. אַשְׁפָּה יוּשַׂם:",4,0],[3,29,"דִּי יִכֻּל לְהַצָּלָה כִּדְנָה. אֲשֶׁר יָכוֹל לְהַצִּיל כָּזֹאת:",5,0],[3,30,"הַצְלַח. הִצְלִיחַ וְהִגְדִּיל אוֹתָם:",1,0],[3,31,"נְבוּכַדְנֶצַּר מַלְכָּא לְכָל עַמְמַיָּא. זֶה טֹפֶס כְּתַב הָאִגֶּרֶת: נְבוּכַדְנֶצַּר הַמֶּלֶךְ שׁוֹאֵל לְשָׁלוֹם לְכָל הָעַמִּים:",1,0],[3,32,"שְׁפַר קׇדָמַי לְהַחֲוָיָה. טוֹב לִי לְהַגִּיד:",1,0],[4,1,"שְׁלֵה הֲוֵית בְּבֵיתִי. שָׁלֵיו הָיִיתִי:",1,0],[4,2,"וִידַחֲלִנַּנִי. וְאִיֵּם עָלַי וְהִפְחִידַנִי:",1,0],[4,5,"וְעַד אׇחֳרֵין. וְעַד אֲשֶׁר בָּאַחֲרוֹנָה הוּבָא לִפְנֵי דָּנִיֵּאל:",1,0],[4,5,"כְּשׁוּם אֱלָהִי. עֲבוֹדַת כּוֹכָבִים שֶׁל בָּבֶל בֵּל שְׁמָהּ, טְשַׁצַּר שֵׁם לְשׁוֹן חָכְמָה הוּא בָּאוּמּוֹת:",2,0],[4,6,"וְכָל רָז לָא אָנֵס לָךְ. וְכָל סָתוּם לֹא נֶאֱנַס וְלֹא נִכְחַד מִמְּךָ׃",1,0],[4,8,"רְבָה אִילָנָא וּתְקִיף. גָּדַל הָאִילָן וְהוּחְזַק וְעָצַם:",1,0],[4,8,"יִמְטֵא לִשְׁמַיָּא. הִגִּיעַ הַשָּׁמַיִם:",2,0],[4,9,"עָפְיֵהּ שַׁפִּיר. עַנְפּוֹ נָאֶה:",1,0],[4,9,"וְאִנְבֵּהּ שַׂגִּיא. פִּרְיוֹ רַב:",2,0],[4,9,"וּמָזוֹן לְכֹלָּא בֵהּ. וּכְדֵי מָזוֹן לְכָל בְּרִיָּה הָיָה בּוֹ:",3,0],[4,9,"תַּטְלֵל. לְשׁוֹן צֵל:",4,0],[4,9,"יְדוּרָן. לְשׁוֹן מָדוֹר וְלִינָה:",5,0],[4,9,"יִתְּזִין. לְשׁוֹן מָזוֹן:",6,0],[4,10,"חָזֵה הֲוֵית. רוֹאֶה הָיִיתִי:",1,0],[4,10,"וַאֲלוּ עִיר וְקַדִּישׁ. וְהִנֵּה מַלְאָךְ שֶׁהוּא עֵר לְעוֹלָם וְקָדוֹשׁ:",2,0],[4,11,"קָרֵא בְחַיִל. צוֹעֵק בְּכֹחַ:",1,0],[4,11,"גּוֹדּוּ אִילָנָא. קוּצּוּ הָאִילָן:",2,0],[4,11,"אַתַּרוּ עָפְיֵהּ. הִשִּׁירוּ וְהִפִּילוּ עֲנָפָיו:",3,0],[4,11,"וּבַדַּרוּ אִנְבֵּהּ. הֵפִיצוּ פִּרְיוֹ:",4,0],[4,11,"תְּנוּד חֵיוְתָא מִן תַּחְתּוֹהִי. יָנוּדוּ הַחַיּוֹת מִתַּחְתָּיו:",5,0],[4,12,"בְּרַם עִקַּר שָׁרְשׁוֹהִי בְּאַרְעָא שְׁבוּקוּ. אַךְ עִקַּר שָׁרְשָׁיו הַנִּיחוּ:",1,0],[4,12,"וּבֶאֱסוּר דִּי פַרְזֶל וּנְחָשׁ. כְּלוֹמַר: תְּנוּ רַגְלָיו בְּכַבְלֵי בַרְזֶל, כְּשֵׁם שֶׁעוֹשִׂין לְסוּס שֶׁמַּנִּיחִין אוֹתוֹ בָּאָפָר כָּךְ כַּבְלוּהִי בְּכַבְלִים:",2,0],[4,12,"בְּדִתְאָא. בַּעֲשַׂב הַשָּׂדֶה, כְּלוֹמַר: בָּאָחוּ, שֶׁלֹּא יָזוּז מִשָּׁם:",3,0],[4,12,"יִצְטַבַּע. יְהֵא שָׁרוּי תָּמִיד, לְשׁוֹן טְבִילָה:",4,0],[4,12,"חֲלָקֵהּ. חֶלְקוֹ:",5,0],[4,13,"וְשִׁבְעָה עִדָּנִין. שֶׁבַע שָׁנִים:",1,0],[4,13,"יַחְלְפוּן עֲלוֹהִי. יַעַבְרוּ עָלָיו בִּגְזֵרָה זוֹ:",2,0],[4,14,"שְׁאֵלְתָא. גְּזֵרָה. וְעַל יְדֵי שֶׁנִּמְלָכִין בְּהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹדֶם שֶׁיִּגְזְרוּ הַגְּזֵרָה, קוֹרֵא אוֹתָהּ שְׁאֵלְתָא:",1,0],[4,14,"עַד דִּבְרַת. כְּמוֹ לְמַעַן:",2,0],[4,14,"דִּי יִנְדְּעוּן חַיַּיָּא. שֶׁיֵּדְעוּ כָּל הַחַיִּים:",3,0],[4,14,"וּלְמַן דִּי יִצְבֵּא. לְמִי שֶׁיִּרְצֶה:",4,0],[4,15,"פִּשְׁרָא. פִּתְרוֹנוֹ:",1,0],[4,15,"וְאַנְתְּ כָּהֵל. וְאַתָּה יָכוֹל:",2,0],[4,16,"אֱדַיִן דָּנִיֵּאל. אֶשְׁתּוֹמַם שָׁתַק:",1,0],[4,16,"וְרַעְיוֹנוֹהִי. וּמַחְשְׁבוֹתָיו:",2,0],[4,16,"יְבַהֲלוּנֵיהּ. שֶׁהָיָה יָרֵא לִפְתּוֹר לוֹ חֲלוֹם:",3,0],[4,16,"מָרִאי. אֲדוֹנִי, אָמְרוּ רַבּוֹתֵינוּ (שבועות לה:): מָרִי חֶלְמָא לְשָׂנְאָךְ קֹדֶשׁ הוּא. תָּלָה עֵינָיו לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר: חֲלוֹם זֶה יִתְקַיֵּם עַל שׂוֹנַאֲךָ זֶה. וְאִם תֹּאמַר לִנְבוּכַדְנֶצַּר אָמַר, וַהֲלֹא יִשְׂרָאֵל שׂוֹנְאוֹ, אֶפְשָׁר שֶׁיְּקַלְלֵם?",4,0],[4,16,"לְעָרָךְ. לְשׂוֹנְאָךְ, כְּמוֹ ״וַיְהִי עָרֵךְ״ (שמואל א כה):",5,0],[4,21,"דִּי מְטָת עַל מָרִאי מַלְכָּא. אֲשֶׁר הִגִּיעַ עַל אֲדוֹנִי הַמֶּלֶךְ:",1,0],[4,22,"וְלָךְ טָרְדִין מִן אֲנָשָׁא. וְאוֹתְךָ יִטְרְדוּ מִבְּנֵי אָדָם:",1,0],[4,22,"לָךְ מְצַבְּעִין. אוֹתְךָ יִטְבְּלוּ:",2,0],[4,22,"וְשִׁבְעָה עִדָּנִין יַחְלְפוּן עֲלָךְ. יֵשׁ לוֹמַר: גְּמוּל בֵּית הַמִּקְדָּשׁ שֶׁהֶחֱרִיב, שֶׁנִּבְנְתָה בְּשֶׁבַע שָׁנִים (מלכים א ו:לח):",3,0],[4,23,"וְדִי אֲמַרוּ וְגוֹ׳. אֲשֶׁר אָמְרוּ לְהַנִּיחַ שָׁרְשׁוֹהִי שֶׁל אִילָן, וְהוּא הַפִּתְרוֹן: מַלְכוּתָא לָךְ קַיֶּמֶת. הַמַּלְכוּת עוֹמֶדֶת לְךָ, סוֹפְךָ שֶׁתָּשׁוּב לְךָ מַלְכוּתְךָ:",1,0],[4,23,"מִן דִּי תִנְדַּע דִּי שַׁלִּיטִין שְׁמַיָּא. מֵאַחַר שֶׁתֵּדַע שֶׁהָעֶלְיוֹנִים מוֹשְׁלִים בָּעוֹלָם:",2,0],[4,24,"לָהֵן מַלְכָּא. בֶּאֱמֶת אַתָּה מֶלֶךְ, שְׁמַע לַעֲצָתִי:",1,0],[4,24,"מַלְכִּי. עֲצָתִי, כְּמוֹ ״אִיעָצְךָ״ (במדבר כד:יד) ״אֲמַלְכִינָךְ״ (תרגום אונקלוס):",2,0],[4,24,"יִשְׁפַּר עֲלָךְ. עֲצָתִי תִּיטַב בְּעֵינֶיךָ לִשְׁמֹעַ מִלַּי:",3,0],[4,24,"וַחֲטָאָךְ בְּצִדְקָה פְרֻק. וַחֲטָאָךְ בִּצְדָקָה פְּרֹק מֵעַל צַוָּארֶךָ:",4,0],[4,24,"וַעֲוָיָתָךְ בְּמִחַן עֲנָיִן. וַעֲוֹנוֹתֶיךָ פְּרוֹק בַּחֲנִינַת עֲנִיִּים:",5,0],[4,24,"הֵן תֶּהֱוֵא אַרְכָא לִשְׁלֵוְתָךְ. אוּלַי תְּהֵא שָׁהוּת לִשְׁלוֹמְךָ, שֶׁלֹּא תְּמַהֵר הָרָעָה לָבוֹא. וּמָה רָאָה דָנִיֵּאל לְהַשִּׂיא עֵצָה טוֹבָה לִנְבוּכַדְנֶצַּר? רָאָה יִשְׂרָאֵל עֲנִיִּים שִׁפְלֵי גוֹלָה מַחֲזִירִין עַל הַפְּתָחִים, וְהִשִּׂיאוֹ עֵצָה לְחָנְנָם. אָמַר לוֹ: עֲנִיִּים אֵלּוּ שֶׁהִגְלֵיתָם רְעֵבִים הֵם, פַּרְנְסֵם! וְכֵן עָשָׂה, פָּתַח אוֹצְרוֹתָיו וְהָיָה מְפַרְנְסָם כָּל שְׁנֵים עָשָׂר חֹדֶשׁ:",6,0],[4,25,"כֹּלָּא מְטָא. כָּל הַפִּתְרוֹן הִגִּיעַ עַל נְבוּכַדְנֶצַּר:",1,0],[4,26,"מְהַלֵּךְ הֲוָה. הוֹלֵךְ הָיָה:",1,0],[4,27,"הֲלָא דָא הִיא. שָׁמַע עֲנִיִּים בָּאִים עַל הַפֶּתַח וְצוֹעֲקִים, אָמַר: מָה קוֹל הֶהָמוֹן הַזֶּה בְּאָזְנָי? אָמְרוּ לוֹ עֲבָדָיו: אֵלּוּ הָעֲנִיִּים שֶׁקָּבַעְתָּ לָהֶם עֵת פַּרְנָסָתָם. אָמַר: הֲלָא דָא הִיא בָּבֶל רַבְּתָא וְגוֹמֵר, וְאִלְמָלֵא בִּזְבַּזְתִּי אוֹצְרוֹתַי לְפַרְנָסַת עֲנִיִּים, מֵהֵיכָן הָיִיתִי בּוֹנֶה כָּל הַפַּלְטְרִין הַלָּלוּ? מֵעַתָּה אֵינִי מְפַרְנְסָם. כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא:",1,0],[4,27,"וְלִיקָר הַדְרִי. וּלְכָבוֹד תִּפְאַרְתִּי:",2,0],[4,28,"עוֹד מִלְּתָא בְּפֻם מַלְכָּא, עֲדָת מִנָּךְ. סָרָה מִנָּךְ:",1,0],[4,29,"טָרְדִין. לְשׁוֹן גֵּרוּשִׁין:",1,0],[4,30,"סָפַת. הַגְּזֵרָה כָּלְתָה עָלָיו:",1,0],[4,30,"גִּשְׁמֵהּ. גּוּפֵיהּ:",2,0],[4,30,"שַׂעְרֵהּ כְּנִשְׁרִין רְבָה. שַׂעֲרוֹתָיו כְּכַנְפֵי נְשָׁרִים גָּדְלוּ עַל כָּל גּוּפוֹ:",3,0],[4,30,"וְטִפְרוֹהִי כְצִפְּרִין. וְצִפָּרְנָיו כְּצִפּוֹר:",4,0],[4,31,"וְלִקְצָת יוֹמַיָּא. לְקֵץ הַיָּמִים שֶׁקָּבְעוּ לוֹ, לְסוֹף שֶׁבַע הַשָּׁנִים:",1,0],[4,31,"נִטְלֵת. נָשָׂאתִי:",2,0],[4,31,"וּמַנְדְּעִי עֲלַי יְתוּב. וְדַעְתִּי עָלַי חָזְרָה:",3,0],[4,31,"וּלְעִלָּאָה בָּרְכֵת. וְאֶת הָעֶלְיוֹן בֵּרַכְתִּי:",4,0],[4,32,"כֻּלָּה חֲשִׁיבִין. רַבּוֹתֵינוּ אָמְרוּ: הַאי חִירְגָּא דְּיוֹמָא לָא שְׁמֵיהּ אָבָק הַנִּרְאֶה בַּשֶּׁמֶשׁ (יומא כ:):",1,0],[4,32,"וּכְמִצְבְּיֵהּ עָבֵד בְּחֵיל שְׁמַיָּא. וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם:",2,0],[4,32,"וְלָא אִיתַי דִּי יְמַחֵא בִידֵהּ. וְלָא יֵשׁ שֶׁיִּמְחֶה בְּיָדוֹ:",3,0],[4,33,"בֵּהּ זִמְנָא. בְּאוֹתוֹ זְמָן:",1,0],[4,33,"וְלִיקַר מַלְכוּתִי הַדְרִי. וּלְכָבוֹד מַלְכוּתִי חָזַרְתִּי:",2,0],[4,33,"וְזִיוִי. וְתֹאַר פָּנַי:",3,0],[4,33,"וְלִי הַדָּבְרַי וְרַבְרְבָנַי יְבַעוֹן. וְאוֹתִי יוֹעֲצַי וְשָׂרַי הָיוּ מְבַקְּשִׁים וַחֲפֵצִים שֶׁאָשׁוּב:",4,0],[4,33,"הׇתְקְנַת. הוּכַנְתִּי:",5,0],[4,33,"וּרְבוּ יַתִּירָה הוּסְפַת לִי. וּגְדֻלָּה יְתֵרָה מִן הָרִאשׁוֹנָה נִתּוֹסְפַת לִי, אָמְרוּ רַבּוֹתֵינוּ (שבת קנ.) שֶׁרָכַב עַל אֲרִי וְקָשַׁר תַּנִּין בְּרֹאשׁוֹ:",6,0],[4,34,"וְאֹרְחָתֵהּ דִּין. וּדְרָכָיו מִשְׁפָּט:",1,0],[4,34,"וְדִי מְהַלְּכִין בְּגֵוָה. וַאֲשֶׁר מְהַלְּכִין בְּגַאֲוָה יָכוֹל לְהַשְׁפִּיל:",2,0],[5,1,"בֵּלְשַׁאצַּר מַלְכָּא. בְּנוֹ הָיָה, וּמָלַךְ לְאַחַר אֱוִיל מְרֹדַךְ שֶׁמָּלַךְ תַּחַת נְבוּכַדְנֶצַּר, וְגַם (הוּא) הָיָה בְּנוֹ שֶׁל נְבוּכַדְנֶצַּר:",1,0],[5,1,"עֲבַד לְחֶם רַב. עָשָׂה סְעוּדָּה גְּדוֹלָה. מָצִינוּ בְּסֵפֶר יוֹסִיפוֹן שֶׁנִּלְחַם בַּיּוֹם עִם דָּרְיָוֶשׁ הַמָּדִי וְכוֹרֶשׁ וְנִצַּח הַמִּלְחָמָה, וְלָעֶרֶב עָשָׂה מִשְׁתֶּה, כְּמוֹ שֶׁנִּבָּא עָלָיו יְשַׁעְיָה ״עָרוֹךְ הַשֻּׁלְחָן צָפֹה הַצָּפִית אָכוֹל שָׁתֹה קוּמוּ הַשָּׂרִים וְגוֹ׳״ (ישעיה כא:ה) שֶׁבְּתוֹךְ הַמִּשְׁתֶּה חָזְרוּ אוֹיְבָיו וְנִלְחֲמוּ עַל הָעִיר וּלְכָדוּהָ:",2,0],[5,1,"וְלׇקֳבֵל אַלְפָּא חַמְרָא. כְּנֶגֶד אֶלֶף אִישׁ הָיָה שׁוֹתֶה יַיִן:",3,0],[5,2,"אֲמַר בִּטְעֵם חַמְרָא. אָמַר בַּעֲצַת הַיַּיִן שֶׁנִּשְׁתַּכֵּר:",1,0],[5,2,"לְהַיְתָיָה. לְהָבִיא:",2,0],[5,2,"דִּי הַנְפֵּק. שֶׁהוֹצִיא׃",3,0],[5,2,"שֵׁגְלָתֵהּ. לְשׁוֹן מַלְכָּא בִּלְשׁוֹן אֲרָמִי, כְּמוֹ ״וְהַשֵּׁגַל יוֹשֶׁבֶת אֶצְלוֹ״ (נחמיה ב:ו):",4,0],[5,3,"הַיְתִיו. הוּבָאוּ׃",1,0],[5,3,"דִּי הַנְפִּקוּ. שֶׁהוֹצִיאוּ:",2,0],[5,5,"נָפְקוּ: אֶצְבְּעָן. יָצְאוּ אֶצְבְּעוֹת יַד אָדָם מִן הַשָּׁמַיִם:",1,0],[5,5,"לָקֳבֵל נֶבְרַשְׁתָּא. לְמוּל הַמְּנוֹרָה אֲשֶׁר לִפְנֵי הַשֻּׁלְחָן, וְדֻגְמָתוֹ בְּמַסֶּכֶת יוֹמָא: עָשְׂתָה נִבְרֶשֶׁת שֶׁל זָהָב (יומא לז.):",2,0],[5,5,"עַל גִּירָא. עַל סִיד טִיחַ כּוֹתֶל הַבַּיִת, כְּמוֹ (ישעיהו כז:ט) ״כְּאַבְנֵי גִר מְנֻפָּצוֹת״, וְהוּא דּוֹמֶה לְסִיד:",3,0],[5,6,"זִיוֺהִי שְׁנוֹהִי. תָּאֳרָיו נִשְׁתַּנּוּ עָלָיו:",1,0],[5,6,"וְרַעְיוֹנוֹהִי. מַחְשְׁבוֹתָיו:",2,0],[5,6,"וְקִטְרֵי חַרְצֵהּ מִשְׁתָּרַיִן. אֵזוֹר חֲלָצָיו נִפְתָּח, שֶׁהָיוּ מָתְנָיו מִתְרוֹקְנִין מֵחֲמַת הַיִּרְאָה וַחֲגוֹרוֹ נִפְתָּח:",3,0],[5,6,"וְקִטְרֵי חַרְצֵהּ מִשְׁתָּרַיִן. נִתְרִין:",4,0],[5,6,"וְאַרְכֻבָּתֵהּ. וּבִרְכָּיו:",5,0],[5,6,"דָּא לְדָא נָקְשָׁן. מַקִּישׁוֹת וְדוֹפְקוֹת:",6,0],[5,7,"בְּחַיִל. בְּכֹחַ:",1,0],[5,7,"לְהֶעָלָה. לְהַכְנִיס:",2,0],[5,7,"כְּתָבָה דְנָה. מִכְתָּב זֶה:",3,0],[5,7,"אַרְגְּוָנָא יִלְבַּשׁ. כְּמִשְׁפַּט הַפַּרְתְּמִים:",4,0],[5,7,"וְהַמְנִיכָא. רְבִיד עֲנָק:",5,0],[5,7,"וְתַלְתִּי בְמַלְכוּתָא יִשְׁלַט. בִּשְׁלִישׁ הַמַּלְכוּת יִמְשׁוֹל:",6,0],[5,8,"עָלִין. נִכְנָסִין:",1,0],[5,9,"שַׂגִּיא מִתְבָּהַל. הַרְבֵּה מִתְפַּחֵד:",1,0],[5,9,"מִשְׁתַּבְּשִׁין. נֶחְפָּזִין:",2,0],[5,10,"מַלְכְּתָא לָקֳבֵל מִלֵּי מַלְכָּא. הַמַּלְכָּה כְּלַפֵּי שֶׁשָּׁמְעָה אֶת דִּבְרֵי הַמֶּלֶךְ וְשָׂרָיו לְבֵית הַמִּשְׁתֶּה בָּאָה:",1,0],[5,11,"אִיתַי גְּבַר. יֵשׁ אָדָם בְּמַלְכוּתְךָ אֲשֶׁר רוּחַ קְדוֹשִׁים בּוֹ:",1,0],[5,11,"כְּחָכְמַת אֱלָהִין. מַלְאָכִים:",2,0],[5,11,"הֲקִימֵהּ. מִנָּהוּ שַׂר עַל כֻּלָּם:",3,0],[5,12,"כָּל קֳבֵל וְגוֹ׳. כְּלַפֵּי אֲשֶׁר רוּחַ יְתֵירָה וְדַעַת הַשֵּׂכֶל יֵשׁ בּוֹ, וְהַגָּדַת חִידוֹת:",1,0],[5,12,"וּמְשָׁרֵא קִטְרִין. סָתוּם כָּל סֵתֶר נִמְצָא בוֹ בְּדָנִיֵּאל:",2,0],[5,16,"תִכּוּל. אִם תּוּכַל:",1,0],[5,17,"וּנְבָזְבְּיָתָךְ. דּוֹרְנוֹתָךְ׃",1,0],[5,17,"לְאָחֳרָן הַב. לְאַחֵר תֵּן:",2,0],[5,19,"דִּי הֲוָה צָבֵא. לְמִי שֶׁהָיָה חָפֵץ:",1,0],[5,19,"הֲוָה מַחֵא. מְחַיֵּיהּ:",2,0],[5,20,"וּכְדִי רִם לִבְבֵיהּ. וְכַאֲשֶׁר רָם לְבָבוֹ:",1,0],[5,20,"לְהָזָדָה. לְהַרְשִׁיעַ:",2,0],[5,20,"הׇנְחַת. הוֹרִיד:",3,0],[5,20,"הֶעְדִּיו מִנֵּהּ. הֵסִירוּ מִמֶּנּוּ:",4,0],[5,21,"טְרִיד. נִגְרָשׁ:",1,0],[5,22,"כָּל קֳבֵל דִּי כָל דְּנָה יְדַעְתָּ. כָּל עוּמַת אֲשֶׁר כָּל זֶה יָדַעְתָּ שֶׁאֵרַע לְאָבִיךָ, וְהָיָה לְךָ לִהְיוֹת יָרֵא מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[5,24,"שְׁלִיחַ פַּסָּא דִּי יְדָא. נִשְׁלַח כַּף יָד:",1,0],[5,24,"וּכְתָבָא דְנָה רְשִׁים. וְזֶה הַמִּכְתָּב אֲשֶׁר חָקַק:",2,0],[5,26,"מְנֵא מְנָא. מְנָה אֱלָהָא, כְּלוֹמַר מְנָא זֶהוּ פֵּרוּשׁוֹ מְנָה אֱלָהָא מַלְכוּתָךְ:",1,0],[5,26,"וְהַשְׁלְמַהּ. חָשַׁב קֵץ שֶׁנִּפְסַק מַלְכוּת שֶׁל אָבִיךָ וְזַרְעוֹ וּמָצָא שֶׁכְּבָר הֻשְׁלְמָה:",2,0],[5,27,"תְּקֵל תְּקִילְתָּא בְמֹאזַנְיָא. תְּקֵל זֶהוּ פֵּרוּשׁוֹ: נִשְׁקַלְתָּ לְפָנָיו בְּמֹאזְנַיִם וְנִמְצֵאתָ חָסֵר מִכָּל צְדָקָה:",1,0],[5,28,"פְּרֵס פְּרִיסַת מַלְכוּתָךְ וְגוֹ׳. כְּלוֹמַר: ״וּפַרְסִין״ מַשְׁמַע שְׁנֵי פְרָסִין, הָאֶחָד: פְּרִיסַת מַלְכוּתָךְ, נִשְׁתַּבְּרָה מַלְכוּתְךָ, וְהַשֵּׁנִי, שֶׁנִּתְּנָה לְמָדַי וּפָרָס:",1,0],[6,1,"וְדָרְיָוֶשׁ מָדָאָה קַבֵּל מַלְכוּתָא כְּבַר שְׁנִין שִׁתִּין וְתַרְתֵּין. לָמָּה מָנָה שְׁנוֹתָיו? לוֹמַר לְךָ: בְּיוֹם שֶׁנִּכְנַס נְבוּכַדְנֶצַּר לַהֵיכָל בִּימֵי יְהוֹיָקִים (צריך לומר: יְהוֹיָכִין), נוֹלַד שִׂטְנוֹ דָּרְיָוֶשׁ (סדר עולם כח). מִגָּלוּת יְכָנְיָה וְעַד כָּאן שִׁשִּׁים וּשְׁתַּיִם שָׁנָה, וְאָמַר מַר: גָּלוּ בִּימֵי יְהוֹיָכִין בְּשֶׁבַע לְכִבּוּשׁ יְהוֹיָקִים, שֶׁהוּא שְׁמוֹנֶה לִנְבוּכַדְנֶצַּר, נִשְׁתַּיְּרוּ לִנְבוּכַדְנֶצַּר שְׁלֹשִׁים וָשֶׁבַע, שֶׁהֲרֵי אַרְבָּעִים וְחָמֵשׁ מָלַךְ, וְשָׁלֹשׁ וְעֶשְׂרִים דְּאֱוִיל מְרֹדַךְ, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמַסֶּכֶת מְגִלָּה (מגילה יא:), שְׁתַּיִם שֶׁעָבְדוּ לְבֵלְשַׁצַּר, הֲרֵי שִׁשִּׁים וּשְׁתַּיִם:",1,0],[6,3,"וְעֵלָּא מִנְּהוֹן. וּלְמַעְלָה מֵהֶן:",1,0],[6,3,"דִּי לֶהֱוֺן אֲחַשְׁדַּרְפְּנַיָּא. שֶׁיִּתְּנוּ הָאֲחַשְׁדַּרְפְּנַיָּא הַלָּלוּ עֵצָה לִשְׁלֹשָׁה הָאֲפַרְכִּים:",2,0],[6,3,"וּמַלְכָּא לָא לֶהֱוֵא נָזִיק. וְהַמֶּלֶךְ לֹא יְהֵא נִפְסָד בְּשׁוּם דָּבָר מַלְכוּת הַמּוּטָּל עֲלֵיהֶם לַעֲשׂוֹת:",3,0],[6,4,"דָּנִיֵּאל דְּנָה. דָּנִיֵּאל זֶה:",1,0],[6,4,"מִתְנַצַּח. מִתְגַּבֵּר:",2,0],[6,4,"וּמַלְכָּא עֲשִׁית. הַמֶּלֶךְ הָיָה חוֹשֵׁב בְּלִבּוֹ לַהֲקִימוֹ עַל כֻּלָּם:",3,0],[6,5,"הֲווֹ בָעַיִן עִלָּה. הָיוּ מְבַקְּשִׁים עֲלִילָה לִמְצוֹא לְדָנִיֵּאל בִּדְבַר הַמַּלְכוּת, שֶׁיּוּכְלוּ לְהַלְשִׁין עָלָיו:",1,0],[6,6,"דִּי לָא נְהַשְׁכַּח. אָמְרוּ בֵּינֵיהֶם: לֹא נִמְצָא לְדָנִיֵּאל זֶה שׁוּם עֲלִילָה:",1,0],[6,6,"לָהֵן הַשְׁכַּחְנָא עֲלוֹהִי. אֲבָל נִמְצָא עָלָיו עֲלִילָה עַל יְדֵי תּוֹרַת אֱלֹהָיו, אִם נוּכַל לְבַקֵּשׁ מֵאֵת פְּנֵי הַמֶּלֶךְ שׁוּם גְּזֵרָה שֶׁיִּגְזֹר לְהַעֲבִירוֹ עַל תּוֹרָתוֹ, וְהוּא לֹא יְקַיֵּם אֶת מִצְוַת הַמֶּלֶךְ, וַהֲרֵי הָעֲלִילָה:",2,0],[6,7,"הִרְגִּישׁוּ. מְשַׁמְּשׁוּ עַל הַמֶּלֶךְ:",1,0],[6,8,"אִתְיָעַטוּ. נוֹעֲצוּ:",1,0],[6,8,"לְקַיָּמָה קְיָם מַלְכָּא. לְהַחֲזִיק בְּדַת הַמֶּלֶךְ בְּכֹחַ, לְפִי שֶׁמֵחָדָשׁ בָּאתָ לִמְלוֹךְ וּמִמְּדִינָה אַחֶרֶת אַתָּה, וְצָרִיךְ חִזּוּק:",2,0],[6,8,"דִּי יִבְעֵא בָעוּ. אֲשֶׁר יְבַקֵּשׁ שׁוּם בַּקָּשָׁה:",3,0],[6,8,"לָהֵן מִנָּךְ מַלְכָּא. זוּלָתִי מִמְּךָ הַמֶּלֶךְ:",4,0],[6,8,"לְגוֹב אַרְיָוָתָא. לְבוֹר שֶׁאֲרָיוֹת הַמֶּלֶךְ שָׁם:",5,0],[6,9,"תְּקִים אֱסָרָא. תַּעֲמִיד חֹק זֶה:",1,0],[6,9,"דִּי לָא לְהַשְׁנָיָה. שֶׁלֹּא לְשַׁנּוֹת כְּדָת מָדַי וּפָרָס:",2,0],[6,9,"דִּי לָא תֶעְדֵּא. שֶׁלֹּא תַעֲבוֹר:",3,0],[6,11,"כְּדִי יְדַע. וְכַאֲשֶׁר יָדַע:",1,0],[6,11,"וְכַוִּין פְּתִיחָן לֵהּ בְּעִלִּיתֵהּ. בַּעֲלִיָּתוֹ:",2,0],[6,11,"נֶגֶד יְרוּשְׁלֶם. לְצַד בֵּית הַמִּקְדָּשׁ, וְאַף עַל פִּי שֶׁחָרַב, עָשָׂה כְּמוֹ שֶׁאָמַר שְׁלֹמֹה ״וְהִתְפַּלְלוּ אֵלֶיךָ דֶּרֶךְ אַרְצָם״ (מלכים א ח:מח):",3,0],[6,11,"וְזִמְנִין תְּלָתָה. עַרְבִית וְשַׁחֲרִית וּמִנְחָה:",4,0],[6,11,"בָּרֵךְ עַל בִּרְכוֹהִי. כּוֹרֵעַ עַל בִּרְכָּיו:",5,0],[6,11,"כָּל קֳבֵל דִּי הוּא עָבֵד וְגוֹ׳. כְּכָל אֲשֶׁר הָיָה עוֹשֶׂה לִפְנֵי זֹאת:",6,0],[6,12,"הִרְגִּישׁוּ. מִשְׁמְשׁוּ וְתָפְשׁוּ:",1,0],[6,13,"עַל אֱסָר מַלְכָּא. עַל בִּטּוּל אִסּוּר הַמֶּלֶךְ אֲשֶׁר בָּאוּ לְהַלְשִׁין:",1,0],[6,13,"יַצִּיבָא מִלְּתָא. אֱמֶת הַדָּבָר:",2,0],[6,14,"לֹא שָׂם עֲלָךְ מַלְכָּא טְעֵם. לֹא נָתַן לֵב וְעֵצָה לָחוּשׁ עַל גְּזֵרוֹתֶיךָ:",1,0],[6,14,"בָּעֵא בָּעוּתֵהּ. מִתְפַּלֵּל תְּפִלָּתוֹ:",2,0],[6,15,"כְּדִי מִלְּתָא שְׁמַע. כַּאֲשֶׁר שָׁמַע הַדָּבָר:",1,0],[6,15,"שַׂגִּיא בְאֵשׁ עֲלוֹהִי. הַרְבֵּה הֵרַע בְּעֵינָיו, שֶׁהָיָה אוֹהֵב אֶת דָּנִיֵּאל וְקָשֶׁה עָלָיו מִיתָתוֹ:",2,0],[6,15,"וְעַל דָּנִיֵּאל שָׂם בָּל לְשֵׁיזָבוּתֵהּ. עַל דָּנִיֵּאל שָׂם דְּחוּי לִדְחוֹת הַדָּבָר לְהַצִּילוֹ וְאָמַר לָהֶם: אֵינִי מַאֲמִין לָכֶם:",3,0],[6,15,"בָּל. אֵינִי יוֹדֵעַ דֻּגְמָתוֹ, אַךְ עִנְיָנוֹ יוֹרֶה פִּתְרוֹנוֹ:",4,0],[6,15,"וְעַד מְעָלֵי שִׁמְשָׁא. וְעַד בֹּא הַשֶּׁמֶשׁ הָיָה מִשְׁתַּדֵּל לְהַצִּילוֹ, אֲבָל כְּשֶׁהִגִּיעַ זְמַן תְּפִלָּתוֹ כָּרַע לְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל בִּרְכָּיו וְהִתְפַּלֵּל תְּפִלָּתוֹ, וְשׁוּב לֹא הָיָה לוֹ פִּתְחוֹן פֶּה לְהַצִּילוֹ:",5,0],[6,16,"דִּי מַלְכָּא יְהָקֵם. אֲשֶׁר הַמֶּלֶךְ יִגְזֹר וְיַעֲמֹד, לֹא לְאָדָם לְשַׁנּוֹתוֹ:",1,0],[6,18,"וְהֵיתָיִת אֶבֶן חֲדָה. וְהוּבְאַת אֶבֶן אַחַת. בְּכָל אֶרֶץ בָּבֶל אֵין אֶבֶן כִּי אִם לְבֵנִים, כְּמוֹ שֶׁכָּתוּב ״הָבָה נִלְבְּנָה לְבֵנִים״ (בראשית יא:ג). לָמַדְנוּ שֶׁאֵין אֶבֶן בְּבָבֶל, וּלְפִי שָׁעָה הֱבִיאוּהָ מַלְאָכִים מֵאֶרֶץ יִשְׂרָאֵל. אִם הִתְנָה בְּמַעֲשֵׂה בְרֵאשִׁית עַל הַיָּם שֶׁיִּקָּרַע לִבְנֵי יִשְׂרָאֵל, וְעַל הָאֵשׁ שֶׁיִּצְטַנֵּן לַחֲנַנְיָה וַחֲבֵרָיו, וְעַל הָאֲרָיוֹת מֵהַזִּיק לְדָנִיֵּאל, לֹא הִתְנָה עַל זְרִיקַת אֶבֶן וְזַיִן שֶׁלֹּא יַזִּיק בָּאָדָם. וְהַמֶּלֶךְ אָמַר: מֵעִם הָאֲרָיוֹת אִי אֶפְשָׁר לְסַלְּקוֹ, שֶׁכְּבָר נִגְזְרָה גְּזֵרָה, אֶזְדַּהֵר בּוֹ מֵהֶזֵּקַת אָדָם, וְהַנֵּס אִם יָבֹא יָבֹא (ספרים אחרים אומרים):",1,0],[6,18,"וְשָׂמַת עַל פֻּם גּוּבָּא. הוּשְׂמָה עַל פִּי הַגּוּמָּא׃",2,0],[6,18,"בְּעִזְקְתֵיהּ. בְּטַבַּעְתּוֹ, שֶׁלֹּא יְזִיזוּהָ מִמְּקוֹמוֹ וְיַשְׁלִיכוּ עָלָיו אֲבָנִים לְהָרְגוֹ:",3,0],[6,18,"דִּי לָא תִשְׁנֵא צְבוּ בְדָנִיֵּאל. שֶׁלֹּא יִשְׁתַּנֶּה רְצוֹנוֹ, כְּלוֹמַר שֶׁלֹּא יַעֲשׂוּ לוֹ הֶיזֵּק שֶׁלֹּא כִּרְצוֹנוֹ (ספרים אחרים כִּרְצוֹנָם):",4,0],[6,19,"וּבָת טְוָת. לָן בְּתַעֲנִית:",1,0],[6,19,"וְדַחֲוָן. וְשֻׁלְחָן בַּמִּשְׁנָה (כלים בבא מציעא ה:א); כָּךְ פֵּתַר דּוֹנַשׁ; לֹא הִכְנִיסוּ לְפָנָיו שֻׁלְחָן לֶאֱכֹל:",2,0],[6,19,"וְשִׁנְתֵּהּ נַדַּת עֲלוֹהִי. נָדְדָה שְׁנָתוֹ:",3,0],[6,20,"בִּשְׁפַּרְפָּרָא. בַּעֲלוֹת שַׁחַר, וְהַרְבֵּה יֵשׁ בְּתַרְגּוּם יוֹנָתָן:",1,0],[6,20,"יְקוּם בְּנָגְהָא. עָמַד לְאוֹר הַבֹּקֶר, וְלֹא בְּשָׁלֹשׁ שָׁעוֹת כִּשְׁאָר מְלָכִים:",2,0],[6,20,"וּבְהִתְבְּהָלָה לְגֻבָּא דִי אַרְיָוָתָא אֲזַל. וּבִבְהָלָה לַחֲפִירַת הָאֲרָיוֹת אֲזַל:",3,0],[6,23,"חֲבוּלָה לָא עַבְדֵת. שׁוּם דְּבַר כִּעוּר וְשֶׁקֶר לֹא עָשִׂיתִי:",1,0],[6,24,"שַׂגִּיא טְאֵב עֲלוֹהִי. הַרְבֵּה הוּטַב בְּעֵינָיו:",1,0],[6,24,"וּלְדָנִיֵּאל. וְאֶת דָּנִיֵּאל צִוָּה לְהַעֲלוֹת מִן הַבּוֹר:",2,0],[6,24,"דִּי הֵימַן בֵּאלָהֵהּ. אֲשֶׁר הֶאֱמִין בֵּאלֹהָיו:",3,0],[6,25,"דִּי אֲכַלוּ קַרְצוֹהִי. אֲשֶׁר הִלְשִׁינוּ עָלָיו:",1,0],[6,25,"וְלָא מְטוֹ לְאַרְעִית גּוּבָּא. לֹא הִגִּיעוּ לְתַחְתִּיּוֹת הַבּוֹר עַד שֶׁמָּשְׁלוּ בָּהֶם הָאֲרָיוֹת וְכָל עַצְמוֹתֵיהֶם הַדִּיקוּ:",2,0],[6,26,"בֵּאדַיִן דָּרְיָוֶשׁ מַלְכָּא וְכוּ׳ דִּי דָאֲרִין בְּכָל אַרְעָא שַׁדְּרִין בְּכָל הָאָרֶץ, שְׁלָמְכוֹן יִסְגֵּא:",1,0],[6,29,"וּבְמַלְכוּת כּוֹרֶשׁ. שֶׁמָּלַךְ אַחַר דָּרְיָוֶשׁ, שֶׁלֹּא מָלַךְ דָּרְיָוֶשׁ הַמָּדִי אֶלָּא שָׁנָה אַחַת וְנֶהֱרַג בַּמִּלְחָמָה, כַּאֲשֶׁר כָּתוּב בְּסֵפֶר יוֹסֵף בֶּן גּוּרְיוֹן, וְהִמְלִיכוּ אֶת כּוֹרֶשׁ חֲתָנוֹ עֲלֵיהֶם בְּתוֹךְ הַחַיִל:",1,0],[7,1,"בֵּאדַיִן חֶלְמָא כְּתַב. אָז (הַחֲלוֹם כָּתַב) וְרָאשֵׁי הַדְּבָרִים אָמַר:",1,0],[7,2,"וַאֲרוּ. וְהִנֵּה:",1,0],[7,2,"אַרְבַּע רוּחֵי שְׁמַיָּא מְגִיחָן וְגוֹ׳. אַרְבַּע רוּחוֹת נוֹשְׁבוֹת בָּאוֹת מֵאַרְבַּע רוּחוֹת הָעוֹלָם וְנִלְחָמוֹת עִם הַיָּם הַגָּדוֹל וְסוֹעֲרוֹת אוֹתוֹ:",2,0],[7,3,"וְאַרְבַּע חֵיוָן. וְאַרְבַּע חַיּוֹת:",1,0],[7,3,"שָׁנְיָן דָּא מִן דָּא. מְשֻׁנּוֹת זוֹ מִזּוֹ:",2,0],[7,4,"קַדְמָיְתָא כְאַרְיֵה וְגַפִּין דִּי נְשַׁר לַהּ. הִיא כְּאַרְיֵה וְלָהּ כַּנְפֵי נֶשֶׁר; זוֹ הִיא מַלְכוּת בָּבֶל שֶׁהָיְתָה מוֹשֶׁלֶת בְּאוֹתָהּ שָׁעָה, וְכָךְ רָאָה אוֹתָהּ יִרְמְיָה, שֶׁנֶּאֱמַר ״עָלָה אַרְיֵה מִסֻּבְּכוֹ״ (ירמיהו ד:ז), וְאוֹמֵר ״הִנֵּה כַנֶּשֶּׁר יִדְאֶה וְגוֹ׳״ (ירמיהו מח:מ):",1,0],[7,4,"עַד דִּי מְרִיטוּ גַפַּהּ. נִמְרְטוּ כְּנָפֶיהָ, זוֹ הִיא רֶמֶז לְמַפַּלְתָּהּ:",2,0],[7,4,"וּנְטִילַת מִן אַרְעָא. לְשׁוֹן נִסְתַּלֵּק מִן הָאָרֶץ, רֶמֶז שֶׁתִּבָּטֵל הַמַּלְכוּת מִן הָאָרֶץ:",3,0],[7,4,"וּלְבַב אֱנָשׁ. לְשׁוֹן חֲלָשׁוּת, כְּמוֹ ״יֵדְעוּ גוֹיִם אֱנוֹשׁ הֵמָּה סֶּלָה״ (תהלים ט:כא):",4,0],[7,5,"אׇחֳרִי. אַחֶרֶת:",1,0],[7,5,"תִּנְיָנָה. שֶׁעָלְתָה שְׁנִיָּה מִן הַיָּם:",2,0],[7,5,"דָּמְיָה לְדֹב. זֶה רֶמֶז לְמַלְכוּת פָּרַס שֶׁתִּמְלֹךְ אַחַר בָּבֶל, שֶׁאוֹכְלִים וְשׁוֹתִים כַּדֹּב וּמְסֻרְבָּלִים בְּבָשָׂר כַּדֹּב:",3,0],[7,5,"דָּמְיָה לְדֹב. לְדֹב כְּתִיב, כְּמוֹ ״דִּיבָא״ תַּרְגּוּם שֶׁל זְאֵב, שֶׁאַף זְאֵב נִקְרֵאת מַלְכוּת פָּרַס, שֶׁנֶּאֱמַר: ״עַל כֵּן הִכָּם אַרְיֵה מִיַּעַר זְאֵב עֲרָבוֹת יְשָׁדְדֵם״ (ירמיהו ה:ו):",4,0],[7,5,"וְלִשְׂטַר חַד הֳקִימַת. וּלְצַד אֶחָד עָמְדָה, רֶמֶז לְשֶׁיִּפְסֹק מַלְכוּת בָּבֶל, תַּמְתִּין פָּרַס שָׁנָה אַחַת שֶׁתִּמְלֹךְ מָדַי:",5,0],[7,5,"וּתְלָת עִלְעִין בְּפֻמַּהּ. שָׁלֹשׁ צְלָעוֹת. רַבּוֹתֵינוּ פֵּרְשׁוּ: שָׁלֹשׁ מְדִינוֹת הָיוּ תָּמִיד מוֹרְדוֹת בָּהּ וּמַשְׁלִימוֹת עִמָּהּ, פְּעָמִים בּוֹלַעְתָּן וּפְעָמִים פּוֹלַטְתָּן (קידושין עב.); זֶהוּ בְּפֻמַּהּ בֵּין שִׁנֶּיהָ פְּעָמִים חוּץ לְשִׁנֶּיהָ פְּעָמִים לְתוֹכָן. וַאֲנִי אוֹמֵר: תְּלָת עִלְעִין שְׁלֹשָׁה מְלָכִים שֶׁיַּעַמְדוּ לְפָרַס: כּוֹרֶשׁ וַאֲחַשְׁוֵרוֹשׁ וְדָרְיָוֶשׁ שֶׁבָּנָה הַבַּיִת:",6,0],[7,5,"בָּשָׂר שַׂגִּיא. בָּשָׂר הַרְבֵּה:",7,0],[7,6,"גַּפִּין אַרְבַּע וְגוֹ׳ וְאַרְבְּעָה רֵאשִׁין. הֵם אַרְבָּעָה מוֹשְׁלִים שֶׁחִלֵּק לָהֶם אֲלֶכְּסַנְדְּרוֹס מוּקְדּוֹן בְּמוֹתוֹ אֶת מַלְכוּתוֹ, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יוֹסֵף בֶּן גּוּרְיוֹן; שֶׁהַחַיָּה הַזֹּאת הַשְּׁלִישִׁית הִיא מַלְכוּת אַנְטִיוֹכוֹס, וְנִקְרָא נְמַר עַל שֵׁם שֶׁהָיְתָה גּוֹזֶרֶת גְּזֵרוֹת עַל יִשְׂרָאֵל מְנֻמָּרוֹת וּמְשֻׁנּוֹת זוֹ מִזּוֹ:",1,0],[7,6,"וְשָׁלְטָן יְהִב לַהּ. וּמֶמְשָׁלָה נִתְּנָה לָהּ:",2,0],[7,7,"בְּחֶזְוֵי לֵילְיָא. בְּלַיְלָה אַחֶרֶת. הַשָּׁלֹשׁ הָרִאשׁוֹנוֹת רָאָה בְּלַיְלָה אַחַת, וְזוֹ בְּלַיְלָה אַחֶרֶת, עַל שֵׁם שֶׁהִיא שְׁקוּלָה כְּנֶגֶד שְׁלָשְׁתָּן בְּוַיִּקְרָא רַבָּה:",1,0],[7,7,"וְשִׁנַּיִן דִּי פַרְזֶל לַהּ. שִׁנֵּי בַרְזֶל לָהּ:",2,0],[7,7,"וּמַדֱּקָה. מְדִיקָה וְשׁוֹחֶקֶת הַדֵּק:",3,0],[7,7,"וּשְׁאָרָא. מוֹתַר אֲכִילָתָהּ:",4,0],[7,7,"וְקַרְנַיִן עֲשַׂר. עֶשֶׂר קַרְנוֹת. זוֹ פֵּרֵשׁ לוֹ הַמַּלְאָךְ (דניאל ז:כד), שֶׁהֵם עֲשָׂרָה מְלָכִים שֶׁיַּעַמְדוּ לְרוֹמִי קֹדֶם לְאַסְפַּסְיָנוּס שֶׁחָרַב אֶת הַבַּיִת:",5,0],[7,8,"וַאֲלוּ. כְּמוֹ ״וַאֲרוּ״ (דניאל ב:לא), לְשׁוֹן הִנֵּה:",1,0],[7,8,"מְמַלִּל רַבְרְבָן. דִּבְרֵי גַּאֲוָה, הוּא טִיטוּס שֶׁאָמְרוּ חֲכָמֵינוּ זִכְרוֹנָם לִבְרָכָה (גיטין נו:) שֶׁחֵרֵף וְגִדֵּף וְנִכְנַס לַהֵיכָל בְּעַזּוּת פָּנִים:",2,0],[7,9,"דִּי כָרְסָוָן רְמִיו. כִּסְאוֹת הוּטְלוּ וְנִתְקְנוּ לֵישֵׁב בְּמִשְׁפָּט, אֶחָד לְדִין וְאֶחָד לִצְדָקָה לְיִשְׂרָאֵל:",1,0],[7,9,"וְעַתִּיק יוֹמִין יְתִב. הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב לְמִשְׁפָּט עַל הַמַּלְכוּת הַזּוֹ וְעַל שֶׁלְּפָנֶיהָ, שֶׁהִכְעִיסוּ לְפָנָיו וְהֵצִיקוּ לְבָנָיו:",2,0],[7,9,"כִּתְלַג חִוָּר. לְלַבֵּן עֲוֹנוֹת עַמּוֹ:",3,0],[7,9,"וּשְׂעַר רֵאשֵׁהּ כַּעֲמַר נְקֵא. מְנַקֶּה עַצְמוֹ מִזְּכֻיּוֹת שֶׁיֵּשׁ לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לְפָנָיו, וּמְשַׁלֵּם לָהֶם כָּל שְׂכָרָם בָּעוֹלָם הַזֶּה (ויקרא רבה):",4,0],[7,10,"דִּי נוּר. שֶׁל אֵשׁ:",1,0],[7,10,"נוּר דָּלֵק. אֵשׁ בּוֹעֵרָה:",2,0],[7,10,"נָגֵד וְנָפֵק. מוֹשֵׁךְ וְיָצָא:",3,0],[7,10,"יְשַׁמְּשׁוּנֵּהּ. לְעַתִּיק יוֹמִין:",4,0],[7,10,"דִּינָא יְתִב. הַמִּשְׁפָּט נִתְיַשֵּׁב לְפָנָיו:",5,0],[7,10,"וְסִפְרִין פְּתִיחוּ. הַסְּפָרִים נִפְתְּחוּ, סִפְרֵי הָעֲבֵירוֹת וְהָרָעוֹת שֶׁעָשׂוּ:",6,0],[7,11,"מִן קָל מַלְיָא. מִקּוֹל הַדְּבָרִים הַגְּבוֹהִים שֶׁהַקֶּרֶן מְדַבֶּרֶת עָלְתָה חֲמָתוֹ שֶׁל עַתִּיק יוֹמִין:",1,0],[7,11,"עַד דִּקְטִילַת חֵיוְתָא וְהוּבַד גִּשְׁמַהּ. אֲבַד גּוּפָהּ:",2,0],[7,11,"לִיקֵדַת אֶשָּׁא. לְלַבַּת אֵשׁ, הוּא אִשּׁוֹ שֶׁל יַעֲקֹב: ״וְהָיָה בֵית יַעֲקֹב אֵשׁ וְגוֹ׳״ (עובדיה א:יח):",3,0],[7,12,"וּשְׁאָר חֵיוָתָא הֶעְדִּיו שָׁלְטָנְהוֹן. וּלְשְׁאָר הַמַּלְכֻיּוֹת הֵסִירוּ מִן הַשָּׁמַיִם מֶמְשַׁלְתְּהוֹן׃",1,0],[7,12,"וְאַרְכָה בְחַיִּין יְהִיבַת לְהוֹן. וּזְמַן נִתַּן לָהֶם בַּחַיִּים עַד יוֹם מוֹעֵד לֶעָתִיד לָבֹא מִלְחֲמוֹת גּוֹג וּמָגוֹג (יחזקאל לח:א-ג):",2,0],[7,12,"אַרְכָה. הַמְתָּנָה:",3,0],[7,13,"כְּבַר אֱנָשׁ אָתֵה. הוּא מֶלֶךְ הַמָּשִׁיחַ:",1,0],[7,13,"וְעַד עַתִּיק יוֹמַיָּא. שֶׁהָיָה יוֹשֵׁב בַּמִּשְׁפָּט וְדָן אֶת הָאוּמּוֹת:",2,0],[7,13,"מַטָּה. הִגִּיעַ׃",3,0],[7,14,"וְלֵהּ יְהִיב שָׁלְטָן. וּלְאוֹתוֹ בֶּן אָדָם נָתַן מֶמְשֶׁלֶת הָאוּמּוֹת. דִּימָּה כַּחַיּוֹת, וְיִשְׂרָאֵל דִּימָּה כְּבֶן אָדָם עַל שֶׁהֵם עֲנְוְתָנִים וּתְמִימִים:",1,0],[7,14,"דִּי לָא יֶעְדֵּה. לָא יָסוּר:",2,0],[7,15,"אֶתְכְּרִיַּת רוּחִי. לְשׁוֹן ״כִּי יִכְרֶה״ (שמות כב:לג), וְלָשׁוֹן אֲרַמִּי וְעִבְרִי שָׁוִין בּוֹ. כְּלוֹמַר: נִסְחָה מִתּוֹךְ עֹמֶק כְּרִיָּתָהּ:",1,0],[7,15,"בְּגוֹ נִדְנֶה. בְּתוֹךְ תִּיקָה, נַרְתֵּק שֶׁלּוֹ, כְּלוֹמַר: נִבְהֲלָה רוּחִי בְּתוֹךְ הַגּוּף מִן הַחֲלוֹם הַזֶּה:",2,0],[7,16,"קִרְבֵת עַל חַד מִן קָאֲמַיָּא. קָרַבְתִּי אֵצֶל אֶחָד מִן הָעוֹמְדִים שָׁם לִפְנֵי עַתִּיק הַיָּמִים. הַמַּלְאָכִים נִקְרְאוּ עוֹמְדִים, שֶׁנֶּאֱמַר (זכריה ג:ז) ״בֵּין הָעֹמְדִים הָאֵלֶּה״, מִפְּנֵי שֶׁאֵין לָהֶם קְפָצִים:",1,0],[7,16,"וְיַצִּיבָא אֶבְעֵא מִנֵּהּ. וְהָאֱמֶת שָׁאַלְתִּי מִמֶּנּוּ:",2,0],[7,17,"אַרְבְּעָה מַלְכִין. אַרְבַּע מַלְכִיּוֹת:",1,0],[7,18,"וִיקַבְּלוּן מַלְכוּתָא קַדִּישֵׁי עֶלְיוֹנִין. אֵלּוּ יִשְׂרָאֵל שֶׁיִּטְּלוּ הַמַּלְכוּת מֵהָרְבִיעִית:",1,0],[7,19,"אֱדַיִן צְבִית לְיַצָּבָא. אָז חָפַצְתִּי לַעֲמֹד עַל הָאֱמֶת מִן הַחַיָּה הָרְבִיעִית:",1,0],[7,19,"דִּי הֲוָת שָׁנְיָה מִן כָּלְּהֵין דְּחִילָה יַתִּירָה. אֲשֶׁר הָיְתָה מְשֻׁנָּה מִכֻּלָּן בְּאֵימָה יְתֵרָה:",2,0],[7,20,"וּנְפַלָה מִן קֳדָמַהּ תְּלָת. וְנָפְלוּ מִפָּנֶיהָ שָׁלֹשׁ מִן הָרִאשׁוֹנוֹת:",1,0],[7,20,"וְקַרְנָא דִכֵּן וְעַיְנִין לַהּ. וְהַקֶּרֶן אֲשֶׁר כָּזֹאת וְעֵינַיִם לָהּ, כְּכָתוּב לְמַעְלָה (דניאל ז:ח):",2,0],[7,21,"חָזֵה הֲוֵית. בַּחֲלוֹמִי הָרִאשׁוֹן שֶׁסִּפַּרְתִּי לְמַעְלָה (דניאל ז:א-ח):",1,0],[7,21,"עִם קַדִּישִׁין. עַם יִשְׂרָאֵל:",2,0],[7,22,"וְדִינָא יְהִב לְקַדִּישֵׁי עֶלְיוֹנִין. וּנְקָמָה נָתַן לָהֶם מִמֶּנָּה׃",1,0],[7,23,"כֵּן אֲמַר. כֹּה עָנַנִי הַמַּלְאָךְ הַפּוֹתֵר לִי אֶת הַחֲלוֹם:",1,0],[7,24,"וְקַרְנַיָּא עֲשַׂר. וְקַרְנַיִם עֶשֶׂר אֲשֶׁר רָאִיתִי לָהּ, זֶה פִּתְרוֹנוֹ:",1,0],[7,24,"מִנַּהּ מַלְכוּתָא. מֵאוֹתָהּ הַמַּלְכוּת:",2,0],[7,24,"וְאָחֳרָן יְקוּם אַחֲרֵיהוֹן. וְהָאַחֲרוֹן יָקוּם אַחֲרֵיהֶן, הוּא טִיטוּס:",3,0],[7,25,"לְצַד עִלָּאָה. כְּלַפֵּי מַעְלָה:",1,0],[7,25,"וּלְקַדִּישֵׁי עֶלְיוֹנִין יְבַלֵּא. וּלְיִשְׂרָאֵל יַטְרִיחַ וְיָצִיק:",2,0],[7,25,"וְיִסְבַּר לְהַשְׁנָיָא זִמְנִין וְדָת. יִדְמֶה בְּלִבּוֹ לְהַעֲבִירָם עַל כָּל מוֹעֲדֵיהֶם וְדָתֵיהֶם׃",3,0],[7,25,"עַד עִדָּן וְעִדָּנִין וּפְלַג עִדָּן. קֵץ סָתוּם הוּא זֶה, כַּאֲשֶׁר נֶאֱמַר לְדָנִיֵּאל ״סְתֹם הַדְּבָרִים וַחֲתֹם״ (דניאל יב:ד), וּדְרָשׁוּהוּ הָרִאשׁוֹנִים אִישׁ לְפִי דַעְתּוֹ, וְכָלוּ הַקִּצִּים. וְיֵשׁ לָנוּ לְפוֹתְרוֹ עוֹד כַּאֲשֶׁר רָאִיתִי כָתוּב בְּשֵׁם רַב סְעַדְיָה: הֵם אֶלֶף וּשְׁלֹשׁ מֵאוֹת וּשְׁלֹשִׁים וְחָמֵשׁ שָׁנִים הָאָמוּר בְּסוֹף הַסֵּפֶר ״אַשְׁרֵי הַמְחַכֶּה וְגוֹ׳״ (דניאל יב:יב); וּפֵרֵשׁ הַמּוֹעֵד עַד עֵת שְׁנֵי עִתִּים וַחֲצִי עֵת, וְאָמַר שֶׁהָעִתִּים הֵם אַרְבַּע מֵאוֹת וּשְׁמוֹנִים שֶׁמִּיּוֹם צֵאתָם מִמִּצְרַיִם עַד שֶׁנִּבְנָה הַבַּיִת, וְאַרְבַּע מֵאוֹת וְעֶשֶׂר יְמֵי מִקְדָּשׁ רִאשׁוֹן הֲרֵי שְׁמוֹנֶה מֵאוֹת וְתִשְׁעִים, וְעוֹד חֲצִי הָעֵת הַזֶּה ארבַּע מֵאוֹת אַרְבָּעִים וְחָמֵשׁ הֲרֵי אֶלֶף שְׁלוֹשׁ מֵאוֹת שְׁלוֹשִׁים וְחָמֵשׁ. אֶת אֵלֶּה חֲשׁוֹב מֵעֵת הוּסַר הַתָּמִיד עַד שׁוּב זֶבַח הַתָּמִיד אֶל מְקוֹמוֹ, וְהוּא הוּסַר שֵׁשׁ שָׁנִים לִפְנֵי הַחֻרְבָּן; וְיֵשׁ קְצָת רְאָיָה בְּסֵפֶר זֶה. וְעוֹד יֵשׁ מְבִיאִין רְאָיָה לְחֶשְׁבּוֹן זֶה ״הַסְתֵּר אַסְתִּיר פָּנַי״ (דברים לא:יח) ״הַסְתֵּר אַסְתִּיר״ בְּגִימַטְרִיָּא אֶלֶף וּשְׁלוֹשׁ מֵאוֹת שְׁלוֹשִׁים וְחָמֵשׁ:",4,0],[7,26,"וְדִינָא יִתִּב. וְהַדִּין נִתְיַשֵּׁב לִפְנֵי הַמָּקוֹם׃",1,0],[7,26,"וְשָׁלְטָנֵהּ יְהַעְדּוֹן. וְשׁוּלְטָנוּ וּמֶמְשֶׁלֶת שֶׁל אוֹתוֹ הַמַּלְכוּת יָסִירוּ מִן הַשָּׁמַיִם:",2,0],[7,27,"וְיִשְׁתַּמְּעוּן. יִהְיוּ נִשְׁמָעִים לְמִצְוָתוֹ לַעֲשׂוֹתוֹ:",1,0],[7,28,"עַד כֹּה. עַד כָּאן:",1,0],[7,28,"שַׂגִּיא רַעְיוֹנַי יְבַהֲלוּנַּנִי. הַרְבֵּה הָיוּ מַחְשְׁבוֹתַי מְבַהֲלוֹת אוֹתִי:",2,0],[7,28,"וְזִיוַי יִשְׁתַּנּוֹן. מַרְאִית יוֹפִי וְתֹאֲרִי נִשְׁתַּנּוּ:",3,0],[7,28,"בְּלִבִּי נִטְרֵת. בְּלִבִּי צָפַנְתִּי:",4,0],[8,1,"בִּשְׁנַת שָׁלוֹשׁ. אַחֲרֵי הַמַּרְאֶה הָרִאשׁוֹן, אַחַר שֶׁנִּרְאָה אֵלַי בַּתְּחִלָּה הַחֲלוֹם הָאָמוּר לְמַעְלָה, שֶׁנִּרְאָה לוֹ בִּשְׁנַת אַחַת לְבֵלְשַׁצַּר (לעיל ז:א):",1,0],[8,2,"עַל אוּבַל אוּלָי. עַל הַנָּהָר שֶׁשְּׁמוֹ אוּלָי:",1,0],[8,3,"וְלוֹ קַרְנָיִם. רֶמֶז לְמַלְכוּת פָּרַס וּמָדַי:",1,0],[8,3,"וְהָאַחַת גְּבוֹהָה מִן הַשֵּׁנִית. רֶמֶז לְמַלְכוּת פָּרַס שֶׁגְּדוֹלָה מִמַּלְכוּת מָדַי, שֶׁמַּלְכוּת מָדַי לֹא הָיְתָה אֶלָּא שָׁנָה אַחַת, שֶׁנֶּאֱמַר (לקמן ט:א) ״בִּשְׁנַת אַחַת לְדָרְיָוֶשׁ בֶּן אֲחַשְׁוֵרוֹשׁ מִזֶּרַע מָדַי״, וְשָׁנִינוּ בְּסֵדֶר עוֹלָם: לֹא מָצִינוּ שָׁנָה לְמָדַי בַּכְּתוּבִים אֶלָּא זוֹ בִּלְבַד:",2,0],[8,3,"וְהַגְּבֹהָה עוֹלָה בָּאַחֲרוֹנָה. רֶמֶז הוּא שֶׁתַּקְדִּים מַלְכוּת מָדַי לְמַלְכוּת פָּרַס:",3,0],[8,5,"הָיִיתִי מֵבִין. הָיִיתִי מִסְתַּכֵּל בּוֹ:",1,0],[8,5,"צְפִיר. שָׂעִיר:",2,0],[8,5,"וְאֵין נוֹגֵעַ בָּאָרֶץ. דּוֹמֶה הָיָה כִּמְדַלֵּג בָּאֲוִיר:",3,0],[8,5,"קֶרֶן חָזוּת. קֶרֶן גָּדוֹל לְמַרְאֵה הָעָיִן:",4,0],[8,7,"וַיִּתְמַרְמַר אֵלָיו. וַיִּלָּחֵם אֵלָיו, הוּא לְשׁוֹן כַּעַס מַר:",1,0],[8,8,"חָזוּת אַרְבַּע. מַרְאֵה אַרְבַּע קְרָנַיִם:",1,0],[8,9,"וּמִן הָאַחַת מֵהֶם. וּמֵאַחַת מֵאֵלּוּ הַמַּלְכֻיּוֹת:",1,0],[8,9,"יָצָא קֶרֶן אַחַת. מַלְכוּת טִיטוּס יוֹצֵאת מִמֶּנּוּ:",2,0],[8,9,"מִצְּעִירָה. מַלְכוּת מוּצְעֶרֶת וְנִבְזֵית, כְּמוֹ שֶׁקָּרְאוּ לְמַעְלָה קֶרֶן אַחַת מִצְּעִירָה. וְהוּא עַל עִנְיָן שֶׁנֶּאֱמַר ״בָּזוּי אַתָּה מְאֹד״ (עובדיה א:ב):",3,0],[8,9,"וַתִּגְדַּל יֶתֶר. וַתִּגְדַּל מְאֹד:",4,0],[8,9,"אֶל הַנֶּגֶב. הוּא מִצְרַיִם שֶׁהִיא בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל:",5,0],[8,9,"וְאֶל הַצֶּבִי. אֶרֶץ יִשְׂרָאֵל שֶׁנִּקְרֵאת אֶרֶץ צְבִי, כְּעִנְיָן שֶׁנֶּאֱמַר ״נַחֲלַת צְבִי צִבְאוֹת גּוֹיִם״ (ירמיהו ג:יט):",6,0],[8,10,"עַד צְבָא הַשָּׁמָיִם. הֵם יִשְׂרָאֵל שֶׁנִּמְשְׁלוּ לַכּוֹכָבִים (בראשית כב:יז):",1,0],[8,11,"וְעַד שַׂר הַצָּבָא. הוּא בֵּית הַמִּקְדָּשׁ שֶׁהוּא בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. שַׂר הַצָּבָא כְּלַפֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא חֵרֵף.",1,0],[8,11,"וּמִמֶּנּוּ הוּרַם הַתָּמִיד. וְעַל יְדֵי גְדוּדָיו וְחֵילוֹתָיו שֶׁשָּׁלַח לִירוּשָׁלַיִם בָּטֵל הַתָּמִיד שֶׁשָּׁלַח שָׁם נִירוֹן קֵיסָר שַׂר צְבָאוֹ; כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמַסֶּכֶת גִּטִּין וּבְגוֹרְיוֹן:",2,0],[8,12,"וְצָבָא תִּנָּתֵן עַל הַתָּמִיד בְּפָשַׁע. וּזְמַן מוֹעֵד נִתַּן לִהְיוֹת הַתָּמִיד מְסֻלָּק בִּשְׁבִיל פֶּשַׁע שׁוֹמֵם הִיא עֲבוֹדָה זָרָה. כְּלוֹמַר שֶׁתְּהֵא עֲבוֹדָה זָרָה נִתֶּנֶת בִּירוּשָׁלַיִם תְּמוּרַת הַתָּמִיד. וְכֵן הִיא קְרוּיָה בַּסֵּפֶר הַזֶּה בְּכַמָּה מְקוֹמוֹת, שֶׁנֶּאֱמַר ״עַד מָתַי הֶחָזוֹן הַתָּמִיד וְהַפֶּשַׁע שֹׁמֵם״ (דניאל ח:יג), וְאוֹמֵר ״מֵעֵת הוּסַר הַתָּמִיד וְלָתֵת שִׁקּוּץ שֹׁמֵם״ (דניאל יב:יא):",1,0],[8,12,"וְצָבָא. זְמַן, כְּמוֹ ״הֲלֹא צָבָא לֶאֱנוֹשׁ עֲלֵי אָרֶץ״ (אִיּוֹב ז:א):",2,0],[8,12,"וְתַשְׁלֵךְ אֱמֶת אַרְצָה. תּוֹרַת אֱמֶת הִשְׁפִּילָה:",3,0],[8,13,"אֶחָד קָדוֹשׁ. אֶחָד מִן הַמַּלְאָכִים:",1,0],[8,13,"וַיֹּאמֶר. אוֹתוֹ הַמַּלְאָךְ:",2,0],[8,13,"לַפַּלְמוֹנִי. הֲרֵי תֵּיבָה זוֹ כִּשְׁתַּיִם: לִפְלוֹנִי אַלְמוֹנִי. וְתִרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל בְּסֵפֶר שְׁמוּאֵל (שמואל א כא:ג): ״כְּסִי וְטָמִיר״, כְּמוֹ ״כִּי יִפָּלֵא מִמְּךָ דָבָר״ (דברים יז:ח). אַלְמוֹנִי, אַלְמוֹן מִבְּלִי שֵׁם, שֶׁלֹּא פֵּירַשׁ לוֹ מַהוּ וּמַה שְּׁמוֹ:",3,0],[8,13,"לַפַּלְמוֹנִי הַמְדַבֵּר. לַמַּלְאָךְ שֶׁהָיָה מְדַבֵּר וְגוֹזֵר גְּזֵרוֹת, וְצָבָא הַמּוֹעֵד תִּנָּתֵן עַל הַתָּמִיד בְּפֶשַׁע:",4,0],[8,13,"עַד מָתַי הֶחָזוֹן. הַזֶּה אֲשֶׁר עַל הַתָּמִיד לִהְיוֹת מְסֻלָּק וְהַפֶּשַׁע שֹׁמֵם יִהְיֶה נָתוּן תַּחְתָּיו. פֶּשַׁע שֹׁמֵם עֲבוֹדָה זָרָה מֵעוֹבְדֵי כוֹכָבִים שֶׁהִיא כְּאֶבֶן דּוֹמֵם, וְכֵן הִיא קְרוּיָה בַּסֵּפֶר הַזֶּה בְּכַמָּה מְקוֹמוֹת, שֶׁנֶּאֱמַר עַד מָתַי הֶחָזוֹן הַתָּמִיד וְהַפֶּשַׁע שֹׁמֵם, וְאוֹמֵר (דניאל יב:יא) ״מֵעֵת הוּסַר הַתָּמִיד וְלָתֵת שִׁקּוּץ שֹׁמֵם״:",5,0],[8,13,"שׁוֹמֵם. לְשׁוֹן אִלֵּם וּמְשֻׁתָּק, כְּמוֹ ״אֶשְׁתּוֹמַם כְּשָׁעָה חֲדָא״ (דניאל ד:טז), ״וָאֵשֵׁב שָׁם שִׁבְעַת יָמִים מַשְׁמִים בְּתוֹכָם״ (יחזקאל ג:טו) כְּמוֹ אִלֵּם:",6,0],[8,13,"תֵּת וְקֹדֶשׁ וְצָבָא מִרְמָס. לָתֵת אֶת מְכוֹן הַמִּקְדָּשׁ וְאֶת צְבָא הַשָּׁמַיִם אֲשֶׁר הִפִּיל לָאָרֶץ מִרְמָס לְרַגְלָיו, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה ״וַתַּפֵּל אַרְצָה מִן הַצָּבָא וּמִן הַכּוֹכָבִים״ (דניאל ח:י):",7,0],[8,13,"וְקֹדֶשׁ וְצָבָא. וָ״ו יְתֵרָה, וְהַרְבֵּה כָּאֵלֶּה בַּמִּקְרָא: ״נִרְדָּם וְרֶכֶב וָסוּס״ (תהילים עו:ז), וְאַף בִּלְשׁוֹן בְּנֵי אָדָם יֵשׁ מְדַבְּרִים כֵּן:",8,0],[8,14,"עַד עֶרֶב בֹּקֶר אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת. רָאִיתִי פָּתַר בְּשֵׁם רַבֵּינוּ סְעַדְיָה לְדָבָר, וּכְבָר עָבַר וּפָתַר עוֹד: עַד עֶרֶב בֹּקֶר עַד שֶׁיָּבוֹא אוֹתוֹ הָעֶרֶב שֶׁנֶּאֱמַר בּוֹ ״וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר״ (זכריה יד:ז); וּבְטוּחִים אָנוּ כִּי ״דְּבַר אֱלֹהֵינוּ יָקוּם לְעוֹלָם״ (ישעיהו מ:ח), לֹא יוּפַר. וַאֲנִי אוֹמֵר, כִּי הָעֶרֶב וְהַבֹּקֶר הָאָמוּר כָּאן גִּימַטְרִיָּא הוּא, וְיֵשׁ סֶמֶךְ לַדָּבָר מִשְּׁנֵי טְעָמִים: הָאֶחָד, שֶׁיְּהֵא חֶשְׁבּוֹן זֶה מְכֻוָּן עִם חֶשְׁבּוֹן אַחֵר שֶׁבְּסוֹף הַסֵּפֶר; וְהַשֵּׁנִי, שֶׁאָמַר גַּבְרִיאֵל לְדָנִיֵּאל לְמַטָּה בָּעִנְיָן: ״וּמַרְאֵה הָעֶרֶב וְהַבֹּקֶר אֲשֶׁר נֶאֱמַר אֱמֶת הוּא״ (דניאל ח:כו), וְאִם לֹא רֶמֶז הַחֶשְׁבּוֹן הוּא תָּלוּי, לָמָּה חָזַר וְכָפַל אוֹתוֹ לוֹמַר ״אֱמֶת הוּא״. וְהַחוֹזֶה נִצְטַוָּה לִסְתֹּם וְלַחְתֹּם הַדָּבָר (דניאל ט:כד; יב:ד), וְאַף הוּא לֹא נִגְלָה בְּלָשׁוֹן סָתוּם וְחָתוּם. וְאָנוּ נוֹחִיל לְהַבְטָחַת מַלְכֵּנוּ קֵץ אַחַר קֵץ; וּבַעֲבוּר קֵץ הַדּוֹרֵשׁ, נוֹדַע כִּי טָעָה בְּמִדְרָשָׁיו, וְהַבָּא אַחֲרָיו יָתוּר וְיִדְרֹשׁ דֶּרֶךְ אַחֶרֶת. יֵשׁ לִפְתֹּר עֶרֶב וָבֹקֶר בְּגִימַטְרִיָּא: חֲמֵשׁ מֵאוֹת וְשִׁבְעִים וְאַרְבַּע, וְעוֹד אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת הֲרֵי אַלְפַּיִם וּשְׁמוֹנֶה מֵאוֹת וְשִׁבְעִים וְאַרְבַּע:",1,0],[8,14,"וְנִצְדַּק קֹדֶשׁ. יְכֻפַּר עֲוֹן יִשְׂרָאֵל, לְבַטֵּל גְּזֵרוֹת מִדְרְסָן וּמְרַפְּסָן מֵאָז גָּלוּ גָּלוּת רִאשׁוֹנָה לְמִצְרַיִם עַד יִגָּאֲלוּ וְיִוָּשְׁעוּ תְּשׁוּעַת עוֹלָמִים בְּמֶלֶךְ מְשִׁיחֵנוּ. וְחֶשְׁבּוֹן זֶה כָּלֶה לְסוֹף אֶלֶף וּמָאתַיִם וְתִשְׁעִים מִיּוֹם הוּסַר הַתָּמִיד, וְהוּא שֶׁנֶּאֱמַר בְּסוֹף הַסֵּפֶר ״וּמֵעֵת הוּסַר הַתָּמִיד לָתֵת שִׁקּוּץ שֹׁמֵם יָמִים אֶלֶף מָאתַיִם וְתִשְׁעִים״ (דניאל יב:יא) יִהְיֶה וְלֹא יוֹתֵר, שֶׁיָּבֹא הַמֶּלֶךְ מְשִׁיחֵנוּ וְיָסִיר שִׁקּוּץ הַשּׁוֹמֵם. וְהַתָּמִיד הוּסַר שֵׁשׁ שָׁנִים לִפְנֵי הַחֻרְבָּן בַּיִת שֵׁנִי וְהֶעֱמִיד צֶלֶם בַּהֵיכָל, וְיוֹם שִׁבְעָה עָשָׂר בְּתַמּוּז הָיָה שֶׁשָּׂרַף אַפּוֹסְטְמוֹס אֶת הַתּוֹרָה וּבִטֵּל אֶת הַתָּמִיד וְהֶעֱמִיד צֶלֶם בַּהֵיכָל, כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת תַּעֲנִית (תענית כו:). וְשֵׁשׁ שָׁנִים שֶׁכָּתַבְתִּי אֵין בְּיָדִי רְאָיָה מְפֹרֶשֶׁת, אַךְ יֵשׁ רְאָיָה שֶׁשָּׁבוּעַ שָׁלֵם לֹא בָּטַל הַתָּמִיד לִפְנֵי הַחֻרְבָּן, שֶׁכֵּן נִבָּא דָּנִיֵּאל עַל טִיטוּס ״וַחֲצִי הַשָּׁבוּעַ יַשְׁבִּית זֶבַח וּמִנְחָה״ (דניאל ט:כז), כְּלוֹמַר: מִקְצָת הַשָּׁבוּעַ שֶׁלִּפְנֵי הַחֻרְבָּן יְבַטְּלוּ הַקָּרְבָּנוֹת; כָּךְ מְפֹרָשׁ לְמַטָּה בָּעִנְיָן (שם). נַחֲזֹר עַל הָרִאשׁוֹנוֹת, כֵּיצַד מְכֻוָּן חֶשְׁבּוֹן עֶרֶב בֹּקֶר אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת מִיּוֹם רֶדֶת יִשְׂרָאֵל לְמִצְרַיִם לִהְיוֹת כָּלֶה לְסוֹף אֶלֶף וּמָאתַיִם וַחֲמִשִּׁים לְיוֹם שֶׁהוּסַר הַתָּמִיד: מָאתַיִם וְעֶשֶׂר הָיוּ בְמִצְרַיִם, אַרְבַּע מֵאוֹת וּשְׁמוֹנִים מִיּוֹם צֵאתָם עַד ״וַיִּבֶן הַבַּיִת״ (מלכים א ו:א); אַרְבַּע מֵאוֹת וְעֶשֶׂר הָיָה הַבַּיִת, וְשִׁבְעִים שָׁנָה גָּלוּת בָּבֶל, וְאַרְבַּע מֵאוֹת וְעֶשְׂרִים בַּיִת שֵׁנִי, תֵּן עֲלֵיהֶם אֶלֶף וּמָאתַיִם וְתִשְׁעִים שֶׁל קֵץ הַיָּמִים, הֲרֵי אַלְפַּיִם וּשְׁמוֹנֶה מֵאוֹת. צֵא מֵהֶן שֵׁשׁ שָׁנִים שֶׁהוּסַר הַתָּמִיד לִפְנֵי הַחֻרְבָּן, שֶׁלֹּא מָנָה הַכָּתוּב אֶלֶף וּמָאתַיִם וְתִשְׁעִים אֶלָּא לְמֵעֵת הוּסַר הַתָּמִיד, הֲרֵי לְךָ חֶשְׁבּוֹן עֶרֶב וָבֹקֶר וְאַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת. עוֹד נוֹסָף בַּחֶשְׁבּוֹן ״אַשְׁרֵי הַמְחַכֶּה וְיַגִּיעַ לְיָמִים״ (דניאל יב:יב) אַרְבָּעִים וְחָמֵשׁ שָׁנָה יְתֵרִים עַל אֶלֶף וּמָאתַיִם וְתִשְׁעִים יֵשׁ לוֹמַר עַל חֶשְׁבּוֹן הָרִאשׁוֹן, יֵצֵא הַמֶּלֶךְ הַמָּשִׁיחַ וְיַחֲזֹר וְיִתְכַּסֶּה מֵהֶם אוֹתָם אַרְבָּעִים וְחָמֵשׁ שָׁנִים. וְרַבִּי אֶלְעָזָר הַקַּלִּיר יִסֵּד בִּיסוֹד שִׁירוֹ (בְּסִלּוּק יוֹצֵר שֶׁל פָּרָשַׁת הַחֹדֶשׁ): שְׁבוּעִים שִׁשָּׁה הֲרֵי אַרְבָּעִים וּשְׁתַּיִם; וְיֵשׁ לוֹמַר: הַשָּׁלֹשׁ שָׁנִים שֶׁלֹּא בָּאוּ לְחֶשְׁבּוֹן שָׁבוּעַ לֹא מָנָה. וַאֲנִי מָצָאתִי כָּךְ בְּמִדְרַשׁ רוּת, שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לְהִתְכַּסּוֹת אַרְבָּעִים וְחָמֵשׁ שָׁנִים לְאַחַר שֶׁיִּגָּלֶה, וּמֵבִיא רְאָיָה מִן הַמִּקְרָאוֹת הַלָּלוּ:",2,0],[8,15,"וָאֲבַקְשָׁה בִינָה. הָיִיתִי מִתְאַוֶּה שֶׁיָּבִינוּ לִי מִן הַשָּׁמָיִם:",1,0],[8,16,"בֵּין אוּלָי. בְּתוֹךְ הַנָּהָר:",1,0],[8,16,"וַיִּקְרָא. הָאָדָם:",2,0],[8,16,"וַיֹּאמַר. לַמַּלְאָךְ אַתָּה גַבְרִיאֵל:",3,0],[8,16,"הָבֵן לְהַלָּז אֶת הַמַּרְאֶה. פָּרֵשׁ לָזֶה אֶת הֶחָזוֹן׃",4,0],[8,16,"לְהַלָּז. לְשׁוֹן חֲשִׁיבוּת, כְּמוֹ שֶׁקְּרָאוֹ חֲמוּדוֹת (דניאל ט:כג). כָּל מָקוֹם שֶׁנֶּאֱמַר ׳הַלָּז׳ בַּעַל צוּרָה הוּא, וּמִכָּאן לָמְדוּ בָּאַגָּדָה: יִצְחָק נִדְמָה לְאָבִיו בְּצֶלֶם וּבִדְמוּת, שֶׁנִּקְרָא ״הָאִישׁ הַלָּז״ בְּפָרָשַׁת ׳וַיְהִי כִּי זָקֵן יִצְחָק׳ (בראשית כז:א). ״וַיְהִי יוֹסֵף יְפֵה תֹאַר״ (בראשית לט:ו) זֶהוּ הַנּוֹי, הַמָּנוּי בַּחֲמִשָּׁה דְבָרִים שֶׁהָאָב זוֹכֶה לִבְנוֹ (עדויות ב:ט):",5,0],[8,17,"לְעֶת קֵץ. לְיָמִים רַבִּים יִהְיֶה הַחָזוֹן הַזֶּה:",1,0],[8,18,"נִרְדַּמְתִּי. לְשׁוֹן תְּנוּמָה וְשִׁמָּמוֹן:",1,0],[8,18,"עַל עָמְדִי. עַל מַעֲמַד רַגְלִי:",2,0],[8,19,"כִּי לְמוֹעֵד קֵץ. כִּי הוּא לִזְמַן קֵץ יָמִים רַבִּים:",1,0],[8,20,"מַלְכֵי מָדַי וּפָרָס. שְׁתֵּי קְרָנַיִם שְׁתֵּי אֻמּוֹת מוֹלְכוֹת, כְּמוֹ שֶׁפֵּרַשְׁתִּי לְמַעְלָה (דניאל ח:ג):",1,0],[8,21,"הַמֶּלֶךְ הָרִאשׁוֹן. הוּא אֲלֶכְּסַנְדְּרוֹס מוּקְדוֹן שֶׁהָרַג אֶת דָּרְיָוֶשׁ בֶּן אֶסְתֵּר, כְּמוֹ שֶׁמָּצִינוּ בְּסֵפֶר יוֹסִיפוֹן:",1,0],[8,22,"וְהַנִּשְׁבֶּרֶת. שֶׁרָאִיתָ שֶׁנִּשְׁבְּרָה:",1,0],[8,22,"וַתַּעֲמֹדְנָה אַרְבַּע תַּחְתֶּיהָ. כְּמוֹ שֶׁכָּתוּב בְּסִפּוּר הַחֲלוֹם לְמַעְלָה: אַרְבַּע מַלְכֻיּוֹת, אֲשֶׁר יַעֲמֹדְנָה מֵאוֹתוֹ גּוֹי שֶׁחָלַק אֲלֶכְּסַנְדְּרוֹס מוּקְדָּן מַלְכוּתוֹ בְּמוֹתוֹ לְאַרְבַּע יְלָדִים. וְיוֹסֵף קְרָאָם בְּסִפְרוֹ אַרְבַּע רָאשֵׁי נָמֵר, וְלֹא בְּנֵי הַמֶּלֶךְ הָיוּ:",2,0],[8,22,"וְלֹא בְכֹחוֹ. וְלֹא יִהְיוּ הָאַחֲרוֹנִים כְּכֹחַ הַמֶּלֶךְ הָרִאשׁוֹן, כִּי חֲלָשִׁים מִמֶּנּוּ יִהְיוּ:",3,0],[8,23,"וּבְאַחֲרִית מַלְכוּתָם כְּהָתֵם הַפּוֹשְׁעִים. כְּשֶׁיַּגִּיעַ זְמַן שֶׁיִּתַּמּוּ רִשְׁעֵי יִשְׂרָאֵל שֶׁבְּבַיִת שֵׁנִי:",1,0],[8,23,"יַעֲמֹד מֶלֶךְ עַז פָּנִים. הוּא טִיטוּס:",2,0],[8,24,"וְעָצַם כֹּחוֹ. וְלֹא בִּגְבוּרָה כִּי אִם בַּחֲלַקְלַקּוֹת, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסוֹף הַסֵּפֶר (דניאל יא:כא):",1,0],[8,24,"וְנִפְלָאוֹת יַשְׁחִית. וּבְהַפְלֵא וָפֶלֶא יַשְׁחִית עוֹבְדֵי כוֹכָבִים:",2,0],[8,24,"וְהִצְלִיחַ וְעָשָׂה. חֶפְצוֹ:",3,0],[8,24,"וְהִשְׁחִית עֲצוּמִים. הִשְׁחִית אֻמּוֹת רַבּוֹת:",4,0],[8,24,"וְעַם קְדוֹשִׁים. יִשְׂרָאֵל הַמַּאֲמִינִים בַּתּוֹרָה:",5,0],[8,25,"וְעַל שִׂכְלוֹ וְהִצְלִיחַ מִרְמָה בְּיָדוֹ. וְעַל יְדֵי שֶׁהוּא מַשְׂכִּיל בְּכָל אֲשֶׁר יִפְנֶה וְיַצְלִיחַ, יַחֲזִיק בַּמִּרְמָה שֶׁבְּיָדוֹ:",1,0],[8,25,"וּבִלְבָבוֹ יַגְדִּיל. יִתְגָּאֶה:",2,0],[8,25,"וּבְשַׁלְוָה יַשְׁחִית רַבִּים. בְּמִרְמָה וּבַחֲלַקְלַקּוֹת יַשְׁחִית רַבִּים הַיּוֹשְׁבִים אִתּוֹ בִּבְרִית וְשָׁלוֹם:",3,0],[8,25,"וְעַל שַׂר שָׂרִים יַעֲמֹד. כְּלַפֵּי מַעְלָה יַטִּיחַ דְּבָרִים. זֶהוּ פֵּרוּשׁ הַחֲלוֹם הַכָּתוּב לְמַעְלָה (״וְעַד שַׂר הַצָּבָא הִגְדִּיל״):",4,0],[8,25,"וּבְאֶפֶס יָד יִשָּׁבֵר. וּבְאֵין כֹּחַ יִשָּׁבֵר עַל יְדֵי יַתּוּשׁ חַלָּשׁ שֶׁבַּבְּרִיּוֹת שֶׁנִּכְנַס בְּחוֹטְמוֹ, כְּמוֹ שֶׁשָּׁנִינוּ בְּמַסֶּכֶת גִּטִּין (גיטין נו:):",5,0],[8,26,"וּמַרְאֵה הָעֶרֶב וְהַבֹּקֶר. אֲשֶׁר נֶאֱמַר לְךָ בַּחֲלוֹם הָעֶלְיוֹן אֱמֶת הוּא:",1,0],[8,26,"וְאַתָּה סְתֹם הֶחָזוֹן. אַל תְּפָרְשֵׁהוּ וְסָתְמֵהוּ בְּלִבְּךָ, כִּי לְיָמִים רַבִּים יָבֹא:",2,0],[8,27,"נִהְיֵיתִי. לְשׁוֹן הֹוֶה וְשֶׁבֶר, כְּלוֹמַר: נִצְטַעַרְתִּי עַל הַפּוּרְעָנוּת הַזֶּה וְנִדְכֵּיתִי:",1,0],[8,27,"אֶת מְלֶאכֶת הַמֶּלֶךְ. שֶׁהָיִיתִי מְמֻנֶּה עַל פְּקֻדַּת עֲבוֹדַת מֶמְשֶׁלֶת מַלְכוּת בֵּלְשַׁצַּר, שֶׁמִּנָּהוּ נְבוּכַדְנֶצַּר אָבִיו, כְּמוֹ שֶׁנֶּאֱמַר בִּתְחִלַּת הַסֵּפֶר ״וְהַשְׁלְטֵיהּ עַל כָּל מְדִינַת בָּבֶל״ (דניאל ב:מח):",2,0],[8,27,"וָאֶשְׁתּוֹמֵם עַל הַמַּרְאֶה. וָאֶתְבַּהֵל עַל הֶחָזוֹן:",3,0],[8,27,"וְאֵין מֵבִין. שֶׁאֲנִי מִשְׁתּוֹמֵם, כִּי הָיִיתִי לִפְנֵי הַשָּׂרִים מִתְחַזֵּק:",4,0],[9,1,"בִּשְׁנַת אַחַת לְדָרְיָוֶשׁ בֶּן אֲחַשְׁוֵרוֹשׁ. לֹא זֶהוּ אֲחַשְׁוֵרוֹשׁ שֶׁבִּימֵי הָמָן (אסתר ג:א), כִּי הוּא מֶלֶךְ פָּרַס הָיָה, וְזֶה דָּרְיָוֶשׁ הַמָּדִי אֲשֶׁר הוּמְלַךְ עַל מַלְכוּת כַּשְׂדִּים כְּשֶׁנֶּהֱרַג בֵּלְשַׁצַּר, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה ״וְדָרְיָוֶשׁ מָדָאָה קַבֵּל מַלְכוּתָא״ (דניאל ו:א):",1,0],[9,2,"בִּינוֹתִי בַסְּפָרִים. נִסְתַּכַּלְתִּי בַחֶשְׁבּוֹנוֹת:",1,0],[9,2,"מִסְפַּר הַשָּׁנִים וְגוֹ׳. הָיִיתִי מְחַשֵּׁב חֶשְׁבּוֹן הַשָּׁנִים שֶׁהָיִיתִי סָבוּר עַל מַה שֶׁנִּבָּא ״כִּי לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקֹד אֶתְכֶם״ (ירמיה כט:י), דִּמִּיתִי שֶׁהַפְּקִידָה הַזֹּאת הִיא בִּנְיַן הַבַּיִת, וְשִׁבְעִים שָׁנָה כָּלִים בִּשְׁנַת אַחַת לְדָרְיָוֶשׁ הַמָּדִי מִשֶּׁפָּשְׁטָה מַלְכוּת בָּבֶל יָד עַל יִשְׂרָאֵל, שֶׁכָּבַשׁ נְבוּכַדְנֶצַּר יְהוֹיָקִים לִהְיוֹת לוֹ עֶבֶד, וְהִיא הָיְתָה שָׁנָה שְׁנִיָּה לְמַלְכוּת נְבוּכַדְנֶצַּר; דְּאָמַר מַר: שָׁנָה רִאשׁוֹנָה כָּבַשׁ נִינְוֵה, שָׁנָה שְׁנִיָּה עָלָה וְכָבַשׁ יְהוֹיָקִים. צֵא וַחֲשׁוֹב מֵאוֹתָהּ שָׁנָה וְעַד כָּאן וְתִמְצָאֵם. וְאַף בְּמִשְׁנַת סֵדֶר עוֹלָם נִמְצָא הַחֶשְׁבּוֹן הַזֶּה, וְשָׁנִינוּ שָׁם: בִּשְׁנַת מוֹת בֵּלְשַׁאצַּר הֲרֵי שִׁבְעִים שָׁנָה מִיּוֹם שֶׁמָּלַךְ נְבוּכַדְנֶצַּר: שִׁבְעִים חָסֵר אַחַת מִיּוֹם שֶׁכָּבַשׁ יְהוֹיָקִים וְעוֹד שָׁנָה אַחַת לְבָבֶל, עָמַד דָּרְיָוֶשׁ וְהִשְׁלִימָהּ. וּבִרְאוֹתִי כִּי עֲדַיִן אֵין הַגְּאֻלָּה מְמַהֶרֶת לָבֹא, הֲבִינוֹתִי וְנָתַתִּי לֵב לִסְפִירַת הַחֶשְׁבּוֹן, וְיָדַעְתִּי שֶׁלֹּא הָיָה לִי לִמְנוֹת לְפִי כִּבּוּשׁ יְהוֹיָקִים, אֶלָּא לְמַלֹּאות לְחָרְבוֹת יְרוּשָׁלִַם כְּשֶׁיִּמְלְאוּ שִׁבְעִים שָׁנָה לְגָלוּת צִדְקִיָּהוּ שֶׁבּוֹ חָרְבָה יְרוּשָׁלַיִם; וְעוֹד יֵשׁ שְׁמֹנֶה עֶשְׂרֵה לָבֹא, שֶׁהַגָּלוּת הַזֹּאת הָיְתָה בִּשְׁמֹנֶה עֶשְׂרֵה שָׁנָה לְכִבּוּשׁ יְהוֹיָקִים, כְּמוֹ שֶׁשָּׁנִינוּ בְּסֵדֶר עוֹלָם: גָּלוּ בְּשֶׁבַע, גָּלוּ בִּשְׁמֹנֶה, גָּלוּ בִּשְׁמֹנֶה עֶשְׂרֵה גָּלוּ בְּתִשְׁעָה עֶשְׂרֵה; וּפֵרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּמַסֶּכֶת מְגִלָּה (מגילה יא:): גָּלוּ גָּלוּת יְכָנְיָה בְּשֶׁבַע לְכִבּוּשׁ יְהוֹיָקִים, שֶׁהוּא שְׁמֹנֶה לִנְבוּכַדְנֶצַּר; גָּלוּ בַּשְּׁנִיָּה בִּשְׁמֹנֶה עֶשְׂרֵה לְכִבּוּשׁ יְהוֹיָקִים, שֶׁהִיא תְּשַׁע עֶשְׂרֵה לִנְבוּכַדְנֶצַּר:",2,0],[9,4,"וָאֶתְוַדֶּה. עַל חַטַּאת עַמִּי:",1,0],[9,4,"הָאֵל הַגָּדוֹל וְהַנּוֹרָא. וְלֹא אָמַר גִּבּוֹר. אָמַר: עוֹבְדֵי כוֹכָבִים מִשְׁתַּעְבְּדִים בְּבָנָיו וְאַיֵּה גְּבוּרוֹתָיו?",2,0],[9,5,"וְסוֹר. וְהָלַכְנוּ הָלוֹךְ וָסוֹר מִמִּצְוֹתֶיךָ, טִילְנ״שׁ בְּלַעַ״ז:",1,0],[9,7,"לְךָ אֲדֹנָי הַצְּדָקָה. כְּלוֹמַר: מִשְׁפָּטֶיךָ וּפוּרְעָנוּת שֶׁהֵבֵאתָ עָלֵינוּ, הַדִּין וְהַצֶּדֶק עִמְּךָ:",1,0],[9,7,"וְלָנוּ בֹּשֶׁת הַפָּנִים. כְּדַאי אָנוּ לְהִתְבַּיֵּשׁ עַל הַמְּאוֹרָע לָנוּ, כִּי אֲנַחְנוּ גָּרַמְנוּ לְעַצְמֵנוּ:",2,0],[9,7,"כַּיּוֹם הַזֶּה. כַּאֲשֶׁר אֲנַחְנוּ רוֹאִים הַיּוֹם׃",3,0],[9,9,"לַאדֹנָי אֱלֹהֵינוּ הָרַחֲמִים. שֶׁלֹּא כָלִינוּ בַּעֲוֹנוֹתֵינוּ כִּי מָרַדְנוּ בוֹ:",1,0],[9,11,"וַתִּתַּךְ עָלֵינוּ. וַתַּגִּיעַ עָלֵינוּ, כְּמוֹ ״לֹא נִתַּךְ אָרְצָה״ (שמות ט:לג). וְתִרְגֵּם אוּנְקְלוֹס: ״לָא מְטָאת לְאַרְעָא״:",1,0],[9,11,"הָאָלָה וְהַשְּׁבוּעָה. אָלוֹת הַבְּרִית אֲשֶׁר הִשְׁבַּעְתָּנוּ בְּחוֹרֵב ״וְהָיָה אִם לֹא תִשְׁמְעוּ וְגוֹמֵר״ (ויקרא כו:יד), כָּל הַקְּלָלוֹת הַכְּתוּבוֹת שָׁם:",2,0],[9,12,"כַּאֲשֶׁר נֶעֶשְׂתָה בִּירוּשָׁלִָם. חֶרֶב, הֶרֶג, וּשְׂרֵפַת הָעִיר, וְנָשִׁים עֻנּוּ, וְשָׁבוּ בְּקוֹלָרִין:",1,0],[9,13,"כַּאֲשֶׁר כָּתוּב בְּתוֹרַת מֹשֶׁה. רֶמֶז שֶׁהֵעִיד בָּנוּ שֶׁאִם נַעֲבֹר עַל הַשְּׁבוּעָה תָּבֹא עָלֵינוּ כָּל הָרָעָה הַזֹּאת:",1,0],[9,14,"וַיִּשְׁקֹד. וַיְמַהֵר:",1,0],[9,14,"כִּי צַדִּיק. כִּי הַדִּין עִמּוֹ. וְרַבּוֹתֵינוּ פֵּרְשׁוּ: צַדִּיק הַקָּדוֹשׁ בָּרוּךְ הוּא, וּצְדָקָה הִיא עָלֵינוּ, שֶׁמִּהֵר וְהִקְדִּים שְׁתֵּי שָׁנִים לְמִנְיַן ״וְנוֹשַׁנְתֶּם״ (דברים ד:כה), כְּדֵי שֶׁלֹּא תִתְקַיֵּם בָּנוּ ״כִּי אָבֹד תֹּאבֵדוּן״ (דברים ד:כו). ״וְנוֹשַׁנְתֶּם״ בְּגִימַטְרִיָּא: שְׁמוֹנֶה מֵאוֹת וַחֲמִשִּׁים וּשְׁתַּיִם, וְהֵם גָּלוּ לְסוֹף שְׁמוֹנֶה מֵאוֹת וַחֲמִשִּׁים לְבִיאָתָם לָאָרֶץ:",2,0],[9,15,"וְעַתָּה אֲדֹנָי אֱלֹהֵינוּ. מִתְוַדִּים אֲנַחְנוּ כִּי חָטָאנוּ וְרָשַׁעְנוּ:",1,0],[9,16,"לְחֶרְפָּה. לְגִדּוּף:",1,0],[9,16,"לְכָל סְבִיבוֹתֵינוּ. לְכָל שְׁכֵנֵינוּ, כֻּלָּם מְחָרְפִים אוֹתָנוּ:",2,0],[9,17,"לְמַעַן ה׳. לְמַעַן שֵׁם הַקָּדוֹשׁ הַנִּקְרָא עַל בֵּית הַמִּקְדָּשׁ, שֶׁנֶּאֱמַר: ״מִקְדָּשׁ ה׳ כּוֹנְנוּ יָדֶיךָ״ (שמות טו:יז):",1,0],[9,18,"וּרְאֵה שֹׁמְמוֹתֵינוּ. וְשִׁמְמוֹת הָעִיר אֲשֶׁר נִקְרָא שִׁמְךָ עָלֶיהָ, כִּי לֹא עַל מִשְׁעֶנֶת צִדְקוֹתֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵינוּ לְהֵיטִיב לָנוּ, כִּי עַל רַחֲמֶיךָ בָּאנוּ:",1,0],[9,19,"אֲדֹנָי שְׁמָעָה. אֶל תַּחֲנוּנֵינוּ:",1,0],[9,19,"אֲדֹנָי סְלָחָה. לַחֲטָאתֵינוּ׃",2,0],[9,19,"אֲדֹנָי הַקְשִׁיבָה. אָזְנְךָ לְצַעֲקָתֵינוּ׃",3,0],[9,19,"וַעֲשֵׂה. אֶת בַּקָּשָׁתֵינוּ וְאַל תְּאַחַר׃",4,0],[9,20,"עַל הַר קֹדֶשׁ אֱלֹהַי. בְּעַד הַר בֵּית אֱלֹהִים שֶׁיִּבָּנֶה:",1,0],[9,21,"בַּתְּחִלָּה. בִּימֵי בֵּלְשַׁצַּר, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה:",1,0],[9,21,"מוּעָף בִּיעָף. הָיָה מוּעָף אֵלַי בִּפְרִיחָה וּבְטִיסָה:",2,0],[9,22,"וַיָּבֶן. וַיְבִינֵנִי:",1,0],[9,23,"בִּתְחִלַּת תַּחֲנוּנֶיךָ יָצָא דָבָר. אֱמֶת מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא אֵלַי לְהַגִּיד לְךָ:",1,0],[9,23,"כִּי חֲמוּדוֹת אָתָּה. דִּבְרֵי חֶמֶד יֵשׁ לְךָ לְהַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[9,23,"וּבִין בַּדָּבָר. וְתֵן לֵב לְהָבִין בַּדָּבָר:",3,0],[9,24,"שָׁבֻעִים שִׁבְעִים נֶחְתַּךְ. עַל יְרוּשָׁלַיִם מִיּוֹם חֻרְבַּן רִאשׁוֹן בִּימֵי צִדְקִיָּהוּ עַד שֶׁיִּהְיֶה בַּשְּׁנִיָּה:",1,0],[9,24,"לְכַלֵּא הַפֶּשַׁע וּלְהָתֵם חַטָּאת. שֶׁיְּקַבְּלוּ יִשְׂרָאֵל אֶת גְּמַר פּוּרְעָנוּתָם בְּגָלוּת טִיטוּס וְשִׁעְבּוּד, וּכְדֵי שֶׁיִּכְלוּ פִּשְׁעֵיהֶם וְיִתַּמּוּ חַטָּאתָם וְיִתְכַּפֵּר עֲוֹנוֹתָם, כְּדֵי לְהָבִיא עֲלֵיהֶם צֶדֶק עוֹלָמִים וְלִמְשׁוֹחַ (עֲלֵיהֶם) קֹדֶשׁ קָדָשִׁים. הָאָרוֹן וְהַמִּזְבְּחוֹת וּכְלֵי הַקֹּדֶשׁ שֶׁיָּבוֹאוּ לָהֶם עַל יְדֵי מֶלֶךְ הַמָּשִׁיחַ. וּמִנְיַן שָׁבוּעִים אַרְבַּע מֵאוֹת וְתִשְׁעִים שָׁנָה, גָּלוּת בָּבֶל שִׁבְעִים, וּבַיִת שֵׁנִי אַרְבַּע מֵאוֹת וְעֶשְׂרִים:",2,0],[9,25,"וְתֵדַע וְתַשְׂכֵּל מִן מוֹצָא דָבָר. מִתּוֹךְ מוֹצָא דָבָר זֶה שֶׁיָּצָא בִּתְחִלַּת תַּחֲנוּנֶיךָ לְהַגִּיד לְךָ תֵּדַע לְהַשְׂכִּיל לְהָשִׁיב וְלִבְנוֹת יְרוּשָׁלִַם:",1,0],[9,25,"עַד מָשִׁיחַ נָגִיד. זְמַן תִּנָּתֵן מִיּוֹם הַחֻרְבָּן עַד בֹּא כֹּרֶשׁ מֶלֶךְ פָּרַס, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו שֶׁהוּא יָשׁוּב וְיִבְנֶה עִירוֹ, וּקְרָאוֹ מְשִׁיחוֹ וּנְגִידוֹ, שֶׁנֶּאֱמַר: ״כֹּה אָמַר ה׳ לִמְשִׁיחוֹ לְכוֹרֶשׁ וְגוֹ׳ הוּא יִבְנֶה עִירִי וְגָלוּתִי יְשַׁלֵּחַ וְגוֹ׳״ (ישעיה מה:א,יג):",2,0],[9,25,"שָׁבֻעִים שִׁבְעָה. שֶׁבַע שְׁמִטּוֹת שְׁלֵמוֹת יִהְיוּ בַגּוֹלָה קֹדֶם שֶׁיָּבֹא כּוֹרֶשׁ, וְעוֹד הָיוּ יוֹתֵר שָׁלֹשׁ שָׁנִים, אֶלָּא מִתּוֹךְ שֶׁלֹּא שָׁלְמָה הַשָּׁבוּעַ לֹא נִמְנָה. בִּשְׁנַת אַחַת לְדָרְיָוֶשׁ הַמָּדִי שֶׁהָיָה דָנִיֵּאל עוֹמֵד בָּהּ כְּשֶׁנֶּאֱמַר לוֹ הֶחָזוֹן הַזֶּה, כָּלוּ שִׁבְעִים לִכְבּוֹשׁ יְהוֹיָקִים. צֵא מֵהֶן שְׁמוֹנֶה עֶשְׂרֵה שָׁנָה שֶׁקָּדְמָה כְבוּשׁ יְהוֹיָקִים לְחֻרְבַּן יְרוּשָׁלַיִם, נִשְׁאֲרוּ חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה. הִיא שֶׁשָּׁנוּ רַבּוֹתֵינוּ: חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה לֹא עָבַר אִישׁ בִּיהוּדָה (יומא נד.), הֵם חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה אֲשֶׁר מִיּוֹם הַחֻרְבָּן עַד שֶׁחָזְרוּ בִּימֵי כּוֹרֶשׁ. הֲרֵי שֶׁבַע שְׁמִטּוֹת וְשָׁלֹשׁ שָׁנִים:",3,0],[9,25,"וְשָׁבֻעִים שִׁשִּׁים וּשְׁנַיִם תָּשׁוּב וְנִבְנְתָה. הָעִיר בִּרְחוֹבוֹתֶיהָ וּבַחֲרִיצוֹתֶיהָ:",4,0],[9,25,"וְחָרוּץ. הֵם חֲרִיצִים שֶׁעוֹשִׂין סְבִיב הַחוֹמָה לְחִזּוּק הָעִיר, שֶׁקּוֹרִין קאבה בְּלַעַ״ז:",5,0],[9,25,"וּבְצוֹק הָעִתִּים. וְאוֹתָן הָעִתִּים יִהְיוּ בְצוֹק וּבְצָרָה, כִּי בְּשִׁעְבּוּד מַלְכֵי פָרַס וְעוֹבְדֵי כוֹכָבִים יִהְיוּ מַטְרִיחִים עֲלֵיהֶם בְּשִׁעְבּוּד קָשֶׁה, וְאַף עַל פִּי שֶׁהֵם שִׁשִּׁים וּשְׁתַּיִם שָׁבֻעִים וְעוֹד אַרְבַּע שָׁנִים שֶׁנּוֹתְרוּ מִן הַשָּׁבוּעַ הַשְּׁמִינִי, שֶׁהָיְתָה תְּחִלָּתוֹ נִבְלַעַת שָׁלֹשׁ שָׁנִים בְּתוֹךְ חֲמִשִּׁים וּשְׁתַּיִם שֶׁל הֶמְשֵׁךְ הַגּוֹלָה, לֹא נִמְנוּ כָאן אוֹתָן אַרְבַּע שָׁנִים, לְפִי שֶׁלֹּא מָנָה כָאן אֶלָּא שָׁבֻעִים. וַהֲרֵי אַתָּה מוֹצֵא שֶׁמִּתְּחִלָּה הִתְחִיל לִמְנוֹת שָׁבֻעִים שִׁבְעִים, וּבַסּוֹף כְּשֶׁפֵּרַשׁ עִתֵּיהֶם וּמִשְׁפָּטֵיהֶם, לֹא מָנָה אֶלָּא שִׁשִּׁים וָתֵשַׁע, אֶלָּא שָׁבוּעַ אֶחָד נֶחְלַק מִקְצָתוֹ לְכָאן וּמִקְצָתוֹ לְכָאן, וְהוּא לֹא הִזְכִּיר אֶלָּא הַשָּׁבוּעִים הַשְּׁלֵמִים:",6,0],[9,25,"וּבְצוֹק הָעִתִּים. בְּצוּקָה יִהְיוּ אוֹתָן הָעִתִּים:",7,0],[9,26,"וְאַחֲרֵי. אוֹתָן שָׁבוּעִים:",1,0],[9,26,"יִכָּרֵת מָשִׁיחַ. יֵהָרֵג אַגְרִיפַּס מֶלֶךְ יְהוּדָה שֶׁהָיָה מוֹשֵׁל בִּימֵי הַחֻרְבָּן:",2,0],[9,26,"וְאֵין לוֹ. כְּמוֹ וְאֵינֶנּוּ:",3,0],[9,26,"מָשִׁיחַ. אֵינוֹ אֶלָּא לְשׁוֹן שַׂר וְגָדוֹל:",4,0],[9,26,"וְהָעִיר וְהַקֹּדֶשׁ. וְהָעִיר וְהַמִּקְדָּשׁ:",5,0],[9,26,"יַשְׁחִית עַם נָגִיד הַבָּא. עֲלֵיהֶם הוּא טִיטוּס וְאוּכְלוּסָיו:",6,0],[9,26,"וְקִצּוֹ בַשֶּׁטֶף. וְסוֹפוֹ לִקְלָלָה וַאֲבַדּוֹן שֶׁיִּשְׁטֹף כֹּחַ מַלְכוּתוֹ עַל יְדֵי מָשִׁיחַ:",7,0],[9,26,"וְעַד קֵץ מִלְחָמָה. גּוֹג תְּהֵא הָעִיר:",8,0],[9,26,"נֶחֱרֶצֶת שֹׁמֵמוֹת. חָרַץ שֶׁל שׁוֹמֵמוֹת:",9,0],[9,27,"וְהִגְבִּיר בְּרִית לָרַבִּים שָׁבוּעַ אֶחָד. לָרַבִּים לַשָּׂרִים, כְּמוֹ ״וְכָל רַבֵּי הַמֶּלֶךְ״ בְּסֵפֶר יִרְמְיָה (ירמיהו לט:יג):",1,0],[9,27,"וְהִגְבִּיר. טִיטוּס בְּרִית לְשָׂרֵי יִשְׂרָאֵל:",2,0],[9,27,"שָׁבוּעַ אֶחָד. יַבְטִיחֵם בְּהַגְבָּרַת בְּרִית וְשַׁלְוָה עַד שֶׁבַע שָׁנִים, וּבְתוֹךְ הַשָּׁבוּעַ יָפֵר אֶת בְּרִיתוֹ:",3,0],[9,27,"יַשְׁבִּית זֶבַח וּמִנְחָה. וְזֶהוּ שֶׁאָמַר בַּחֲזָיוֹן הָרִאשׁוֹן ״וּבְשַׁלְוָה יַשְׁחִית רַבִּים״ (דניאל ח:כה), מִתּוֹךְ בְּרִית שַׁלְוָה יַשְׁחִיתֵם:",4,0],[9,27,"וְעַל כְּנַף שִׁקּוּצִים מְשֹׁמֵם. כִּנּוּי שֶׁל גְּנַאי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת הוּא, כְּלוֹמַר: וְעַל מוֹשַׁב גֹּבַהּ בֵּין שִׁקּוּצִים וְתִעוּב יַנִּיחַ אֶת הַשּׁוֹמֵם, אֶת הָעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהִיא נֶאֱלֶמֶת כְּאֶבֶן דּוֹמֵם:",5,0],[9,27,"כְּנַף. לְשׁוֹן גּוֹבַהּ, כִּכְנַף עוֹף הַפּוֹרֵחַ:",6,0],[9,27,"וְעַד כָּלָה וְנֶחֱרָצָה תִּתַּךְ עַל שׁוֹמֵם. וְתִתְקַיֵּם מֶמְשֶׁלֶת הַשִּׁקּוּץ עַד יוֹם אֲשֶׁר תִּתַּךְ עָלֶיהָ כָּלָה וְנֶחֱרָצָה הַנִּגְזוֹר עָלֶיהָ בִּימֵי מֶלֶךְ הַמָּשִׁיחַ:",7,0],[9,27,"תִּתַּךְ עַל שׁוֹמֵם. תָּגִיחַ וְתֵרֵד כִּלָּיוֹן חָרוּץ (ישעיה י:כב) עַל הָעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְעַל עוֹבְדֶיהָ:",8,0],[10,1,"וְצָבָא גָדוֹל. וּלִזְמַן אָרוֹךְ יָבֹא:",1,0],[10,1,"וּבִין אֶת הַדָּבָר. וּלְהָבִין אֶת הַדָּבָר נִגְלָה לִי אֶת הֶחָזוֹן:",2,0],[10,1,"וּבִינָה לוֹ בַּמַּרְאֶה. וּלְהָבִינָהּ לוֹ בַּמַּרְאֶה. וְאֵין הַתֵּיבָה הַזֹּאת שֵׁם דָּבָר כְּמוֹ ״אִם יָדַעְתָּ בִינָה״ (אִיּוֹב לח:ד), אֶלָּא ה״א יְתֵרָה, וְהוּא כְּמוֹ ״בִּינָה הֲגִיגִי״ (תְּהִלִּים ה:ב), לְפִיכָךְ הַטַּעַם לְמַעְלָה בַּבֵּי״ת, וּפֵירוּשָׁהּ כְּמוֹ הָבֵן:",3,0],[10,2,"הָיִיתִי מִתְאַבֵּל. כְּשֶׁרָאָה שֶׁבִּטֵּל כּוֹרֶשׁ מְלֶאכֶת הַבַּיִת שֶׁצִּוָּה לְהַתְחִיל וְחָזַר בּוֹ עַל פִּי כְּתַב צָרֵי יְהוּדָה וּבִנְיָמִין רְחוּם בְּעֵל טְעֵם וְשִׁמְשַׁי סָפְרָא, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר עֶזְרָא (עזרא ד:ח):",1,0],[10,2,"שְׁלֹשָׁה שָׁבֻעִים יָמִים. עֶשְׂרִים וְאַחַת שָׁנָה הֵם, שְׁמוֹנֶה עֶשְׂרֵה שָׁנָה מִשְּׁנָה אַחַת לְדָרְיָוֶשׁ הַמָּדִי אֲשֶׁר שָׂם אֶל לִבּוֹ לַחְשֹׁב שִׁבְעִים שְׁנֵי הַגּוֹלָה כְּמוֹ שֶׁכָּתוּב, עַד שְׁנַת שְׁתַּיִם לְדָרְיָוֶשׁ הַפַּרְסִי (עזרא ד:כד) בֶּן אֶסְתֵּר שֶׁבָּנָה הַבַּיִת. וְשָׁלֹשׁ שָׁנִים הַיְתֵרִים לֹא יָדַעְתִּי אִם לִפְנֵיהֶם הִתְחִיל לְהִתְעַנּוֹת, אוֹ מֶשֶׁךְ קַבָּלַת נֶדֶר תַּעֲנִיּוֹתָיו שָׁלֹשׁ שָׁנִים לְאַחַר הַבִּנְיָן:",2,0],[10,3,"לֶחֶם חֲמֻדוֹת. פַּת נְקִיָּה, כְּמוֹ שֶׁתִּרְגֵּם אוּנְקְלוֹס אֶת ״בִּגְדֵי עֵשָׂו הַחֲמֻדוֹת״ (בראשית כז:טו): ״דַּכְיָתָא״:",1,0],[10,5,"לְבוּשׁ בַּדִּים. בֶּגֶד בּוּץ:",1,0],[10,5,"בְּכֶתֶם אוּפָז. בַּחֲגוֹרָה שֶׁל קְבוּצַת מַרְגָּלִיּוֹת. כָּל כֶּתֶם לְשׁוֹן קְבוּצַת זָהָב וְאֶבֶן יְקָרָה:",2,0],[10,6,"וּגְוִיָּתוֹ כְתַרְשִׁישׁ. פֵּרְשׁוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בִּשְׁחִיטַת חֻלִּין (צא.): גּוּפוֹ גָּדוֹל שְׁנֵי אֲלָפִים פַּרְסָה כְּמִדַּת יָם שֶׁשְּׁמוֹ תַרְשִׁישׁ וְהוּא יָמָּהּ שֶׁל אַפְרִיקָא:",1,0],[10,6,"קָלָל. צָרוּף וּמְזֻקָּק וּמַצְהִיב:",2,0],[10,6,"כְּקוֹל הָמוֹן. כְּקוֹל קְבוּצַת הָמוֹן רַב, שֶׁקּוֹלָם נִשְׁמָע לְמֵרָחוֹק:",3,0],[10,7,"וְהָאֲנָשִׁים אֲשֶׁר הָיוּ עִמִּי. אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה הֵם חַגַּי זְכַרְיָה וּמַלְאָכִי (מגילה ג.):",1,0],[10,7,"אֲבָל חֲרָדָה גְדוֹלָה נָפְלָה עֲלֵיהֶם. אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (ברכות ו.): אַף עַל פִּי שֶׁאָדָם אֵינוֹ רוֹאֶה דָּבָר שֶׁהוּא נִבְעָת מִמֶּנּוּ, מַזָּלוֹ שֶׁבָּרָקִיעַ רוֹאֵהוּ, וּלְכָךְ נִבְעָת:",2,0],[10,8,"נֶהְפַּךְ עָלַי לְמַשְׁחִית. לְהַשְׁחָתָה, וְדֶרֶךְ הַמִּקְרָאוֹת לְדַבֵּר כֵּן, כְּמוֹ (ירמיה ה:ח) ״סוּסִים מְזֻיָּנִים מַשְׁכִּים הָיוּ״, (מַשְׁכִּים) בְּהַשְׁכָּמַת הַבֹּקֶר:",1,0],[10,8,"וְלֹא עָצַרְתִּי כֹּחַ. כְּלוֹמַר: לֹא כָּנַסְתִּי כָּל כֹּחִי (כִּי כֹּחִי) הָלַךְ מִקִּרְבִּי:",2,0],[10,9,"נִרְדָּם. מֵרוֹב פַּחַד:",1,0],[10,10,"וַתְּנִיעֵנִי. כְּאָדָם הַמֵּנִיעַ אֶת הַיָּשֵׁן לַהֲקִיצוֹ:",1,0],[10,11,"אִישׁ חֲמֻדוֹת. אִישׁ טָהוֹר:",1,0],[10,11,"עַל עָמְדֶךָ. עַל מַעֲמַד רַגְלֶיךָ:",2,0],[10,11,"שָׁלַחְתִּי אֵלֶיךָ. נִשְׁתַּלַּחְתִּי אֵלֶיךָ מֵאֵת הַמָּקוֹם:",3,0],[10,11,"מַרְעִיד. מַרְתִּית׃",4,0],[10,12,"וַאֲנִי בָאתִי בִּדְבָרֶיךָ. בָּאתִי בִּשְׁלִיחוּת זוֹ בִּשְׁבִיל דְּבָרֶיךָ. וְרַבּוֹתֵינוּ דָּרְשׁוּ בְּמַסֶּכֶת יוֹמָא: וַאֲנִי בָאתִי לְתוֹךְ הַפַּרְגּוֹד עַל יָדְךָ, שֶׁהָיִיתִי מְגֹרָשׁ מִתּוֹכוֹ (יומא עז.):",1,0],[10,13,"עוֹמֵד לְנֶגְדִּי. נִלְחָם עִמָּדִי בָּרָקִיעַ, כְּשֶׁשּׁוֹאֵל אֹרֶךְ מְלוּכָה לְפָרַס לְשַׁעְבֵּד אֶתְכֶם. הֲרֵי עֶשְׂרִים וּשְׁתַּיִם יוֹם שֶׁהוּא עוֹמֵד לְנֶגְדִּי:",1,0],[10,13,"הַשָּׂרִים הָרִאשֹׁנִים. כְּלוֹמַר: הַחֲשׁוּבִים, רִאשׁוֹנָה בַּנִּכְנָסִים:",2,0],[10,13,"וַאֲנִי נוֹתַרְתִּי שָׁם. לְשַׁתֵּק אֶת שַׂר פָּרַס שֶׁבַּשָּׁמַיִם:",3,0],[10,14,"כִּי עוֹד חָזוֹן. לְהַגִּיד לְךָ מַה שֶּׁלֹּא הֻגַּד לְךָ, וְיָבֹא עוֹד לַיָּמִים הָרַבִּים הַנְּתוּנִים לַמּוֹעֵד:",1,0],[10,16,"נֶהֶפְכוּ צִירַי עָלַי. אֵלּוּ רָאשֵׁי עֲצָמוֹת כָּל אֵבֶר וְאֵבֶר הַתְּקוּעִים בְּחוֹרֵי מוֹשָׁבָם וְסוֹבֵב בְּתוֹכָם כְּדֶלֶת עַל צִירָהּ בְּחוֹר הַמִּפְתָּן. צִירַי נֶהֶפְכוּ לְהִשָּׁמֵט מִמְּקוֹמָם מֵרוֹב רֶתֶת וַחֲרָדָה:",1,0],[10,17,"עֶבֶד אֲדֹנִי זֶה. עַל עַצְמוֹ הוּא אוֹמֵר עֶבֶד וְעַל הַמַּלְאָךְ הוּא אוֹמֵר אֲדֹנִי, כְּלוֹמַר וְאֵיךְ יוּכַל עַבְדְּךָ זֶה לְדַבֵּר עִמָּךְ:",1,0],[10,20,"וְעַתָּה אָשׁוּב לְהִלָּחֵם עִם שַׂר פָּרָס. וְיָדַעְתִּי כִּי אוּכַל, אַךְ כְּבֹא עֵת מַלְכוּת אַנְטִיוֹכוּס יָדַעְתִּי שֶׁאֲנִי אֵצֵא וְהוּא יִכָּנֵס, לְאַחַר שְׁלוֹשִׁים וְאַרְבַּע שָׁנָה לְבִנְיַן הַבַּיִת, וְשֶׁיַּעֲמֹד אֲלֶכְּסַנְדְּרוֹס מוּקְדָּן. כִּי אַף עַל פִּי שֶׁהָיוּ יִשְׂרָאֵל מְשֻׁעְבָּדִים לְמַלְכֵי פָרַס בְּאוֹתָן הַיָּמִים, עֲבוֹדָה נוֹחָה עָבְדוּ בָהֶם וְלֹא הִכְבִּידוּ עֲלֵיהֶם, כִּי נְתָנָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְרַחֲמִים לָהֶם, אֲבָל מַלְכוּת יָוָן הֵטִילוּ עֲלֵיהֶם עֹל קָשֶׁה:",1,0],[10,21,"אֶת הָרָשׁוּם בִּכְתָב אֱמֶת. שְׁטַר הַגְּזֵרָה וֶאֱמֶת הִיא. וְאֵין אֶחָד בְּכָל הַשָּׂרִים הָעֶלְיוֹנִים מִתְחַזֵּק לְעָזְרֵנִי עַל כָּל אֵלֶּה כִּי אִם וְגוֹ׳:",1,0],[11,1,"וַאֲנִי בִּשְׁנַת אַחַת לְדָרְיָוֶשׁ הַמָּדִי. בִּנְפֹל מַלְכוּת בָּבֶל וְהִתְחִילָה מֶמְשֶׁלֶת מָדַי וּפָרַס, וְהָיוּ מְבַקְּשִׁים שָׂרֵי מָדַי וּפָרַס מֵאֵת הַמָּקוֹם לְהַכְבִּיד עֹל מֶמְשֶׁלֶת אֵימָתָם עֲלֵיכֶם, אֲנִי גַבְרִיאֵל עָמַדְתִּי לְמַחֲזִיק וּלְמָעוֹז לְמִיכָאֵל שַׂרְכֶם:",1,0],[11,2,"הִנֵּה עוֹד שְׁלֹשָׁה מְלָכִים וְגוֹ׳. רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ בְּסֵדֶר עוֹלָם (פרק כח): זֶה כּוֹרֶשׁ וַאֲחַשְׁוֵרוֹשׁ וְדָרְיָוֶשׁ שֶׁבָּנָה הַבַּיִת, וּמַה תַּלְמוּד לוֹמַר רְבִיעִי? רְבִיעִי לְמָדַי. אֲבָל בְּסֵפֶר יוֹסֵף בֶּן גּוּרְיוֹן כָּתוּב שֶׁהָיָה לוֹ בֵּן לְכוֹרֶשׁ שֶׁמָּלַךְ תַּחְתָּיו לִפְנֵי מְלוֹךְ אֲחַשְׁוֵרוֹשׁ וּשְׁמוֹ בַּמְבִּישָׁה:",1,0],[11,2,"וּכְחֶזְקָתוֹ. שֶׁל דָּרְיָוֶשׁ:",2,0],[11,2,"בְּעָשְׁרוֹ יָעִיר. אֶת כָּל מַלְכוּתוֹ לְהִלָּחֵם עִם מַלְכוּת יָוָן:",3,0],[11,3,"וְעָמַד מֶלֶךְ גִּבּוֹר. בְּיָוָן הוּא אֲלֶכְּסַנְדְּרוֹס מוּקְדוֹן:",1,0],[11,3,"וְעָשָׂה כִּרְצוֹנוֹ. בְּדָרְיָוֶשׁ מֶלֶךְ פָּרַס וְיַהַרְגֵהוּ וִיקַבֵּל מַלְכוּתוֹ, וְיִשְׁתַּעְבְּדוּ פַרְסִיִּים לַיְּוָנִים׃",2,0],[11,4,"וּכְעָמְדוֹ תִּשָּׁבֵר מַלְכוּתוֹ. וּכְשֶׁיִּתְחַזֵּק הַרְבֵּה וְיַעֲמֹד עַל חֶזְקָתוֹ, תִּשָּׁבֵר מַלְכוּתוֹ, שֶׁיָּמוּת:",1,0],[11,4,"וְתֵחָץ לְאַרְבַּע רוּחוֹת הַשָּׁמָיִם. כָּתוּב בְּסֵפֶר בֶּן גּוּרְיוֹן שֶׁחָלַק מַלְכוּתוֹ לְאַרְבָּעָה רָאשִׁים מִמִּשְׁפַּחְתּוֹ, הֵם אַרְבָּעָה רָאשֵׁי נָמֵר שֶׁרָאָה דָנִיֵּאל ״וַאֲרוּ חֵיוָא אָחֳרִי כִּנְמַר״ (דניאל ז:ו) ״וְלַהּ גַּפִּין אַרְבַּע דִּי עוֹף עַל גַּבַּהּ וְאַרְבְּעָה רֵאשִׁין לְחֵיוְתָא״, הִמְשִׁיל זֶה בַּמִּזְרָח וְזֶה בַּמַּעֲרָב זֶה בַּצָּפוֹן וְזֶה בַּדָּרוֹם. וְכֵן בַּחִזָּיוֹן הָרִאשׁוֹן ״וַתַּעֲלֶינָה חָזוּת אַרְבַּע תַּחְתֶּיהָ״ (דניאל ח:ח) בְּקַרְנוֹ שֶׁל צְפִיר הַשָּׂעִיר:",2,0],[11,4,"וְלֹא לְאַחֲרִיתוֹ. וְלֹא תָבֹא הַמֶּמְשָׁלָה לְבָנָיו, אֶלָּא לִבְנֵי מִשְׁפַּחְתּוֹ. אַחֲרִיתוֹ אֵינוֹ נוֹפֵל אֶלָּא עַל לְשׁוֹן בָּנִים, וְכֵן הוּא אוֹמֵר (עמוס ד:ב) ״וְנִשָּׂא אֶתְכֶם בְּצִנּוֹת וְאַחֲרִיתְכֶם בְּסִירוֹת דּוּגָה״, וְתִרְגֵּם יוֹנָתָן: ״וּבְנֵיכוֹן וּבְנָתֵיכוֹן בְּדוּגִית צַיָּדִין״:",3,0],[11,4,"וְלֹא כְמָשְׁלוֹ אֲשֶׁר מָשָׁל. וְלֹא תְהֵא מַלְכוּת שֶׁל אֵלּוּ חֲזָקָה כְּמוֹ שֶׁל אֲלֶכְסַנְדְּרוֹס:",4,0],[11,4,"כִּי תִנָּתֵשׁ מַלְכוּתוֹ. לְחַלֵּק לְאַרְבַּע רָאשִׁים הַלָּלוּ וְלַאֲחֵרִים מִלְּבַד אֵלֶּה:",5,0],[11,5,"וְיֶחֱזַק מֶלֶךְ הַנֶּגֶב. הָרֹאשׁ אֲשֶׁר יַמְלִיךְ בַּנֶּגֶב יֶחֱזַק מִן הָרֹאשׁ שֶׁכְּנֶגְדּוֹ הַמּוֹלֵךְ בַּצָּפוֹן וּמִן שָׂרָיו:",1,0],[11,6,"לַעֲשׂוֹת מֵישָׁרִים. פְּשָׁרַת שָׁלוֹם בֵּינוֹ וּבֵין אָבִיהָ:",1,0],[11,6,"וְלֹא תַעְצֹר וְגוֹ׳. וְיִלְכְּדֶנָּה מֶלֶךְ הַצָּפוֹן וְאֶת מְבִיאֶיהָ וְאֶת אָבִיהָ הַיּוֹלְדָהּ וּמַחֲזִיקָהּ בְּכָל עֵת צָרָתָהּ:",2,0],[11,6,"וְלֹא תַעְצֹר. זְרוֹעַ מְבִיאֶיהָ כֹּחַ לַעֲמֹד (וְלֹא יַעֲמֹד אָבִיהָ) לְפָנָיו, לֹא הוּא וְלֹא זְרוֹעוֹ הֵם גִּבּוֹרֵי כֹחוֹ:",3,0],[11,6,"וְתִנָּתֵן. בְּיַד מֶלֶךְ הַצָּפוֹן: הִיא וּמְבִיאֶיהָ וְהַיֹּלְדָהּ. הוּא אָבִיהָ:",4,0],[11,7,"וְעָמַד מִנֵּצֶר שָׁרָשֶׁיהָ. בֵּן יוֹשֵׁב עַל כַּנּוֹ בְּכִסֵּא הַמְּלוּכָה:",1,0],[11,7,"וַיָּבֹא אֶל הַחַיִל. אֶל מֶלֶךְ הַצָּפוֹן:",2,0],[11,7,"בִּמְעוֹז מֶלֶךְ הַצָּפוֹן. כְּלוֹמַר: בְּעָרֵי מָעוּזּוֹ בְּמִבְצָרָיו:",3,0],[11,7,"וְעָשָׂה בָהֶם. וְהִצְלִיחַ בָּהֶם:",4,0],[11,7,"וְהֶחֱזִיק. וְיִכְבּוֹשׁ אוֹתָם:",5,0],[11,8,"נְסִיכֵיהֶם. שָׂרֵיהֶם:",1,0],[11,9,"וּבָא בְּמַלְכוּת מֶלֶךְ הַנֶּגֶב. דֶּרֶךְ מַלְכוּת מֶלֶךְ הַנֶּגֶב שֶׁהִיא אֲבִי אָבִיהָ יָשׁוּב אֶל אַדְמָתוֹ וְהִיא מִצְרַיִם, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה ״בַּשְּׁבִי יָבִיא מִצְרָיִם״ (דניאל יא:ח):",1,0],[11,10,"וּבָנָיו. שֶׁל מֶלֶךְ הַצָּפוֹן יִתְגָּרוּ:",1,0],[11,10,"וּבָא בוֹא. כְּמוֹ וְהוֹלֵךְ הָלוֹךְ. בְּנוֹ שֶׁל מֶלֶךְ הַצָּפוֹן יָבוֹא בוֹ וְשָׁטַף וְעָבַר אֶל אֶרֶץ הַנֶּגֶב:",2,0],[11,10,"וְיָשֹׁב וְיִתְגָּרֶה. בְּמֶלֶךְ הַנֶּגֶב:",3,0],[11,10,"עַד מְעֻזּוֹ. עִיר מִבְצָרָיו:",4,0],[11,11,"וְיִתְמַרְמַר. וַיִּלָּחֵם בָּעָם:",1,0],[11,11,"וְנִתַּן הֶהָמוֹן. שֶׁל מֶלֶךְ הַצָּפוֹן בְּיָדוֹ:",2,0],[11,12,"וְנִשָּׂא הֶהָמוֹן. שֶׁל מֶלֶךְ צָפוֹן לְהִתְגָּאוֹת מְאֹד, כִּי יָזְמוּ בְּלִבָּם לְהִתְגַּבֵּר בַּמִּלְחָמָה:",1,0],[11,12,"וְהִפִּיל רִבּוֹאוֹת. רַבִּים בְּחֵיל מֶלֶךְ הַנֶּגֶב:",2,0],[11,12,"וְלֹא יָעוֹז. וּבְכָל זֹאת לֹא יִהְיֶה נִצָּחוֹן הַמִּלְחָמָה שֶׁלּוֹ:",3,0],[11,14,"וּבְנֵי פָרִיצֵי עַמְּךָ יִנַּשְּׂאוּ לְהַעֲמִיד חָזוֹן. רָאִיתִי בְּשֵׁם רַב סְעַדְיָה שֶׁזּוֹ פְּרִיצֵי יִשְׂרָאֵל וְסִיעָתָם:",1,0],[11,15,"וְעַם מִבְחָרָיו. יִהְיוּ בַּמִּלְחָמָה:",1,0],[11,15,"וְאֵין כֹּחַ לַעֲמֹד. מִפְּנֵי מֶלֶךְ הַצָּפוֹן. וְאַף עַל פִּי שֶׁיֵּשׁ כָּאן וָי״ו יְתֵרָה, דֶּרֶךְ מִקְרָא לְדַבֵּר כֵּן בְּלָשׁוֹן זֶה, כְּמוֹ ״חוֹרֶיהָ וְאֵין שָׁם מְלוּכָה יִקְרָאוּ״ (ישעיהו לד:יב):",2,0],[11,16,"וְיַעַשׂ. הַמֶּלֶךְ הַצָּפוֹן הַבָּא אֶל מֶלֶךְ הַנֶּגֶב כִּרְצוֹנוֹ:",1,0],[11,16,"בְּאֶרֶץ הַצְּבִי. בְּאֶרֶץ יִשְׂרָאֵל:",2,0],[11,16,"וְכָלָה בְיָדוֹ. וְכִלָּה אֶת הָאָרֶץ בְּאוּכְלוּסָיו:",3,0],[11,17,"וְיָשֵׂם פָּנָיו. מֶלֶךְ הַצָּפוֹן לָבוֹא בְּתֹקֶף כָּל מַלְכוּתוֹ שֶׁל מֶלֶךְ הַנֶּגֶב:",1,0],[11,17,"וִישָׁרִים עִמּוֹ. עִם מֶלֶךְ הַנֶּגֶב, גַּם עֲלֵיהֶם יִלָּחֵם מֶלֶךְ הַצָּפוֹן בְּאוֹתָן הַיָּמִים:",2,0],[11,17,"וְעָשָׂה. וְהִצְלִיחַ׃",3,0],[11,17,"וּבַת הַנָּשִׁים יִתֶּן לוֹ לְהַשְׁחִיתָהּ. זוֹ כְּנֶסֶת יִשְׂרָאֵל ״הַיָּפָה בַּנָּשִׁים״ (שיר השירים א:ח), יְצַוֶּה מֶלֶךְ הַצָּפוֹן לְשַׂר צְבָאוֹ לְהַשְׁחִיתָהּ. וְאוֹמֵר אֲנִי, שֶׁהוּא אַנְטִיוֹכוּס הָרָשָׁע מֶלֶךְ יָוָן, שֶׁגָּזַר גְּזֵרוֹת עַל יִשְׂרָאֵל וְצִוָּה לְפוֹלִיפוֹס שַׂר צְבָאוֹ לַהֲרֹג אֶת כָּל הַקּוֹרֵא שְׁמוֹ יְהוּדִי, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יוֹסִיפוֹן:",4,0],[11,17,"וְלֹא תַעֲמֹד. עֲצָתוֹ זֹאת:",5,0],[11,17,"וְלֹא לוֹ תִהְיֶה. בַּת הַנָּשִׁים שֶׁעָמַד מַתִּתְיָהוּ בֶּן יוֹחָנָן וּפָרַק עֻלּוֹ מֵעַל יִשְׂרָאֵל:",6,0],[11,18,"וְהִשְׁבִּית קָצִין חֶרְפָּתוֹ לוֹ. וְהִשְׁבִּית הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת גִּדּוּפוֹ וְאֶת חֶרְפָּתוֹ שֶׁהָיָה מְחָרֵף אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֶת יִשְׂרָאֵל, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יוֹסִיפוֹן; וְהֵשִׁיבוֹ עָלָיו שֶׁהִכָּהוּ בִּשְׁחִין רַע בְּעוֹדוֹ בַדֶּרֶךְ שֶׁהָלַךְ לָצוּר עַל יְרוּשָׁלַיִם וְהִסְרִיחַ בְּשָׂרוֹ וְנָשְׁרוּ אֵבָרָיו, וְאָמַר לַעֲבָדָיו לַהֲשִׁיבוֹ לְאַנְטוֹכְיָא, וְלֹא הִסְפִּיק לָבוֹא שָׁם עַד שֶׁמֵּת בְּחוֹלָיִים רָעִים:",1,0],[11,19,"לְמָעוּזֵּי אַרְצוֹ. לָשׁוּב אֶל עִיר מִבְצָרָיו:",1,0],[11,20,"וְעָמַד עַל כַּנּוֹ מַעֲבִיר נוֹגֵשׂ. וְיִתְחַזֵּק עַל בְּסִיסוֹ בְּהַר הַמּוֹדְעִית מַתִּתְיָהוּ בֶּן יוֹחָנָן הַמַּעֲבִיר נוֹגֵשׂ יָוָן מֵעַל יִשְׂרָאֵל וְגוֹ׳, וְהוּא הֶדֶר מַלְכוּת בְּיִשְׂרָאֵל, כִּי שַׂר וְגִבּוֹר יִהְיֶה הוּא וְכָל זַרְעוֹ אַחֲרָיו, בְּנֵי הַחַשְׁמוֹנִים:",1,0],[11,20,"וּבְיָמִים אֲחָדִים יִשָּׁבֵר. בְּיָמִים מוּעָטִים תִּשָּׁבֵר מַלְכוּתָם:",2,0],[11,20,"וְלֹא בְאַפַּיִם. שֶׁל אֻמָּה אַחֶרֶת:",3,0],[11,20,"וְלֹא בְמִלְחָמָה. כִּי מֵהֶם וּבָהֶם אֲשֶׁר יְקַנְּאוּ אֲרִיסְתוֹבְלוֹס וְהוֹרְקְנוֹס עַל דְּבַר הַמְּלוּכָה:",4,0],[11,21,"וְעָמַד עַל כַּנּוֹ נִבְזֶה. וְיִתְחַזֵּק אָז עַל מַעֲמָדָהּ מַלְכוּת עֵשָׂו, שֶׁנֶּאֱמַר ״בָּזוּי אַתָּה מְאֹד״ (עובדיה א:ב), וְיַעַמְדוּ רוֹמִים וְיִטְּלוּ מַלְכוּת מִיְּוָנִים:",1,0],[11,22,"וּזְרֹעוֹת הַשֶּׁטֶף. וְגִבּוֹרֵי מַלְכוּת יָוָן שֶׁהָיוּ מִלְּפָנֵיהֶם שׁוֹטְפִים וַחֲזָקִים יִשָּׁטְפוּ מִלִּפְנֵי רוֹמִיִּים וְיִשָּׁבְרוּ:",1,0],[11,22,"וְגַם נְגִיד בְּרִית. גַּם מֶלֶךְ יִשְׂרָאֵל שֶׁיִּכְרֹת עִמָּם בְּרִית גַּם הוּא סוֹפוֹ שֶׁיִּשָּׁטֵף מִלְּפָנָיו, כִּי יַעַבְרוּ (רוֹמִים) עַל הַבְּרִית וְיִפְשְׁטוּ עֲלֵיהֶם. כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (עבודה זרה ח:): עֶשְׂרִין וְשִׁית שְׁנִין קָמוּ בְּהֵמָנוּתַיְיהוּ בַּהֲדֵי יִשְׂרָאֵל, וַהֲדַר אִשְׁתַּעְבְּדוּ בְּהוֹן:",2,0],[11,23,"וּמִן הִתְחַבְּרוּת אֵלָיו יַעֲשֶׂה מִרְמָה. וּמִן הַשּׁוּתָפוּת שֶׁיִּשְׁתַּתֵּף (רוֹמִי) עִם יִשְׂרָאֵל יַעֲשֶׂה מִרְמָה, שֶׁלֹּא יְגַלֶּה מַחֲשָׁבָה רָעָה:",1,0],[11,23,"וְעָלָה. מִמְּקוֹמוֹ:",2,0],[11,23,"וְעָצַם. בְּכָל מְקוֹמוֹת שֶׁסְּבִיבוֹת אֶרֶץ יְהוּדָה, בֶּאֱדוֹם, בְּעַמּוֹן וּמוֹאָב:",3,0],[11,23,"בִּמְעַט גּוֹי. לֹא יִצְטָרֵךְ לְחַיִל כָּבֵד, כִּי יַעֲזֹר אוֹתוֹ מֶלֶךְ יְהוּדָה. וְכֵן כָּתוּב בְּסֵפֶר יוֹסִיפוֹן:",4,0],[11,24,"בִּזָּה וְשָׁלָל וּרְכוּשׁ לָהֶם יִבְזוֹר. יְחַלֵּק לְכָל הַמְקַבְּלִים עֻלּוֹ עֲלֵיהֶם, עַד שֶׁיִּכְבְּשׁוּ אֶת הַכֹּל בַּחֲנֻפָּה וּבַחֲלַקְלַקּוֹת:",1,0],[11,24,"יִבְזוֹר. כְּמוֹ יְפַזֵּר, וְכֵן ״בִּזַּר עַמִּים״ (תהלים סח:לא):",2,0],[11,24,"וְעַל מִבְצָרִים. עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת יְחַשֵּׁב מַחְשְׁבוֹתָיו לְהוֹשִׁיב בָּהֶם רָאשֵׁי גְּיָסוֹתָיו, עַד עֵת שֶׁיִּהְיֶה הַכֹּל כָּבוּשׁ תַּחְתֵּיהֶם:",3,0],[11,25,"וְלֹא יַעֲמֹד. מֶלֶךְ הַנֶּגֶב:",1,0],[11,25,"כִּי יַחְשְׁבוּ עָלָיו מַחֲשָׁבוֹת. וְיִתְנַכְּלוּ עָלָיו לְהַפִּילוֹ עַל יְדֵי שֹׁחַד, שֶׁיַּשְׁחִידוּ אֶת שָׂרָיו לִבְגֹּד בּוֹ, כְּמוֹ שֶׁהוּא מְסַיֵּם וְאוֹמֵר וְאֹכְלֵי פַת בָּגוֹ יִשְׁבְּרוּהוּ:",2,0],[11,26,"פַּת בָּגוֹ. מַאֲכָלוֹ נוֹטֵל פְּרָס מִשֻּׁלְחָנוֹ:",1,0],[11,27,"וּשְׁנֵיהֶם הַמְּלָכִים. שַׂר רוֹמִים וְנָגִיד הַבְּרִית הָאָמוּר לְמַעְלָה (דניאל יא:כב), הוּא הוֹרְקְנוֹס שֶׁיִּתְחַבֵּר לְעֶזְרָתוֹ כְּדֵי שֶׁיַּעֲזֹר גַּם הוּא עַל אַרְסְתּוֹבְּלוֹס אָחִיו הַמּוֹלֵךְ בִּירוּשָׁלַיִם:",1,0],[11,27,"לְבָבָם לְמֵרָע. עַל בְּנֵי עַמְּךָ לְהָרַע לִיהוּדָה:",2,0],[11,27,"וְעַל שֻׁלְחָן אֶחָד. עַל מַלְכוּת אַרְסְתּוֹבְּלוֹס יִתְלַחֲשׁוּ כְּזָבִים:",3,0],[11,27,"וְלֹא תִצְלָח. שֶׁיִּתְמַסְּרוּ יִשְׂרָאֵל לְהַשְׁחָתָה בְּאוֹתָן הַיָּמִים:",4,0],[11,27,"כִּי עוֹד קֵץ לַמּוֹעֵד. הַחוּרְבָּן לִמְלֹאות שָׁבוּעִים שִׁשִּׁים וּשְׁנַיִם הָאֲמוּרִים בְּסֵפֶר זֶה (דניאל ט:כה-כו), וְאוֹתוֹ הַמּוֹעֵד בִּימֵי אַגְרִיפַּס בֶּן אַגְרִיפַּס מִזֶּרַע הוֹרְדוֹס:",5,0],[11,28,"וְיָשֹׁב. מֶלֶךְ הָרוֹמִי לְאַרְצוֹ מֵעַל מֶלֶךְ הַנֶּגֶב בִּרְכוּשׁ גָּדוֹל:",1,0],[11,28,"וּלְבָבוֹ עַל בְּרִית קֹדֶשׁ. לְהָפֵר בְּרִיתוֹ מֵעַל יִשְׂרָאֵל:",2,0],[11,28,"וְעָשָׂה. כְּלוֹמַר: וְהִצְלִיחַ, וְשָׁב לְאַרְצוֹ:",3,0],[11,29,"לַמּוֹעֵד. לְאַחַר זְמַן:",1,0],[11,29,"וְלֹא תִהְיֶה. הַבִּיאָה הַזֹּאת מֻצְלַחַת כָּרִאשׁוֹנָה הָאֲמוּרָה לְמַעְלָה ״וְעָמַד מִנֵּצֶר שָׁרָשֶׁיהָ וְגוֹ׳״ (דניאל יא:ז), שֶׁהִצְלִיחַ מֶלֶךְ הַצָּפוֹן עַל מֶלֶךְ הַנֶּגֶב, וְכָאַחֲרוֹנָה פַּעַם שְׁנִיָּה זוֹ שֶׁאָמַרְנוּ וְשָׁב לְאַרְצוֹ בִּרְכוּשׁ גָּדוֹל:",2,0],[11,30,"וּבָאוּ בוֹ. לְהִלָּחֵם בּוֹ:",1,0],[11,30,"צִיִּים. סִיעוֹת:",2,0],[11,30,"כִּתִּים. רוֹמִים, גְּדוּדִים מִמַּלְכוּת רוֹמִי שֶׁיִּמְרְדוּ בּוֹ:",3,0],[11,30,"וְנִכְאָה. וְנִשְׁבָּר קְצָת:",4,0],[11,30,"וְשָׁב וְזָעַם עַל בְּרִית קֹדֶשׁ. וְשָׁב לְאַרְצוֹ לְהָפֵר בְּרִית שֶׁכָּרַת עִם יִשְׂרָאֵל:",5,0],[11,30,"וְשָׁב וְיָבֵן עַל עוֹזְבֵי בְּרִית קֹדֶשׁ. וְיִתֵּן לֵב וְיִתְבּוֹנֵן שֶׁעָזְבוּ יִשְׂרָאֵל בְּרִית קֹדֶשׁ, וְתִרְבֶּה שִׂנְאַת חִנָּם וּמַחֲלֹקֶת בְּבַיִת שֵׁנִי, כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר יוֹסִיפוֹן, וְיִשְׁפְּכוּ דָּם נָקִי, וְעַל זֹאת יִבְטַח וְיֵדַע שֶׁיַּצְלִיחַ, וְיָפֵר אֶת בְּרִיתוֹ מֵעִמָּם וְיִתְגָּרֶה בָּם:",6,0],[11,31,"וּזְרֹעִים מִמֶּנּוּ יַעֲמֹדוּ. יִשְׁלַח שָׂרָיו וְגִבּוֹרָיו לִירוּשָׁלַיִם:",1,0],[11,31,"וְחִלְּלוּ הַמִּקְדָּשׁ הַמָּעוֹז. מְעוֹן בֵּית הַמִּקְדָּשׁ:",2,0],[11,32,"וּמַרְשִׁיעֵי בְרִית יַחֲנִיף. פְּרִיצֵי יִשְׂרָאֵל שֶׁיִּתְחַבְּרוּ עִמּוֹ וְיַרְשִׁיעוּ בְּרִיתָם עִם חַבְרֵיהֶם וְיִהְיוּ מַמְרִים, יַחֲנִיף בַּחֲלַקְלַקּוֹת:",1,0],[11,32,"יוֹדְעֵי אֱלֹהָיו. וּכְשֵׁרֵי יִשְׂרָאֵל שֶׁיַּחֲזִיקוּ בְּיִרְאַת אֱלֹהֵיהֶם, כְּלוֹמַר: יֹאחֲזוּ בָהּ וְלֹא יַעַזְבוּהָ:",2,0],[11,32,"וְעָשׂוּ. אֶת תּוֹרָתָם:",3,0],[11,33,"וּמַשְׂכִּילֵי עָם. חֲכָמִים שֶׁבָּהֶם, כְּגוֹן שֶׁל בֵּית רַבִּי וְחַכְמֵי הַדּוֹרוֹת:",1,0],[11,33,"יָבִינוּ לָרַבִּים. יִדְרְשׁוּ לְעַם הָאָרֶץ אֶת הַתּוֹרָה וִיאַמְּצוּ יְדֵיהֶם לְהַחֲזִיק בָּהּ:",2,0],[11,33,"וְנִכְשְׁלוּ. בְּגָלוּתָם בְּחֶרֶב וּבְלֶהָבָה וְגוֹ׳:",3,0],[11,34,"יֵעָזְרוּ. עֵזֶר מְעַט עַל יְדֵי שֹׁחַד וּמָמוֹן שֶׁיַּעַבְדוּ אֶת אוֹיְבֵיהֶם יְסַיֵּעַ אוֹתָם בָּהֶם:",1,0],[11,35,"יִכָּשְׁלוּ לִצְרוֹף בָּהֶם. יִכָּשְׁלוּ בְּחֶשְׁבּוֹן הַקִּצִּים, שֶׁיִּתְּנוּ לֵב לְצָרְפָן וּלְלַבְּנָם לָדַעַת אוֹתָם, וְיִטְעוּ בָּהֶם:",1,0],[11,36,"וְעָשָׂה כִרְצוֹנוֹ הַמֶּלֶךְ. מַלְכוּת רוֹמִי:",1,0],[11,36,"וְהִצְלִיחַ עַד כָּלָה זַעַם. עַד שׁוּב אַף הַקָּדוֹשׁ בָּרוּךְ הוּא מִיִּשְׂרָאֵל:",2,0],[11,36,"כִּי נֶחֱרָצָה נֶעֱשָׂתָה. כְּשֶׁתִּכְלֶה גְּזֵרָתוֹ. כִּי כְּמוֹ כַּאֲשֶׁר:",3,0],[11,37,"וְעַל אֱלֹהֵי אֲבוֹתָיו לֹא יָבִין. לֹא יִתֵּן לֵב לְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אֱלֹהֵי אַבְרָהָם יִצְחָק וְיִשְׂרָאֵל אֲבוֹתָיו:",1,0],[11,37,"חֶמְדַּת נָשִׁים. כְּנֶסֶת יִשְׂרָאֵל הַיָּפָה בַּנָּשִׁים:",2,0],[11,38,"וְלֶאֱלוֹהַּ מָעֻזִּים. לֵאלֹהֵי הַכְּרוּבִים אֲשֶׁר יִכְרְתוּ עִמּוֹ בְּרִית:",1,0],[11,38,"עַל כַּנּוֹ יְכַבֵּד. כִּי יַחֲנִיף אֶת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִהְיוֹתָם כְּבוּשִׁים לוֹ:",2,0],[11,39,"וְעָשָׂה. בִּנְיָנִים:",1,0],[11,39,"לְמִבְצְרֵי מָעֻזִּים עִם אֱלוֹהַּ נֵכָר. כְּלוֹמַר: לִכְבוֹד אֱלֹהֵי נֵכָר. אֲשֶׁר הִכִּיר:",2,0],[11,39,"יַרְבֶּה כָבוֹד. אֶת הַשָּׂרִים אֲשֶׁר יִרְאֶה בַּלֵּב לְהַכִּיר פְּנֵיהֶם וּלְהַחֲנִיף יַרְבֶּה לָהֶם כָבוֹד:",3,0],[11,39,"וַאֲדָמָה יְחַלֵּק. לָהֶם׃",4,0],[11,39,"בִּמְחִיר. בְּדָמִים קַלִּים׃",5,0],[11,40,"וּבְעֵת קֵץ. כְּשֶׁתִּקְרַב גְּאֻלָּתֵינוּ:",1,0],[11,40,"וְיִשְׂתָּעֵר עָלָיו מֶלֶךְ הַצָּפוֹן. עַל מֶלֶךְ הַנֶּגֶב:",2,0],[12,1,"וּבָעֵת הַהִיא יַעֲמֹד מִיכָאֵל. יִשְׁתַּתֵּק כְּאִלֵּם, שֶׁיִּרְאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן בְּעַצְמוֹ וְאוֹמֵר: הֵיאַךְ אֲאַבֵּד אֻמָּה גְּדוֹלָה כָּזוֹ בִּשְׁבִיל יִשְׂרָאֵל:",1,0],[12,1,"וְהָיְתָה עֵת צָרָה. בְּפַמַלְיָא שֶׁל מַעְלָה, וְקָטֵיגוֹרְיָא בְּתַלְמִידֵי חֲכָמִים: בָּזוּזֵי וּבָזוּזֵי דְּבָזוּזֵי, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בַּהַגָּדָה בְּפֶרֶק אַחֲרוֹן שֶׁל כְּתֻבּוֹת (כתובות קיב:):",2,0],[12,1,"יִמָּלֵט עַמְּךָ. תֹּאבַד מַלְכוּת אֲרָם, וְיִמָּלְטוּ יִשְׂרָאֵל:",3,0],[12,1,"כָּל הַנִּמְצָא כָתוּב בַּסֵּפֶר. הֲרֵי זֶה מִקְרָא קָצָר: כָּל הַנִּמְצָא כָתוּב בַּסֵּפֶר זֶה, עַל יְדֵי הַחֲלוֹמוֹת הַכְּתוּבִים בּוֹ, ״עַד דִּקְטִילַת חֵיוְתָא וִיקַבְּלוּן מַלְכוּתָא קַדִּישֵׁי עֶלְיוֹנִין״ (דניאל ז:יא,יח), הַכֹּל יִתְקַיֵּם:",4,0],[12,2,"וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. יִחְיוּ הַמֵּתִים:",1,0],[12,3,"וְהַמַּשְׂכִּילִים. שֶׁעָסְקוּ בַּתּוֹרָה וּבַמִּצְווֹת יַזְהִירוּ כְּזֹהַר הָרָקִיעַ:",1,0],[12,7,"וּכְכַלּוֹת נַפֵּץ יַד עַם קֹדֶשׁ. כְּשֶׁתִּכְלֶה כֹּחַ יִשְׂרָאֵל, כִּי ״אָזְלַת יָד וְאֶפֶס עָצוּר וְעָזוּב״ (דברים לב:לו):",1,0],[12,8,"וְלֹא אָבִין. לֹא יָדַעְתִּי מַהוּ מוֹעֵד מוֹעֲדִים וָחֵצִי:",1,0],[12,8,"מָה אַחֲרִית אֵלֶּה. סוֹף הַחֶשְׁבּוֹנוֹת הַלָּלוּ:",2,0],[12,9,"עַד עֵת קֵץ. עַד אֲשֶׁר תִּקְרַב הַגְּאֻלָּה:",1,0],[12,10,"יִתְבָּרְרוּ וְיִתְלַבְּנוּ. הַחֶשְׁבּוֹנוֹת הָאֵלֶּה:",1,0],[12,10,"וְיִצָּרְפוּ. בָּהֶם רַבִּים לַהֲבִינָם:",2,0],[12,10,"וְהִרְשִׁיעוּ רְשָׁעִים. אֶת הַחֶשְׁבּוֹנוֹת, לְחַשְּׁבָם שֶׁלֹּא כַּמִּשְׁפָּט, וּכְשֶׁיִּכְלוּ יֹאמְרוּ: אֵין עוֹד גְּאֻלָּה:",3,0],[12,10,"וְלֹא יָבִינוּ. אוֹתָם כָּל רְשָׁעִים:",4,0],[12,10,"וְהַמַּשְׂכִּילִים יָבִינוּ. אוֹתָהּ בְּבֹא עֵת קֵץ:",5,0],[12,11,"וּמֵעֵת הוּסַר הַתָּמִיד. כְּדֵי לָתֵת שִׁקּוּץ מְשׁוֹמֵם תַּחְתָּיו. יָמִים אֶלֶף וּמָאתַיִם וְתִשְׁעִים שָׁנָה הֵן מִיּוֹם הוּסַר הַתָּמִיד עַד שֶׁיָּשׁוּב בִּימֵי מְשִׁיחֵנוּ. וְחֶשְׁבּוֹן זֶה מְכֻוָּן עִם חֶשְׁבּוֹן ״עֶרֶב בֹּקֶר אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת״ (דניאל ח:יד) מִיּוֹם גָּלוּתָם לְמִצְרַיִם עַד גְּאֻלָּה אַחֲרוֹנָה: גָּלוּת מִצְרַיִם מָאתַיִם וְעֶשֶׂר, מִיּוֹם צֵאתָם עַד בִּנְיַן בַּיִת רִאשׁוֹן אַרְבַּע מֵאוֹת וּשְׁמוֹנִים, יְמֵי הַבִּנְיָן אַרְבַּע מֵאוֹת וְעֶשֶׂר, גָּלוּת בָּבֶל שִׁבְעִים שָׁנָה, יְמֵי בַיִת שֵׁנִי אַרְבַּע מֵאוֹת וְעֶשְׂרִים, הֲרֵי אֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים, וְהַתָּמִיד הוּסַר לִפְנֵי הַחֻרְבָּן שֵׁשׁ שָׁנִים הֲרֵי מִיּוֹם גָּלוּתָם לְמִצְרַיִם עַד הוּסַר הַתָּמִיד אֶלֶף וַחֲמֵשׁ מֵאוֹת וּשְׁמוֹנִים וְאַרְבַּע, הוֹסִיף עֲלֵיהֶם אֶלֶף מָאתַיִם וְתִשְׁעִים הֲרֵי אַלְפַּיִם וּשְׁמֹנֶה מֵאוֹת וְשִׁבְעִים וְאַרְבַּע כְּמִנְיַן עֶרֶב בֹּקֶר בְּגִימַטְרִיָּא, אַלְפַּיִם וּשְׁלֹשׁ מֵאוֹת:",1,0],[12,12,"אַשְׁרֵי הַמְחַכֶּה וְגוֹ׳. אַרְבָּעִים וְחָמֵשׁ שָׁנִים נוֹסָפִים עַל חֶשְׁבּוֹן הָעֶלְיוֹן, שֶׁעָתִיד מְשִׁיחֵנוּ לְהִתְכַּסּוֹת אַחַר שֶׁנִּגְלָה, וְיָשׁוּב וְיִתְגַּלֶּה. וְכֵן מָצִינוּ בְּמִדְרַשׁ רוּת, וְכֵן יִסַּד רַבִּי אֱלִיעֶזֶר הַקַּלִּיר (בְּסִלּוּק יוֹצֵר פָּרָשַׁת הַחֹדֶשׁ): וְיִתְכַּסֶּה מֵהֶם שְׁבוּעִים שִׁשָּׁה:",1,0],[12,13,"לֵךְ לַקֵּץ. תִּפָּטֵר לְבֵית עוֹלָמְךָ:",1,0],[12,13,"לְגוֹרָלְךָ. לְקַבֵּל חֶלְקְךָ עִם הַצַּדִּיקִים:",2,0],[12,13,"לְקֵץ הַיָּמִין. כְּמוֹ בְּאַחֲרִית הַיָּמִים. וְאֵין לְפָרֵשׁ הַיָּמִין לְשׁוֹן יָד הַיְמָנִית, שֶׁהֲרֵי הוּא מָנוּי בַּמָּסֹרֶת הַגְּדוֹלָה בְּשִׁיטַת תֵּיבוֹת הַמְיֻחָדִין בְּנוּ״ן זְקוּפָה בְּסוֹף תֵּיבָה הַמְשַׁמֶּשֶׁת בִּמְקוֹם מֵ״ם וְלֵית דְּכָוָתֵיהוֹן, כְּגוֹן ״וְעָלֶיהָ יִכְרְעוּן אָחֳרִין״ (איוב לא:י), ״יָקוּם וְלֹא יַאֲמִין בְּחַיִּין״ (איוב כד:כב), ״קַח לְךָ חִטִּין״ (יחזקאל ד:ט), ״יֶחֱרָדוּן אִיִּין״ (יחזקאל כו:יח), ״לִמְחוֹת מְלָכִין״ (משלי לא:ג), לְקֵץ הַיָּמִין (כאן), (וְעַיֵּן רש״י פְּסָחִים נו. דִּבּוּר הַמַּתְחִיל לְקֵץ הַיָּמִין וְעַיֵּן רש״י סַנְהֶדְרִין צב. דִּבּוּר הַמַּתְחִיל לֵךְ לְקֵץ וְכוּ׳ וּקְצָת צָרִיךְ עִיּוּן):",3,0]]);
